            const SizedBox(height: 8),
            _field('Magaca imtixaanka', _examNameSo, hint: 'IMTIXAAN BILEEDKA'),
            _field('Wakhtiga la ogol yahay', _timeSo,
                hint: 'HAL SAAC IYO 20 DAQIIQO OO AKHRIS AH'),
