const kBlue = Color(0xFF3498DB);
const kGreen = Color(0xFF2ECC71);
const kRed = Color(0xFFE74C3C);

/// App-bar button: downloads all uploaded exams as <year>.zip
/// (year folder > subject folders > exam files).
class _DownloadAllButton extends StatefulWidget {
  final ExamService service;
  const _DownloadAllButton({required this.service});

  @override
  State<_DownloadAllButton> createState() => _DownloadAllButtonState();
}

class _DownloadAllButtonState extends State<_DownloadAllButton> {
  bool _busy = false;

  Future<void> _run() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final n = await widget.service.downloadAll();
      messenger.showSnackBar(
          SnackBar(content: Text('Downloaded $n exam files in ${DateTime.now().year}.zip')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(content: Text('$e')));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_busy) {
      return const Padding(
        padding: EdgeInsets.symmetric(horizontal: 12),
        child: Center(
          child: SizedBox(
              width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2)),
        ),
      );
    }
    return IconButton(
      tooltip: 'Download all exams (ZIP)',
      icon: const Icon(Icons.folder_zip),
      onPressed: _run,
    );
  }
}

/// App-bar button: re-uploads a ZIP made by "Download all exams".
/// Every file goes back into its own Subject / Form cell in one go.
class _UploadAllButton extends StatefulWidget {
  final ExamService service;
  const _UploadAllButton({required this.service});

  @override
  State<_UploadAllButton> createState() => _UploadAllButtonState();
}

class _UploadAllButtonState extends State<_UploadAllButton> {
  bool _busy = false;
  String? _progress;

  Future<void> _run() async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      final res = await FilePicker.platform.pickFiles(
        withData: true,
        type: FileType.custom,
        allowedExtensions: ['zip'],
      );
      if (res == null || res.files.isEmpty) return;
      final bytes = res.files.first.bytes;
      if (bytes == null) throw Exception('Could not read the ZIP file.');

      setState(() {
        _busy = true;
        _progress = 'Reading...';
      });
      final plan = widget.service.planZipImport(bytes);
      if (!mounted) return;
      setState(() => _busy = false);

      if (plan.items.isEmpty) {
        throw Exception('No exam files were found in this ZIP.'
            '${plan.skipped.isEmpty ? '' : '\n${plan.skipped.take(3).join('\n')}'}');
      }
      final ok = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('Re-upload all exams'),
          content: SizedBox(
            width: 420,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('${plan.items.length} file(s) will be saved and will '
                      'REPLACE the current files in these cells:'),
                  const SizedBox(height: 8),
                  for (final it in plan.items)
                    Text('• ${it.subject} – ${it.form}   (${it.fileName})',
                        style: const TextStyle(fontSize: 12)),
                  if (plan.skipped.isNotEmpty) ...[
                    const SizedBox(height: 12),
                    Text('${plan.skipped.length} file(s) skipped:',
                        style: const TextStyle(
                            fontWeight: FontWeight.bold, color: kRed)),
                    for (final s in plan.skipped)
                      Text('• $s', style: const TextStyle(fontSize: 12)),
                  ],
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('Cancel')),
            FilledButton(
                onPressed: () => Navigator.pop(ctx, true),
                child: const Text('Upload all')),
          ],
        ),
      );
      if (ok != true || !mounted) return;

      setState(() {
        _busy = true;
        _progress = '0/${plan.items.length}';
      });
      final r = await widget.service.applyZipImport(plan, onProgress: (d, t) {
        if (mounted) setState(() => _progress = '$d/$t');
      });
      messenger.showSnackBar(SnackBar(
        content: Text(r.failed.isEmpty
            ? 'Uploaded ${r.saved} exam file(s).'
            : 'Uploaded ${r.saved}. Failed: ${r.failed.join(', ')}'),
      ));
    } catch (e) {
      messenger.showSnackBar(
          SnackBar(content: Text('$e'.replaceFirst('Exception: ', ''))));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_busy) {
      return Padding(
        padding: const EdgeInsets.symmetric(horizontal: 12),
        child: Center(
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            const SizedBox(
                width: 20,
                height: 20,
                child: CircularProgressIndicator(strokeWidth: 2)),
            if (_progress != null) ...[
              const SizedBox(width: 6),
              Text(_progress!, style: const TextStyle(fontSize: 12)),
            ],
          ]),
        ),
      );
    }
    return IconButton(
      tooltip: 'Re-upload all exams (ZIP)',
      icon: const Icon(Icons.drive_folder_upload),
      onPressed: _run,
    );
  }
}


/// Makes [exam] the active exam (asks first). It is opened, the other exams
/// are closed, and the Exam Manager table shows the papers and exam dates of
/// that exam. The first time, the admin says which exam the papers saved so
/// far belong to.
Future<void> switchActiveExam(BuildContext context, String exam) async {
  final s = appSettings.value;
  if (exam == s.currentExam && s.activeExam == exam) return;
  final messenger = ScaffoldMessenger.of(context);
  final needBase = s.paperBaseExam.isEmpty && exam != s.currentExam;
  var base = s.currentExam;
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => StatefulBuilder(
      builder: (ctx, setD) => AlertDialog(
        title: Text('Make "$exam" the active exam?'),
        content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text('"$exam" is opened for teachers and students and the other '
                  'exams are closed. The Exam Manager table (papers received, '
                  'exam dates) is kept separately for each exam.'),
              if (needBase) ...[
                const SizedBox(height: 14),
                const Text('The papers saved in Exam Manager so far belong to:',
                    style: TextStyle(fontWeight: FontWeight.w600)),
                DropdownButton<String>(
                  isExpanded: true,
                  value: s.examOptions.contains(base) ? base : null,
                  items: [
                    for (final e in s.examOptions)
                      DropdownMenuItem(value: e, child: Text(e)),
                  ],
                  onChanged: (v) => setD(() => base = v ?? base),
                ),
              ],
            ]),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Make active')),
        ],
      ),
    ),
  );
  if (ok != true) return;
  try {
    await appSettings.update({
      'activeExam': exam,
      'closedExams': [for (final e in s.examOptions) if (e != exam) e],
      if (needBase) 'paperBaseExam': base,
    });
    messenger.showSnackBar(
        SnackBar(content: Text('"$exam" is now the active exam')));
  } catch (e) {
    messenger.showSnackBar(SnackBar(
        content: Text('Failed: ${'$e'.replaceFirst('Exception: ', '')}')));
  }
}

/// Bar above the Exam Manager table: the exams, the active one highlighted.
/// An administrator taps another exam to make it active.
class _ExamSwitchBar extends StatelessWidget {
  final AppSettings settings;
  const _ExamSwitchBar({required this.settings});

  @override
  Widget build(BuildContext context) {
    final cur = settings.currentExam;
    return ValueListenableBuilder<TeacherScope>(
      valueListenable: teacherScope,
      builder: (context, sc, _) {
        final canSwitch = !sc.scoped && !sc.isStudent;
        return Container(
          width: double.infinity,
          color: Colors.white,
          padding: const EdgeInsets.fromLTRB(16, 10, 16, 10),
          child: Wrap(
            spacing: 8,
            runSpacing: 6,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              const Icon(Icons.event_note, size: 20, color: kBlue),
              Text(canSwitch ? 'Active exam:' : 'Exam:',
                  style: const TextStyle(fontWeight: FontWeight.w700)),
              for (final e in settings.examOptions)
                ChoiceChip(
                  label: Text(e),
                  selected: e == cur,
                  onSelected: canSwitch && e != cur
                      ? (_) => switchActiveExam(context, e)
                      : null,
                ),
            ],
          ),
        );
      },
    );
  }
}

class ExamTableScreen extends StatelessWidget {
  const ExamTableScreen({super.key});

  /// Every teacher chosen (from the Teachers tab) for a Pending exam gets one
  /// notification, sent directly to their user account.
  Future<void> _remindPending(BuildContext context, ExamService service) async {
    final messenger = ScaffoldMessenger.of(context);
    void say(String t) => messenger.showSnackBar(SnackBar(content: Text(t)));
    try {
      final data = await service.watchAll().first;
      final byTeacher = <String, List<ExamRecord>>{};
      for (final r in data.values) {
        if (!r.received && r.teacherId.isNotEmpty) {
          byTeacher.putIfAbsent(r.teacherId, () => []).add(r);
        }
      }
      if (byTeacher.isEmpty) {
        say('No pending exam has a teacher chosen from the Teachers tab.');
        return;
      }
      var sent = 0;
      final missing = <String>[];
      for (final e in byTeacher.entries) {
        final list = e.value;
        final what = [for (final r in list) '${r.subject} (${r.form})'].join(', ');
        final ok = await notifyTeacherUser(
          teacherId: e.key,
          subject: list.first.subject,
          form: list.first.form,
          title: 'Imtixaanka la sugayo',
          body: 'Fadlan macalin, weli lama helin imtixaanka: $what.',
        );
        if (ok) {
          sent++;
        } else {
          missing.add(list.first.teacherName);
        }
      }
      say(missing.isEmpty
          ? 'Reminder sent to $sent teacher${sent == 1 ? '' : 's'}.'
          : 'Sent to $sent. No user account for: ${missing.join(', ')}.');
    } catch (e) {
      say('Failed: $e');
    }
  }

  @override
  Widget build(BuildContext context) {
    final service = ExamService();
    return Scaffold(
      appBar: AppBar(
        title: const Text('Exam Manager'),
        actions: [
          const AccountBadge(),
          _DownloadAllButton(service: service),
          _UploadAllButton(service: service),
          if (!teacherScope.value.scoped)
            IconButton(
              tooltip: 'Remind the teachers of pending exams',
              icon: const Icon(Icons.notifications_active_outlined),
              onPressed: () => _remindPending(context, service),
            ),
          IconButton(
            tooltip: 'School letterhead (general header)',
            icon: const Icon(Icons.image),
            onPressed: () => showDialog(
              context: context,
              builder: (_) => LetterheadDialog(service: service),
            ),
          ),
          IconButton(
            tooltip: 'Exam heading (general)',
            icon: const Icon(Icons.edit_note),
            onPressed: () => showDialog(
              context: context,
              builder: (_) => ExamHeadingDialog(service: service),
            ),
          ),
          IconButton(
            tooltip: 'Change password',
            icon: const Icon(Icons.lock_reset),
            onPressed: () => showChangePasswordDialog(context),
          ),
          IconButton(
            tooltip: 'Sign out',
            icon: const Icon(Icons.logout),
            onPressed: () => _signOut(context),
          ),
          const SizedBox(width: 8),
        ],
      ),
      body: ValueListenableBuilder<AppSettings>(
        valueListenable: appSettings,
        builder: (context, st, _) => Column(children: [
          _ExamSwitchBar(settings: st),
          Expanded(
            child: StreamBuilder<Map<String, ExamRecord>>(
              stream: service.watchAll(),
              builder: (context, snap) {
                if (snap.hasError) {
                  return Center(child: Text('Error: ${snap.error}'));
                }
                if (!snap.hasData) {
                  return const Center(child: CircularProgressIndicator());
                }
                final data = snap.data!;
                return ValueListenableBuilder<TeacherScope>(
                  valueListenable: teacherScope,
                  builder: (context, sc, _) {
                    if (sc.subjectList.isEmpty || sc.formList.isEmpty) {
                      return const Center(
                        child: Padding(
                          padding: EdgeInsets.all(24),
                          child: Text(
                              'No subjects or forms are set on your account.\n'
                                  'Ask the administrator to add them in Teachers.',
                              textAlign: TextAlign.center),
                        ),
                      );
                    }
                    return SingleChildScrollView(
                      padding: const EdgeInsets.all(16),
                      child: SingleChildScrollView(
                        scrollDirection: Axis.horizontal,
                        child: Card(
                          clipBehavior: Clip.antiAlias,
                          child: ValueListenableBuilder<AppSettings>(
                            valueListenable: appSettings,
                            builder: (_, __, ___) =>
                                _buildTable(context, service, data, sc),
                          ),
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ]),
      ),
    );
  }

  Widget _buildTable(BuildContext context, ExamService service,
      Map<String, ExamRecord> data, TeacherScope sc) {
    const subjectWidth = 130.0;
    const dateWidth = 150.0;
    const cellWidth = 220.0;
    // only someone who sees every subject can set the exam dates
    final canSetDates = !sc.restricted && !sc.isStudent;

    final header = Container(
      color: kBlue,
      padding: const EdgeInsets.symmetric(vertical: 16),
      child: Row(children: [
        const SizedBox(
          width: subjectWidth,
          child: Padding(
            padding: EdgeInsets.only(left: 12),
            child: Text('Subject', style: _headStyle),
          ),
        ),
        const SizedBox(
          width: dateWidth,
          child: Text('Exam date', style: _headStyle),
        ),
        for (final f in sc.formList)
          SizedBox(
            width: cellWidth,
            child: Padding(
              padding: const EdgeInsets.only(left: 12),
              child: Text(f, style: _headStyle),
            ),
          ),
      ]),
    );

    final rows = [
      for (final s in sc.subjectList)
        Container(
          decoration: const BoxDecoration(
            border: Border(bottom: BorderSide(color: Color(0xFFE0E0E0))),
          ),
          padding: const EdgeInsets.symmetric(vertical: 10),
          child: Row(children: [
            SizedBox(
              width: subjectWidth,
              child: Padding(
                padding: const EdgeInsets.only(left: 12),
                child: Text(s, style: const TextStyle(fontSize: 16)),
              ),
            ),
            SizedBox(
              width: dateWidth,
              child: _SubjectDateCell(subject: s, canEdit: canSetDates),
            ),
            for (final f in sc.formList)
              SizedBox(
                width: cellWidth,
                child: !sc.allows(s, f)
                    ? const Center(
                    child: Text('—',
                        style: TextStyle(color: Colors.black26, fontSize: 18)))
                    : _ExamCell(
                  record:
                  data[ExamRecord.idFor(s, f)] ?? ExamRecord.empty(s, f),
                  service: service,
                ),
              ),
          ]),
        ),
    ];

    return Column(crossAxisAlignment: CrossAxisAlignment.start,
        children: [header, ...rows]);
  }

  static const _headStyle =
  TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 16);
}

/// Exam date of one subject (Exam tab). Tap to set or change it. The result
/// deadline of the subject is this date + the days set in Settings.
class _SubjectDateCell extends StatelessWidget {
  final String subject;
  final bool canEdit;
  const _SubjectDateCell({required this.subject, required this.canEdit});

  Future<void> _pick(BuildContext context) async {
    final messenger = ScaffoldMessenger.of(context);
    final cur = appSettings.value.subjectDateOf(subject);
    final now = DateTime.now();
    final picked = await showDatePicker(
      context: context,
      initialDate: cur ?? now,
      firstDate: DateTime(now.year - 2),
      lastDate: DateTime(now.year + 3),
      helpText: 'Exam date of $subject',
    );
    if (picked == null) return;
    try {
      await appSettings.update({
        'subjectDates': {
          appSettings.value.dateKey(subject):
          DateFormat('yyyy-MM-dd').format(picked)
        }
      });
    } catch (e) {
      messenger.showSnackBar(SnackBar(
          content: Text('Failed: ${'$e'.replaceFirst('Exception: ', '')}')));
    }
  }

  Future<void> _clear(BuildContext context) async {
    final messenger = ScaffoldMessenger.of(context);
    try {
      await appSettings.update({
        'subjectDates': {appSettings.value.dateKey(subject): FieldValue.delete()}
      });
    } catch (e) {
      messenger.showSnackBar(SnackBar(
          content: Text('Failed: ${'$e'.replaceFirst('Exception: ', '')}')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final date = appSettings.value.subjectDateOf(subject);
    if (date == null) {
      return Align(
        alignment: Alignment.centerLeft,
        child: canEdit
            ? TextButton.icon(
          onPressed: () => _pick(context),
          icon: const Icon(Icons.event, size: 16),
          label: const Text('Set date'),
        )
            : const Text('—',
            style: TextStyle(color: Colors.black26, fontSize: 18)),
      );
    }
    return Row(children: [
      InkWell(
        onTap: canEdit ? () => _pick(context) : null,
        borderRadius: BorderRadius.circular(6),
        child: Padding(
          padding: const EdgeInsets.symmetric(vertical: 6, horizontal: 4),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            const Icon(Icons.event, size: 16, color: kBlue),
            const SizedBox(width: 6),
            Text(DateFormat('d MMM yyyy').format(date),
                style: const TextStyle(
                    fontSize: 13.5, fontWeight: FontWeight.w600)),
          ]),
        ),
      ),
      if (canEdit)
        IconButton(
          tooltip: 'Remove the exam date',
          visualDensity: VisualDensity.compact,
          iconSize: 16,
          icon: const Icon(Icons.close),
          onPressed: () => _clear(context),
        ),
    ]);
  }
}

class _ExamCell extends StatelessWidget {
  final ExamRecord record;
  final ExamService service;
  const _ExamCell({required this.record, required this.service});

  @override
  Widget build(BuildContext context) {
    final received = record.received;
    final row = Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        if (received && record.receivedAt != null)
          Padding(
            padding: const EdgeInsets.only(right: 6),
            child: Text(
              DateFormat('MM/dd/yyyy').format(record.receivedAt!),
              style: const TextStyle(fontSize: 12, color: Colors.black54),
            ),
          ),
        // The status button IS the upload button.
        ElevatedButton.icon(
          onPressed: () => showDialog(
            context: context,
            builder: (_) => UploadDialog(record: record, service: service),
          ),
          icon: Icon(received ? Icons.check : Icons.upload_file, size: 16),
          label: Text(received ? 'Received' : 'Pending'),
          style: ElevatedButton.styleFrom(
            backgroundColor: received ? kGreen : kRed,
            foregroundColor: Colors.white,
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            minimumSize: const Size(0, 34),
            shape:
            RoundedRectangleBorder(borderRadius: BorderRadius.circular(4)),
          ),
        ),
      ],
    );
    if (record.teacherName.isEmpty) return row;
    return Column(mainAxisSize: MainAxisSize.min, children: [
      row,
      const SizedBox(height: 2),
      Text(record.teacherName,
          style: const TextStyle(fontSize: 11, color: Colors.black54)),
    ]);
  }
}

// ======================= ASSIGNMENTS =======================
//
// Works like the Exam tab (subject rows x form columns, one button per
// cell, school letterhead + footer added to every uploaded file), but each
// button holds ANY NUMBER of assignments instead of one file.
// Firestore: assignments/{id} (details) and assignmentFiles/{id} (the file).

class AssignmentRecord {
  final String id, subject, form, title, teacherName, fileName;
  final int size;
  final DateTime? createdAt;
  const AssignmentRecord({
    required this.id,
    required this.subject,
    required this.form,
    required this.title,
    this.teacherName = '',
    this.fileName = '',
    this.size = 0,
    this.createdAt,
  });

  static String keyFor(String subject, String form) => '${subject}_$form';

  factory AssignmentRecord.fromDoc(
      QueryDocumentSnapshot<Map<String, dynamic>> d) {
    final m = d.data();
    return AssignmentRecord(
      id: d.id,
      subject: '${m['subject'] ?? ''}',
      form: '${m['form'] ?? ''}',
      title: '${m['title'] ?? ''}',
      teacherName: '${m['teacherName'] ?? ''}',
      fileName: '${m['fileName'] ?? ''}',
      size: (m['size'] as num?)?.toInt() ?? 0,
      createdAt: (m['createdAt'] as Timestamp?)?.toDate(),
    );
  }
}

/// Teacher, marks and allowed time saved for one subject + form button
/// (same details the Exam tab keeps per button).
class AssignmentDetails {
  final String teacherName, marks, allowedTime;
  const AssignmentDetails(
      {this.teacherName = '', this.marks = '', this.allowedTime = ''});

  factory AssignmentDetails.fromMap(Map<String, dynamic> m) =>
      AssignmentDetails(
        teacherName: '${m['teacherName'] ?? ''}',
        marks: '${m['marks'] ?? ''}',
        allowedTime: '${m['allowedTime'] ?? ''}',
      );
}

class AssignmentService {
  final _db = FirebaseFirestore.instance;

  /// Reused for the school letterhead, the stamping of the files and the
  /// preview, so assignments look exactly like the exam papers.
  final ExamService exams = ExamService();

  CollectionReference<Map<String, dynamic>> get _meta =>
      _db.collection('assignments');
  CollectionReference<Map<String, dynamic>> get _files =>
      _db.collection('assignmentFiles');

  static void _sortOldestFirst(List<AssignmentRecord> l) {
    final far = DateTime.now().add(const Duration(days: 1));
    l.sort((a, b) => (a.createdAt ?? far).compareTo(b.createdAt ?? far));
  }

  /// All assignments, grouped by "subject_form" (oldest first).
  Stream<Map<String, List<AssignmentRecord>>> watchAll() =>
      _meta.snapshots().map((s) {
        final out = <String, List<AssignmentRecord>>{};
        for (final d in s.docs) {
          final r = AssignmentRecord.fromDoc(d);
          (out[AssignmentRecord.keyFor(r.subject, r.form)] ??= []).add(r);
        }
        for (final l in out.values) {
          _sortOldestFirst(l);
        }
        return out;
      });

  /// The assignments of one subject + form button (oldest first).
  Stream<List<AssignmentRecord>> watchFor(String subject, String form) =>
      _meta.where('subject', isEqualTo: subject).snapshots().map((s) {
        final l = [
          for (final d in s.docs)
            if ('${d.data()['form']}' == form) AssignmentRecord.fromDoc(d),
        ];
        _sortOldestFirst(l);
        return l;
      });

  /// Same footer as the exams: Subject | Form | Teacher.
  static String footerFor(String subject, String form, String teacher) {
    final t = teacher.replaceAll('Teacher: ', '').replaceAll('Teacher:', '').trim();
    return t.isEmpty ? '' : '$subject | $form | $t';
  }

  static String _clean(String v) => v
      .trim()
      .replaceAll(RegExp(r'[\\/:*?"<>|]'), '')
      .replaceAll(RegExp(r'\s+'), '_');

  static String _extOf(String name) {
    final dot = name.lastIndexOf('.');
    return dot >= 0 ? name.substring(dot) : '';
  }

  // ---------------- Per-button details ----------------
  DocumentReference<Map<String, dynamic>> get _details =>
      _db.collection('settings').doc('assignmentDetails');

  /// Live map "subject_form" -> saved teacher / marks / time.
  Stream<Map<String, AssignmentDetails>> watchDetails() =>
      _details.snapshots().map((d) {
        final m = d.data() ?? {};
        return {
          for (final e in m.entries)
            if (e.value is Map)
              e.key: AssignmentDetails.fromMap(
                  Map<String, dynamic>.from(e.value as Map)),
        };
      });

  Future<AssignmentDetails> getDetails(String subject, String form) async {
    final v = (await _details.get()).data()?[AssignmentRecord.keyFor(subject, form)];
    return v is Map
        ? AssignmentDetails.fromMap(Map<String, dynamic>.from(v))
        : const AssignmentDetails();
  }

  /// Saves only the teacher name, footer, marks and time (no file needed).
  Future<void> saveDetails(String subject, String form,
      {required String teacher, String marks = '', String allowedTime = ''}) {
    return _details.set({
      AssignmentRecord.keyFor(subject, form): {
        'teacherName': teacher,
        'footer': footerFor(subject, form, teacher),
        'marks': marks,
        'allowedTime': allowedTime,
      },
    }, SetOptions(merge: true));
  }

  /// Deletes every assignment of one button (it goes back to Pending).
  Future<void> deleteAll(String subject, String form) async {
    final snap = await _meta.where('subject', isEqualTo: subject).get();
    for (final d in snap.docs) {
      if ('${d.data()['form']}' != form) continue;
      try {
        await _files.doc(d.id).delete();
      } catch (_) {}
      await d.reference.delete();
    }
  }

  /// Stamps the general letterhead + footer on the file and saves it as one
  /// more assignment of this subject and form.
  Future<void> upload({
    required String subject,
    required String form,
    required String title,
    required String teacher,
    required PlatformFile file,
    String marks = '',
    String allowedTime = '',
    bool addHeading = true,
    bool autoFormat = true,
    bool numberQuestions = true,
    void Function(String status)? onStatus,
  }) async {
    final letterhead = await exams.getLetterhead();
    if (letterhead == null) {
      throw Exception(
          'No school letterhead yet. Tap the image icon at the top to upload it first.');
    }
    final bytes = file.bytes;
    if (bytes == null) throw Exception('Could not read file bytes.');
    final isDocx = (file.extension ?? '').toLowerCase() == 'docx';
    final footer = footerFor(subject, form, teacher);

    onStatus?.call('Adding letterhead, heading and footer...');
    final ExamHeadingText? heading = addHeading
        ? (await exams.getHeading())
        .build(subject, form, marks: marks, time: allowedTime)
        : null;
    final Uint8List stamped = isDocx
        ? await exams.stampDocx(
        docx: bytes,
        letterhead: letterhead,
        footer: footer,
        heading: heading,
        autoFormat: autoFormat,
        numberQuestions: numberQuestions)
        : await exams.stampDocument(
        file: file,
        letterhead: letterhead,
        footer: footer,
        heading: heading);

    final baseName = file.name.replaceAll(RegExp(r'\.[^.]+$'), '');
    final fileName = isDocx ? file.name : '$baseName.pdf';
    final kb = (stamped.length / 1024).round();
    if (stamped.length > ExamService.maxFileBytes) {
      throw Exception(
          'File is too large ($kb KB after adding the letterhead). The limit is 700 KB. '
              'Please compress the file or use a smaller letterhead image.');
    }

    onStatus?.call('Saving $kb KB...');
    final uid = FirebaseAuth.instance.currentUser?.uid;
    final ref = _meta.doc();
    await _files.doc(ref.id).set({
      'fileName': fileName,
      'contentType': isDocx ? ExamService._docxMime : 'application/pdf',
      'dataBase64': base64Encode(stamped),
      'size': stamped.length,
      'updatedBy': uid,
      'updatedAt': FieldValue.serverTimestamp(),
    }).timeout(const Duration(seconds: 40), onTimeout: () {
      throw Exception(
          'Saving timed out. Check the internet connection and the Firestore rules '
              '(collection "assignmentFiles").');
    });
    await ref.set({
      'subject': subject,
      'form': form,
      'title': title,
      'teacherName': teacher,
      'footer': footer,
      'marks': marks,
      'allowedTime': allowedTime,
      'fileName': fileName,
      'size': stamped.length,
      'createdBy': uid,
      'createdAt': FieldValue.serverTimestamp(),
    });
    // Remember the teacher / marks / time for this button (like the exams).
    try {
      await saveDetails(subject, form,
          teacher: teacher, marks: marks, allowedTime: allowedTime);
    } catch (_) {}
  }

  /// Downloads one assignment to the user's device.
  Future<void> download(AssignmentRecord r) async {
    final d = (await _files.doc(r.id).get()).data();
    if (d == null || d['dataBase64'] == null) {
      throw Exception('The file was not found.');
    }
    final stored = (d['fileName'] as String?) ?? r.fileName;
    final name = '${_clean(r.form)}-${_clean(r.subject)}-'
        '${_clean(r.title.isEmpty ? 'Assignment' : r.title)}${_extOf(stored)}';
    await _downloadInBrowser(
      base64Decode(d['dataBase64'] as String),
      name,
      (d['contentType'] as String?) ?? 'application/octet-stream',
    );
  }

  Future<void> delete(AssignmentRecord r) async {
    try {
      await _files.doc(r.id).delete();
    } catch (_) {}
    await _meta.doc(r.id).delete();
  }

  /// Every assignment this person may see, as one ZIP:
  /// <year>/<Subject>/<Form>-<Subject>-<Title>.<ext>
  Future<int> downloadAll() async {
    final snap = await _meta.get();
    final list = [
      for (final d in snap.docs) AssignmentRecord.fromDoc(d),
    ].where((r) =>
        teacherScope.value.allows(r.subject, r.form)).toList();
    if (list.isEmpty) {
      throw Exception('There are no uploaded assignments to download yet.');
    }
    final year = '${DateTime.now().year}';
    final docs = await Future.wait(list.map((r) => _files.doc(r.id).get()));
    final archive = zip.Archive();
    final used = <String>{};
    var count = 0;
    for (var i = 0; i < list.length; i++) {
      final r = list[i];
      final d = docs[i].data();
      if (d == null || d['dataBase64'] == null) continue;
      final bytes = base64Decode(d['dataBase64'] as String);
      final ext = _extOf((d['fileName'] as String?) ?? r.fileName);
      final stem = '$year/${_clean(r.subject)}/${_clean(r.form)}-'
          '${_clean(r.subject)}-${_clean(r.title.isEmpty ? 'Assignment' : r.title)}';
      var path = '$stem$ext';
      for (var n = 2; !used.add(path); n++) {
        path = '$stem-$n$ext';
      }
      archive.addFile(zip.ArchiveFile(path, bytes.length, bytes));
      count++;
    }
    if (count == 0) throw Exception('The uploaded files could not be read.');
    final out = zip.ZipEncoder().encode(archive);
    if (out == null) throw Exception('Could not create the ZIP file.');
    await _downloadInBrowser(
        Uint8List.fromList(out), 'Assignments-$year.zip', 'application/zip');
    return count;
  }
}

class _AssignmentDownloadAll extends StatefulWidget {
  final AssignmentService service;
  const _AssignmentDownloadAll({required this.service});

  @override
  State<_AssignmentDownloadAll> createState() => _AssignmentDownloadAllState();
}

class _AssignmentDownloadAllState extends State<_AssignmentDownloadAll> {
  bool _busy = false;

  Future<void> _run() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    try {
      final n = await widget.service.downloadAll();
      messenger.showSnackBar(SnackBar(
          content: Text('Downloaded $n assignment files in '
              'Assignments-${DateTime.now().year}.zip')));
    } catch (e) {
      messenger.showSnackBar(SnackBar(
          content: Text('$e'.replaceFirst('Exception: ', ''))));
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_busy) {
      return const Padding(
        padding: EdgeInsets.symmetric(horizontal: 12),
        child: Center(
          child: SizedBox(
              width: 20,
              height: 20,
              child: CircularProgressIndicator(strokeWidth: 2)),
        ),
      );
    }
    return IconButton(
      tooltip: 'Download all assignments (ZIP)',
      icon: const Icon(Icons.folder_zip),
      onPressed: _run,
    );
  }
}

class AssignmentScreen extends StatefulWidget {
  const AssignmentScreen({super.key});

  @override
  State<AssignmentScreen> createState() => _AssignmentScreenState();
}

class _AssignmentScreenState extends State<AssignmentScreen> {
  final _service = AssignmentService();
  late final Stream<Map<String, List<AssignmentRecord>>> _stream =
  _service.watchAll();
  late final Stream<Map<String, AssignmentDetails>> _detailsStream =
  _service.watchDetails();
  Map<String, AssignmentDetails> _details = const {};

  static const _headStyle =
  TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 16);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Assignments'),
        actions: [
          _AssignmentDownloadAll(service: _service),
          IconButton(
            tooltip: 'Exam heading (general)',
            icon: const Icon(Icons.edit_note),
            onPressed: () => showDialog(
              context: context,
              builder: (_) => ExamHeadingDialog(service: _service.exams),
            ),
          ),
          IconButton(
            tooltip: 'School letterhead (general header)',
            icon: const Icon(Icons.image),
            onPressed: () => showDialog(
              context: context,
              builder: (_) => LetterheadDialog(service: _service.exams),
            ),
          ),
          const SizedBox(width: 8),
        ],
      ),
      body: StreamBuilder<Map<String, AssignmentDetails>>(
        stream: _detailsStream,
        builder: (context, dsnap) {
          _details = dsnap.data ?? const {};
          return StreamBuilder<Map<String, List<AssignmentRecord>>>(
            stream: _stream,
            builder: (context, snap) {
              if (snap.hasError) {
                return Center(child: Text('Error: ${snap.error}'));
              }
              if (!snap.hasData) {
                return const Center(child: CircularProgressIndicator());
              }
              final data = snap.data!;
              return ValueListenableBuilder<TeacherScope>(
                valueListenable: teacherScope,
                builder: (context, sc, _) {
                  if (sc.subjectList.isEmpty || sc.formList.isEmpty) {
                    return const Center(
                      child: Padding(
                        padding: EdgeInsets.all(24),
                        child: Text(
                            'No subjects or forms are set on your account.\n'
                                'Ask the administrator to add them in Teachers.',
                            textAlign: TextAlign.center),
                      ),
                    );
                  }
                  return SingleChildScrollView(
                    padding: const EdgeInsets.all(16),
                    child: SingleChildScrollView(
                      scrollDirection: Axis.horizontal,
                      child: Card(
                        clipBehavior: Clip.antiAlias,
                        child: _table(data, sc),
                      ),
                    ),
                  );
                },
              );
            },
          );
        },
      ),
    );
  }

  Widget _table(Map<String, List<AssignmentRecord>> data, TeacherScope sc) {
    const subjectWidth = 130.0;
    const cellWidth = 250.0;
    final header = Container(
      color: kBlue,
      padding: const EdgeInsets.symmetric(vertical: 16),
      child: Row(children: [
        const SizedBox(
          width: subjectWidth,
          child: Padding(
            padding: EdgeInsets.only(left: 12),
            child: Text('Subject', style: _headStyle),
          ),
        ),
        for (final f in sc.formList)
          SizedBox(
            width: cellWidth,
            child: Padding(
              padding: const EdgeInsets.only(left: 12),
              child: Text(f, style: _headStyle),
            ),
          ),
      ]),
    );
    final rows = [
      for (final s in sc.subjectList)
        Container(
          decoration: const BoxDecoration(
            border: Border(bottom: BorderSide(color: Color(0xFFE0E0E0))),
          ),
          padding: const EdgeInsets.symmetric(vertical: 10),
          child: Row(children: [
            SizedBox(
              width: subjectWidth,
              child: Padding(
                padding: const EdgeInsets.only(left: 12),
                child: Text(s, style: const TextStyle(fontSize: 16)),
              ),
            ),
            for (final f in sc.formList)
              SizedBox(
                width: cellWidth,
                child: !sc.allows(s, f)
                    ? const Center(
                    child: Text('—',
                        style: TextStyle(color: Colors.black26, fontSize: 18)))
                    : _AssignmentCell(
                  subject: s,
                  form: f,
                  items: data[AssignmentRecord.keyFor(s, f)] ?? const [],
                  details: _details[AssignmentRecord.keyFor(s, f)],
                  service: _service,
                ),
              ),
          ]),
        ),
    ];
    return Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [header, ...rows]);
  }
}

class _AssignmentCell extends StatelessWidget {
  final String subject, form;
  final List<AssignmentRecord> items;
  final AssignmentDetails? details;
  final AssignmentService service;
  const _AssignmentCell({
    required this.subject,
    required this.form,
    required this.items,
    required this.details,
    required this.service,
  });

  @override
  Widget build(BuildContext context) {
    final has = items.isNotEmpty;
    final last = has ? items.last.createdAt : null;
    var teacher = details?.teacherName ?? '';
    if (teacher.isEmpty && has) {
      teacher = items.reversed
          .map((a) => a.teacherName)
          .firstWhere((n) => n.isNotEmpty, orElse: () => '');
    }
    final row = Row(
      mainAxisAlignment: MainAxisAlignment.center,
      children: [
        if (last != null)
          Padding(
            padding: const EdgeInsets.only(right: 6),
            child: Text(
              DateFormat('MM/dd/yyyy').format(last),
              style: const TextStyle(fontSize: 12, color: Colors.black54),
            ),
          ),
        // The button IS the upload button; it opens the list of assignments.
        ElevatedButton.icon(
          onPressed: () => showDialog(
            context: context,
            builder: (_) => AssignmentDialog(
                subject: subject, form: form, service: service),
          ),
          icon: Icon(has ? Icons.check : Icons.upload_file, size: 16),
          label: Text(has
              ? '${items.length} assignment${items.length == 1 ? '' : 's'}'
              : 'Pending'),
          style: ElevatedButton.styleFrom(
            backgroundColor: has ? kGreen : kRed,
            foregroundColor: Colors.white,
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
            minimumSize: const Size(0, 34),
            shape:
            RoundedRectangleBorder(borderRadius: BorderRadius.circular(4)),
          ),
        ),
      ],
    );
    if (teacher.isEmpty) return row;
    return Column(mainAxisSize: MainAxisSize.min, children: [
      row,
      const SizedBox(height: 2),
      Text(teacher,
          style: const TextStyle(fontSize: 11, color: Colors.black54)),
    ]);
  }
}

/// Opened by every button. Same details as the exam dialog (teacher, footer,
/// marks, allowed time, heading table, formatting) plus the list of the
/// assignments already uploaded and a form to add one more.
class AssignmentDialog extends StatefulWidget {
  final String subject, form;
  final AssignmentService service;
  const AssignmentDialog({
    super.key,
    required this.subject,
    required this.form,
    required this.service,
  });

  @override
  State<AssignmentDialog> createState() => _AssignmentDialogState();
}

class _AssignmentDialogState extends State<AssignmentDialog> {
  final _title = TextEditingController();
  final _teacher = TextEditingController();
  final _footer = TextEditingController();
  final _marks = TextEditingController();
  final _time = TextEditingController();
  late final Stream<List<AssignmentRecord>> _stream =
  widget.service.watchFor(widget.subject, widget.form);
  // The starting ticks come from Settings > Exam upload.
  bool _addHeading = appSettings.value.uploadHeading;
  bool _autoFormat = appSettings.value.uploadAutoFormat;
  bool _numberQuestions = appSettings.value.uploadNumber;
  ExamHeading? _heading; // general heading, loaded from Firestore
  PlatformFile? _file;
  bool _busy = false;
  String? _status;
  List<AssignmentRecord> _items = const [];
  int _count = 0; // assignments already uploaded (for "Assignment N")

  String get _suggestedTitle => 'Assignment ${_count + 1}';
  String get _titleOrSuggested =>
      _title.text.trim().isEmpty ? _suggestedTitle : _title.text.trim();

  @override
  void initState() {
    super.initState();
    widget.service.exams.getHeading().then((h) {
      if (mounted) setState(() => _heading = h);
    }).catchError((_) {});
    _loadDetails();
  }

  /// Teacher, marks and time saved for this button (or, if nothing was
  /// saved yet, the teacher of the last assignment).
  Future<void> _loadDetails() async {
    try {
      final d = await widget.service.getDetails(widget.subject, widget.form);
      var t = d.teacherName;
      if (t.isEmpty) {
        final l =
        await widget.service.watchFor(widget.subject, widget.form).first;
        t = l.reversed
            .map((a) => a.teacherName)
            .firstWhere((n) => n.isNotEmpty, orElse: () => '');
      }
      if (!mounted) return;
      setState(() {
        if (_teacher.text.isEmpty) {
          _teacher.text = t;
          _footer.text = AssignmentService.footerFor(
              widget.subject, widget.form, t);
        }
        if (_marks.text.isEmpty) _marks.text = d.marks;
        if (_time.text.isEmpty) _time.text = d.allowedTime;
      });
    } catch (_) {}
  }

  @override
  void dispose() {
    _title.dispose();
    _teacher.dispose();
    _footer.dispose();
    _marks.dispose();
    _time.dispose();
    super.dispose();
  }

  void _toast(String m, {int seconds = 4}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(duration: Duration(seconds: seconds), content: Text(m)));
  }

  String _err(Object e) => '$e'.replaceFirst('Exception: ', '');

  Future<void> _pick() async {
    final res = await FilePicker.platform.pickFiles(
      withData: true,
      type: FileType.custom,
      allowedExtensions: ['docx', 'pdf', 'png', 'jpg', 'jpeg'],
    );
    if (res == null || res.files.isEmpty) return;
    final f = res.files.first;
    final ext = (f.extension ?? '').toLowerCase();
    if (!const ['docx', 'pdf', 'png', 'jpg', 'jpeg'].contains(ext)) {
      _toast(
          '"${f.name}" cannot be used. Use a Word (.docx) file. For .doc or '
              '.odt files, open them in Word and use Save As → Word Document (.docx).',
          seconds: 6);
      return;
    }
    setState(() => _file = f);
  }

  Future<void> _saveDetails() async {
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    final nav = Navigator.of(context);
    try {
      await widget.service.saveDetails(widget.subject, widget.form,
          teacher: _teacher.text.trim(),
          marks: _marks.text.trim(),
          allowedTime: _time.text.trim());
      nav.pop();
      messenger.showSnackBar(const SnackBar(content: Text('Saved')));
    } catch (e) {
      if (mounted) setState(() => _busy = false);
      messenger.showSnackBar(SnackBar(content: Text('Failed: ${_err(e)}')));
    }
  }

  Future<void> _markPending() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete all assignments?'),
        content: Text(
            'Delete all ${_items.length} assignment${_items.length == 1 ? '' : 's'} '
                'of ${widget.subject} · ${widget.form}? This cannot be undone and '
                'the button will be marked as Pending.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Delete')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    setState(() => _busy = true);
    final messenger = ScaffoldMessenger.of(context);
    final nav = Navigator.of(context);
    try {
      await widget.service.deleteAll(widget.subject, widget.form);
      nav.pop();
      messenger.showSnackBar(const SnackBar(content: Text('Marked as pending')));
    } catch (e) {
      if (mounted) setState(() => _busy = false);
      messenger.showSnackBar(SnackBar(content: Text('Failed: ${_err(e)}')));
    }
  }

  /// Shows the finished document without saving anything.
  Future<void> _preview() async {
    final f = _file;
    if (f == null) return;
    setState(() {
      _busy = true;
      _status = 'Building preview...';
    });
    try {
      final p = await widget.service.exams.buildPreview(
        current: ExamRecord.empty(widget.subject, widget.form),
        file: f,
        footer: _footer.text.trim(),
        marks: _marks.text.trim(),
        allowedTime: _time.text.trim(),
        addHeading: _addHeading,
        autoFormat: _autoFormat,
        numberQuestions: _numberQuestions,
      );
      if (!mounted) return;
      if (p.isDocx) {
        // Word files cannot be drawn inside the app: download a copy to check.
        await _downloadInBrowser(p.bytes, p.name, ExamService._docxMime);
        _toast(
            'Preview downloaded. Open it in Word to check, then press Upload '
                'if it is correct.',
            seconds: 6);
      } else {
        await showDialog(
          context: context,
          builder: (_) => PreviewDialog(bytes: p.bytes),
        );
      }
    } catch (e) {
      _toast('Preview failed: ${_err(e)}');
    } finally {
      if (mounted) {
        setState(() {
          _busy = false;
          _status = null;
        });
      }
    }
  }

  Future<void> _upload() async {
    final f = _file;
    if (f == null) return;
    final title = _titleOrSuggested;
    setState(() {
      _busy = true;
      _status = 'Preparing...';
    });
    try {
      await widget.service.upload(
        subject: widget.subject,
        form: widget.form,
        title: title,
        teacher: _teacher.text.trim(),
        file: f,
        marks: _marks.text.trim(),
        allowedTime: _time.text.trim(),
        addHeading: _addHeading,
        autoFormat: _autoFormat,
        numberQuestions: _numberQuestions,
        onStatus: (t) {
          if (mounted) setState(() => _status = t);
        },
      );
      if (!mounted) return;
      setState(() {
        _file = null;
        _title.clear();
      });
      _toast('"$title" uploaded. You can add another one.');
    } catch (e) {
      _toast('Failed: ${_err(e)}', seconds: 6);
    } finally {
      if (mounted) {
        setState(() {
          _busy = false;
          _status = null;
        });
      }
    }
  }

  Future<void> _download(AssignmentRecord r) async {
    try {
      await widget.service.download(r);
    } catch (e) {
      _toast(_err(e));
    }
  }

  Future<void> _delete(AssignmentRecord r) async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete assignment?'),
        content: Text('Delete "${r.title}"? This cannot be undone.'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Delete')),
        ],
      ),
    );
    if (ok != true || !mounted) return;
    try {
      await widget.service.delete(r);
      _toast('Deleted "${r.title}"');
    } catch (e) {
      _toast('Failed: ${_err(e)}');
    }
  }

  Widget _existing(List<AssignmentRecord> items) {
    return Column(children: [
      for (final r in items)
        ListTile(
          dense: true,
          contentPadding: EdgeInsets.zero,
          leading: const Icon(Icons.description),
          title: Text(r.title.isEmpty ? r.fileName : r.title,
              overflow: TextOverflow.ellipsis),
          subtitle: Text(
              [
                if (r.createdAt != null)
                  DateFormat('MM/dd/yyyy').format(r.createdAt!),
                '${(r.size / 1024).round()} KB',
              ].join(' · '),
              overflow: TextOverflow.ellipsis),
          trailing: Row(mainAxisSize: MainAxisSize.min, children: [
            IconButton(
              tooltip: 'Download',
              icon: const Icon(Icons.download),
              onPressed: _busy ? null : () => _download(r),
            ),
            IconButton(
              tooltip: 'Delete assignment',
              icon: const Icon(Icons.delete_outline),
              color: Theme.of(context).colorScheme.error,
              onPressed: _busy ? null : () => _delete(r),
            ),
          ]),
        ),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final preview = _heading?.build(widget.subject, widget.form,
        marks: _marks.text, time: _time.text);
    return AlertDialog(
      title: Text('${widget.subject} · ${widget.form}'),
      content: SizedBox(
        width: 420,
        child: SingleChildScrollView(
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            TextField(
              controller: _teacher,
              textCapitalization: TextCapitalization.words,
              onChanged: (v) => setState(() => _footer.text =
                  AssignmentService.footerFor(widget.subject, widget.form, v)),
              decoration: const InputDecoration(
                labelText: "Teacher's name",
                prefixIcon: Icon(Icons.person),
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: _footer,
              readOnly: true,
              maxLines: 2,
              decoration: const InputDecoration(
                labelText: 'Footer (auto-generated)',
                helperText: 'Built from subject, form and teacher name',
                filled: true,
                border: OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 12),
            Row(children: [
              Expanded(
                child: TextField(
                  controller: _marks,
                  onChanged: (_) => setState(() {}),
                  decoration: InputDecoration(
                    labelText: 'Marks',
                    hintText: _heading?.marks,
                    border: const OutlineInputBorder(),
                  ),
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                flex: 2,
                child: TextField(
                  controller: _time,
                  onChanged: (_) => setState(() {}),
                  decoration: InputDecoration(
                    labelText: 'Allowed time',
                    hintText: _heading?.defaultTimeFor(widget.subject),
                    border: const OutlineInputBorder(),
                  ),
                ),
              ),
            ]),
            const Padding(
              padding: EdgeInsets.only(top: 4),
              child: Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  'Leave Marks / Allowed time empty to use the general values.',
                  style: TextStyle(fontSize: 11, color: Colors.black54),
                ),
              ),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _addHeading,
              onChanged: _busy
                  ? null
                  : (v) => setState(() => _addHeading = v ?? true),
              title: const Text('Add exam heading table on the first page'),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _autoFormat,
              onChanged: _busy
                  ? null
                  : (v) => setState(() => _autoFormat = v ?? true),
              title: const Text(
                  'Titles and questions bold, options (a, b, c, d) regular'),
            ),
            CheckboxListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              controlAffinity: ListTileControlAffinity.leading,
              value: _numberQuestions,
              onChanged: (_busy || !_autoFormat)
                  ? null
                  : (v) => setState(() => _numberQuestions = v ?? true),
              title: const Text('Number the questions 1. 2. 3. in each part'),
            ),
            if (_addHeading && preview != null) _headingPreview(preview),
            const SizedBox(height: 16),
            // The assignments already uploaded for this button.
            StreamBuilder<List<AssignmentRecord>>(
              stream: _stream,
              builder: (context, snap) {
                if (snap.hasError) return Text('Error: ${snap.error}');
                if (!snap.hasData) {
                  return const Padding(
                    padding: EdgeInsets.all(12),
                    child: Center(child: CircularProgressIndicator()),
                  );
                }
                final items = snap.data!;
                _items = items;
                if (_count != items.length) {
                  // The hint "Assignment N" follows the number uploaded.
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    if (mounted) setState(() => _count = items.length);
                  });
                }
                if (items.isEmpty) return const SizedBox.shrink();
                return Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                          'Uploaded (${items.length})',
                          style: const TextStyle(fontWeight: FontWeight.w700)),
                      _existing(items),
                      const SizedBox(height: 8),
                    ]);
              },
            ),
            TextField(
              controller: _title,
              textCapitalization: TextCapitalization.sentences,
              onChanged: (_) => setState(() {}),
              decoration: InputDecoration(
                labelText: 'Assignment title',
                hintText: _suggestedTitle,
                prefixIcon: const Icon(Icons.title),
                border: const OutlineInputBorder(),
              ),
            ),
            const SizedBox(height: 10),
            Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Flexible(
                  child: OutlinedButton.icon(
                    onPressed: _busy ? null : _pick,
                    icon: const Icon(Icons.attach_file),
                    label: Text(
                      _file?.name ??
                          (_items.isNotEmpty
                              ? 'Choose another file'
                              : 'Choose file'),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ),
                if (_file != null)
                  IconButton(
                    icon: const Icon(Icons.close),
                    tooltip: 'Remove selected file',
                    onPressed: _busy ? null : () => setState(() => _file = null),
                  ),
              ],
            ),
            const SizedBox(height: 6),
            const Text(
              'Word (.docx) recommended; PDF and images also work. The school '
                  'letterhead and the footer are added automatically to every '
                  'page. You can upload as many assignments as you need.',
              style: TextStyle(fontSize: 12, color: Colors.black54),
            ),
            if (_status != null) ...[
              const SizedBox(height: 10),
              Text(_status!, style: const TextStyle(fontSize: 12)),
            ],
            if (_busy) ...[
              const SizedBox(height: 6),
              const LinearProgressIndicator(),
            ],
          ]),
        ),
      ),
      actions: [
        if (_items.isNotEmpty)
          TextButton(
            onPressed: _busy ? null : _markPending,
            child: const Text('Mark pending'),
          ),
        TextButton(
          onPressed: _busy ? null : () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        TextButton(
          onPressed: _busy ? null : _saveDetails,
          child: const Text('Save details'),
        ),
        OutlinedButton.icon(
          onPressed: (_busy || _file == null) ? null : _preview,
          icon: const Icon(Icons.visibility),
          label: const Text('Preview'),
        ),
        FilledButton.icon(
          onPressed: (_busy || _file == null) ? null : _upload,
          icon: const Icon(Icons.cloud_upload),
          label: const Text('Upload'),
        ),
      ],
    );
  }
}

// ======================= HOME SCREEN (Exam / Sections / Attendance) =======================

/// Goes back to the home route first (so no pushed screen stays on top of the
/// login page) and then signs out.
Future<void> _signOut(BuildContext context) async {
  Navigator.of(context).popUntil((r) => r.isFirst);
  try {
    // must be written while still signed in; never block the sign out
    await logActivity('logout').timeout(const Duration(seconds: 4));
  } catch (_) {}
  stopPresence();
  await FirebaseAuth.instance.signOut();
}

// ======================= ACTIVITY LOG (Settings > Activity log) =======================
//
// Firestore:
//   activityLog/{auto}  uid, name, email, role, type ('login'|'logout'), time
//   presence/{uid}      name, role, online (bool), lastSeen
// A person counts as online while presence.online is true and lastSeen is
// less than 5 minutes old (the app refreshes it every 2 minutes), so someone
// who closes the app without signing out drops off the list by itself.

Timer? _presenceTimer;

/// Writes one login / logout event and updates the online marker.
/// Never throws: the activity log must not stop anybody from signing in.
Future<void> logActivity(String type, {User? user}) async {
  final u = user ?? FirebaseAuth.instance.currentUser;
  if (u == null) return;
  try {
    final db = FirebaseFirestore.instance;
    var name = u.displayName ?? '';
    var role = '';
    try {
      final m = (await db.collection('users').doc(u.uid).get()).data();
      if (m != null) {
        if ('${m['name'] ?? ''}'.trim().isNotEmpty) name = '${m['name']}';
        role = '${m['role'] ?? ''}';
      }
    } catch (_) {}
    if (name.trim().isEmpty) name = u.email ?? u.uid;
    await db.collection('activityLog').add({
      'uid': u.uid,
      'name': name,
      'email': u.email ?? '',
      'role': role,
      'type': type,
      'time': FieldValue.serverTimestamp(),
    });
    await db.collection('presence').doc(u.uid).set({
      'name': name,
      'role': role,
      'online': type == 'login',
      'lastSeen': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true));
  } catch (_) {}
}

/// Student events shown in Settings > Activity log:
///   studentLog/{auto}  type ('added'|'moved'|'deleted'), studentId,
///   studentName, from, to (class labels), byUid, byName, time
/// Never throws: logging must not stop a student change from working.
Future<void> logStudentEvents(List<Map<String, dynamic>> events) async {
  if (events.isEmpty) return;
  try {
    final db = FirebaseFirestore.instance;
    final u = FirebaseAuth.instance.currentUser;
    var by = u?.displayName ?? '';
    if (u != null) {
      try {
        final m = (await db.collection('users').doc(u.uid).get()).data();
        if (m != null && '${m['name'] ?? ''}'.trim().isNotEmpty) {
          by = '${m['name']}';
        }
      } catch (_) {}
      if (by.trim().isEmpty) by = u.email ?? u.uid;
    }
    for (var i = 0; i < events.length; i += 400) {
      final batch = db.batch();
      for (final e in events.skip(i).take(400)) {
        batch.set(db.collection('studentLog').doc(), {
          'studentId': '',
          'studentName': '',
          'from': '',
          'to': '',
          ...e,
          'byUid': u?.uid ?? '',
          'byName': by,
          'time': FieldValue.serverTimestamp(),
        });
      }
      await batch.commit();
    }
  } catch (_) {}
}

/// section id -> readable class label (3C, 3C - Section B ...).
Future<Map<String, String>> _sectionLabels() async {
  try {
    final snap = await FirebaseFirestore.instance.collection('sections').get();
    return {
      for (final d in snap.docs) d.id: SectionInfo.fromDoc(d).fullName
    };
  } catch (_) {
    return {};
  }
}

/// Refreshes "lastSeen" every 2 minutes while somebody is signed in.
void startPresence() {
  _presenceTimer?.cancel();
  _presenceTimer = Timer.periodic(const Duration(minutes: 2), (_) {
    final u = FirebaseAuth.instance.currentUser;
    if (u == null) return;
    FirebaseFirestore.instance.collection('presence').doc(u.uid).set({
      'online': true,
      'lastSeen': FieldValue.serverTimestamp(),
    }, SetOptions(merge: true)).catchError((_) {});
  });
}

void stopPresence() {
  _presenceTimer?.cancel();
  _presenceTimer = null;
}

/// Two cards in Settings > Activity log: the users' logins
/// (students: false) and the students' changes (students: true).
class _ActivityLogCard extends StatefulWidget {
  final bool students;
  const _ActivityLogCard({this.students = false});

  @override
  State<_ActivityLogCard> createState() => _ActivityLogCardState();
}

class _ActivityLogCardState extends State<_ActivityLogCard> {
  static const _hint = TextStyle(fontSize: 12, color: Colors.black54);
  static const _onlineFor = Duration(minutes: 5);

  DateTimeRange _range = DateTimeRange(
    start: DateUtils.dateOnly(DateTime.now()),
    end: DateUtils.dateOnly(DateTime.now()),
  );
  // users card: in = online now | out = last logged out
  // students card: added | moved | deleted
  late String _filter = widget.students ? 'added' : 'in';
  // one document per user: their current state (see logActivity)
  late final Stream<QuerySnapshot<Map<String, dynamic>>> _people =
  FirebaseFirestore.instance.collection('presence').snapshots();
  Timer? _tick;

  @override
  void initState() {
    super.initState();
    // re-check who is still online once a minute
    _tick = Timer.periodic(const Duration(minutes: 1), (_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _tick?.cancel();
    super.dispose();
  }

  Future<void> _pickRange() async {
    final picked = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2020),
      lastDate: DateTime.now(),
      initialDateRange: _range,
    );
    if (picked != null) setState(() => _range = picked);
  }

  String _rangeLabel() {
    final f = DateFormat('d MMM yyyy');
    return DateUtils.isSameDay(_range.start, _range.end)
        ? f.format(_range.start)
        : '${f.format(_range.start)} - ${f.format(_range.end)}';
  }

  String _role(String r) => r.isEmpty ? '' : UserProfile.roleLabel(r);

  DateTime? _time(Object? v) => v is Timestamp ? v.toDate() : null;

  Widget _row(Map<String, dynamic> m, bool online, DateTime? seen) {
    final tf = DateFormat('d MMM yyyy, HH:mm');
    final role = _role('${m['role'] ?? ''}');
    final signedOut = m['online'] != true;
    return ListTile(
      dense: true,
      contentPadding: EdgeInsets.zero,
      leading: CircleAvatar(
        radius: 18,
        backgroundColor: online ? Colors.green.shade50 : Colors.grey.shade200,
        child: Icon(online ? Icons.circle : Icons.logout,
            size: online ? 12 : 18,
            color: online ? Colors.green.shade700 : Colors.black54),
      ),
      title: Text('${m['name'] ?? ''}',
          style: const TextStyle(fontWeight: FontWeight.w600)),
      subtitle: Text(online
          ? 'Online${role.isEmpty ? '' : ' - $role'}'
          : '${signedOut ? 'Logged out' : 'Last seen'}'
          '${role.isEmpty ? '' : ' - $role'}'),
      trailing: Text(seen == null ? '...' : tf.format(seen), style: _hint),
    );
  }

  // ---- student activity (added / transferred / deleted) ----
  static const _studentTabs = [
    ('added', 'New students', Icons.person_add_alt_1),
    ('moved', 'Transferred', Icons.swap_horiz),
    ('deleted', 'Deleted', Icons.person_remove_alt_1),
  ];

  Widget _studentRow(Map<String, dynamic> m) {
    final tf = DateFormat('d MMM yyyy, HH:mm');
    final type = '${m['type'] ?? ''}';
    final from = '${m['from'] ?? ''}';
    final to = '${m['to'] ?? ''}';
    final by = '${m['byName'] ?? ''}';
    final color = type == 'added'
        ? Colors.green.shade700
        : type == 'moved'
        ? Colors.blue.shade700
        : Colors.red.shade700;
    final icon = _studentTabs.firstWhere((t) => t.$1 == type).$3;
    final what = type == 'added'
        ? (to.isEmpty ? 'Added' : 'Added to $to')
        : type == 'moved'
        ? '${from.isEmpty ? '?' : from}  ->  ${to.isEmpty ? '?' : to}'
        : (from.isEmpty ? 'Deleted' : 'Deleted from $from');
    return ListTile(
      dense: true,
      contentPadding: EdgeInsets.zero,
      leading: CircleAvatar(
        radius: 18,
        backgroundColor: color.withOpacity(0.12),
        child: Icon(icon, size: 18, color: color),
      ),
      title: Text('${m['studentName'] ?? ''}',
          style: const TextStyle(fontWeight: FontWeight.w600)),
      subtitle: Text('$what${by.isEmpty ? '' : ' - by $by'}'),
      trailing: Text(
          _time(m['time']) == null ? '...' : tf.format(_time(m['time'])!),
          style: _hint),
    );
  }

  Widget _studentLog(String type) {
    final end = _range.end.add(const Duration(days: 1));
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      // one range on one field: needs no composite index
      stream: FirebaseFirestore.instance
          .collection('studentLog')
          .where('time',
          isGreaterThanOrEqualTo: Timestamp.fromDate(_range.start))
          .where('time', isLessThan: Timestamp.fromDate(end))
          .snapshots(),
      builder: (context, snap) {
        if (snap.hasError) {
          return Text(
              'Could not load the student activity. Check that the '
                  'Firestore rules allow reading studentLog.\n${snap.error}',
              style: const TextStyle(color: Colors.red));
        }
        if (!snap.hasData) {
          return const Padding(
            padding: EdgeInsets.symmetric(vertical: 24),
            child: Center(child: CircularProgressIndicator()),
          );
        }
        final rows = [
          for (final d in snap.data!.docs)
            if (d.data()['type'] == type) d.data()
        ]..sort((a, b) {
          final x = _time(a['time']), y = _time(b['time']);
          if (x == null || y == null) return 0;
          return y.compareTo(x);
        });
        final label = _studentTabs.firstWhere((t) => t.$1 == type).$2;
        final empty = type == 'added'
            ? 'No new students on this date.'
            : type == 'moved'
            ? 'No students were transferred on this date.'
            : 'No students were deleted on this date.';
        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const SizedBox(height: 12),
            Text('$label (${rows.length})',
                style:
                const TextStyle(fontSize: 15, fontWeight: FontWeight.w700)),
            const SizedBox(height: 8),
            OutlinedButton.icon(
              onPressed: _pickRange,
              icon: const Icon(Icons.calendar_today, size: 18),
              label: Text(_rangeLabel()),
            ),
            if (rows.isEmpty)
              Padding(
                padding: const EdgeInsets.symmetric(vertical: 12),
                child: Text(empty, style: _hint),
              )
            else
              for (final m in rows) _studentRow(m),
          ],
        );
      },
    );
  }

  Widget _loginLog() {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: _people,
      builder: (context, snap) {
        if (snap.hasError) {
          return Text(
              'Could not load the activity log. Check that the '
                  'Firestore rules allow the administrator to read '
                  'presence.\n${snap.error}',
              style: const TextStyle(color: Colors.red));
        }
        if (!snap.hasData) {
          return const Padding(
            padding: EdgeInsets.symmetric(vertical: 24),
            child: Center(child: CircularProgressIndicator()),
          );
        }
        final cutoff = DateTime.now().subtract(_onlineFor);
        final end = _range.end.add(const Duration(days: 1));
        final online = <(Map<String, dynamic>, DateTime?)>[];
        final out = <(Map<String, dynamic>, DateTime?)>[];
        for (final d in snap.data!.docs) {
          final m = d.data();
          final seen = _time(m['lastSeen']);
          if (m['online'] == true && seen != null && seen.isAfter(cutoff)) {
            online.add((m, seen));
          } else if (seen != null &&
              !seen.isBefore(_range.start) &&
              seen.isBefore(end)) {
            out.add((m, seen));
          }
        }
        online.sort((a, b) => '${a.$1['name']}'.compareTo('${b.$1['name']}'));
        out.sort((a, b) => b.$2!.compareTo(a.$2!));
        return Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            if (_filter == 'in') ...[
              const SizedBox(height: 12),
              Text('Online now (${online.length})',
                  style: const TextStyle(
                      fontSize: 15, fontWeight: FontWeight.w700)),
              if (online.isEmpty)
                const Padding(
                  padding: EdgeInsets.symmetric(vertical: 8),
                  child: Text('Nobody is online right now.', style: _hint),
                )
              else
                for (final p in online) _row(p.$1, true, p.$2),
            ],
            if (_filter == 'out') ...[
              const Divider(height: 28),
              const Text('Last logged out',
                  style: TextStyle(fontSize: 15, fontWeight: FontWeight.w700)),
              const SizedBox(height: 8),
              OutlinedButton.icon(
                onPressed: _pickRange,
                icon: const Icon(Icons.calendar_today, size: 18),
                label: Text(_rangeLabel()),
              ),
              if (out.isEmpty)
                const Padding(
                  padding: EdgeInsets.symmetric(vertical: 12),
                  child: Text('Nobody logged out on this date.', style: _hint),
                )
              else
                for (final p in out) _row(p.$1, false, p.$2),
            ],
          ],
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    return Card(
      elevation: 0,
      color: Colors.white,
      shape: _kSettingsCardShape,
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(widget.students ? 'Students activity' : 'Users activity',
                style:
                const TextStyle(fontSize: 17, fontWeight: FontWeight.w800)),
            const SizedBox(height: 4),
            Text(
                widget.students
                    ? 'New, transferred and deleted students'
                    : 'Who logged in or out, and who is online',
                style: _hint),
            const SizedBox(height: 10),
            Wrap(spacing: 8, runSpacing: 8, children: [
              for (final f in widget.students
                  ? [for (final t in _studentTabs) (t.$1, t.$2)]
                  : [('in', 'Logged in'), ('out', 'Logged out')])
                ChoiceChip(
                  label: Text(f.$2),
                  selected: _filter == f.$1,
                  onSelected: (_) => setState(() => _filter = f.$1),
                ),
            ]),
            if (_filter == 'in' || _filter == 'out')
              _loginLog()
            else
              _studentLog(_filter),
          ],
        ),
      ),
    );
  }
}


/// Lets the signed-in person (teacher, student, administrator) change their
/// own password: the current password is asked first.
Future<void> showChangePasswordDialog(BuildContext context) async {
  final user = FirebaseAuth.instance.currentUser;
  final email = user?.email;
  final messenger = ScaffoldMessenger.of(context);
  if (user == null || email == null) {
    messenger.showSnackBar(
        const SnackBar(content: Text('Sign in first to change the password.')));
    return;
  }
  final current = TextEditingController();
  final next = TextEditingController();
  final again = TextEditingController();
  var hide = true;
  var busy = false;
  String? error;
  final done = await showDialog<bool>(
    context: context,
    barrierDismissible: false,
    builder: (ctx) => StatefulBuilder(builder: (ctx, setD) {
      Future<void> submit() async {
        final cur = current.text;
        final nw = next.text;
        if (cur.isEmpty) {
          setD(() => error = 'Enter your current password.');
          return;
        }
        if (nw.length < 6) {
          setD(() => error = 'The new password must be at least 6 characters.');
          return;
        }
        if (nw != again.text) {
          setD(() => error = 'The new passwords do not match.');
          return;
        }
        if (nw == cur) {
          setD(() => error = 'The new password must be different.');
          return;
        }
        setD(() {
          busy = true;
          error = null;
        });
        try {
          try {
            await user.reauthenticateWithCredential(
                EmailAuthProvider.credential(email: email, password: cur));
          } on FirebaseAuthException catch (e) {
            // a student's first password is the phone number: also try it
            // without spaces, +, dashes
            final digits = phoneDigits(cur);
            final wrong = e.code == 'wrong-password' ||
                e.code == 'invalid-credential';
            if (wrong && digits != null && digits != cur) {
              await user.reauthenticateWithCredential(
                  EmailAuthProvider.credential(email: email, password: digits));
            } else {
              rethrow;
            }
          }
          await user.updatePassword(nw);
          if (ctx.mounted) Navigator.pop(ctx, true);
        } on FirebaseAuthException catch (e) {
          setD(() {
            busy = false;
            error = switch (e.code) {
              'wrong-password' ||
              'invalid-credential' =>
              'The current password is wrong.',
              'weak-password' => 'The new password is too weak.',
              'too-many-requests' =>
              'Too many attempts. Wait a few minutes and try again.',
              'requires-recent-login' =>
              'Please sign out, sign in again and retry.',
              _ => e.message ?? e.code,
            };
          });
        } catch (e) {
          setD(() {
            busy = false;
            error = 'Failed: $e';
          });
        }
      }

      InputDecoration dec(String label, {bool eye = false}) => InputDecoration(
        labelText: label,
        border: const OutlineInputBorder(),
        suffixIcon: eye
            ? IconButton(
          icon: Icon(hide ? Icons.visibility : Icons.visibility_off),
          onPressed: () => setD(() => hide = !hide),
        )
            : null,
      );

      return AlertDialog(
        title: const Text('Change password'),
        content: SizedBox(
          width: 380,
          child: SingleChildScrollView(
            child: Column(mainAxisSize: MainAxisSize.min, children: [
              Align(
                alignment: Alignment.centerLeft,
                child: Text(email,
                    style: const TextStyle(fontSize: 12, color: Colors.black54)),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: current,
                obscureText: hide,
                autofocus: true,
                decoration: dec('Current password', eye: true),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: next,
                obscureText: hide,
                decoration: dec('New password (6 or more characters)'),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: again,
                obscureText: hide,
                onSubmitted: (_) => busy ? null : submit(),
                decoration: dec('Repeat the new password'),
              ),
              if (error != null)
                Padding(
                  padding: const EdgeInsets.only(top: 10),
                  child: Align(
                    alignment: Alignment.centerLeft,
                    child: Text(error!,
                        style: const TextStyle(color: Color(0xFFC62828))),
                  ),
                ),
            ]),
          ),
        ),
        actions: [
          TextButton(
              onPressed: busy ? null : () => Navigator.pop(ctx, false),
              child: const Text('Cancel')),
          FilledButton(
            onPressed: busy ? null : submit,
            child: busy
                ? const SizedBox(
                width: 18,
                height: 18,
                child: CircularProgressIndicator(strokeWidth: 2))
                : const Text('Change password'),
          ),
        ],
      );
    }),
  );
  current.dispose();
  next.dispose();
  again.dispose();
  if (done == true) {
    messenger.showSnackBar(
        const SnackBar(content: Text('Your password was changed.')));
  }
}

/// The pages of the app that can be allowed or hidden for each user.
/// The keys are saved in Firestore, so do not rename them.
class AppPages {
  static const exam = 'exam';
  static const assignments = 'assignments';
  static const sections = 'sections';
  static const students = 'students';
  static const attendance = 'attendance';
  static const daily = 'daily';
  static const result = 'result';
  static const schedule = 'schedule';
  static const teachers = 'teachers';
  static const finance = 'finance';
  static const discipline = 'discipline';
  static const settings = 'settings';

  static const all = [
    exam,
    assignments,
    sections,
    students,
    attendance,
    daily,
    result,
    schedule,
    teachers,
    finance,
    discipline,
    settings,
  ];
  static const labels = {
    exam: 'Exam',
    assignments: 'Assignments',
    sections: 'Sections',
    students: 'Students',
    attendance: 'Attendance',
    daily: 'Daily attendance',
    result: 'Result',
    schedule: 'Schedule',
    teachers: 'Teachers',
    finance: 'Finance',
    discipline: 'Discipline',
    settings: 'Settings',
  };
}

/// Who the signed-in person is and which pages they may open
/// (Firestore: users/{uid}).
///  - role 'admin'   : sees every page and manages the permissions.
///  - role 'affairs' (student affairs): NOT full access. Sees only the pages
///    in `access` (default: Settings > Users > Default access).
///  - role 'finance': sees the pages in `access` (default: Finance only) and,
///    when the administrator ticked classes (`financeSections`), only those
///    classes. No class ticked = every class.
///  - role 'teacher' / 'student': sees the
///    pages in `access`; when `access`
///    is not set, the default of that role (Settings > Users & permissions).
///  - no profile document: an account made before permissions existed. It
///    keeps full access, as an administrator.
class UserProfile {
  final String uid, role, name, email;
  final String phone; // students: the first phone number (their username)
  final String studentId; // student accounts: the registered student record
  final List<String>? access;
  final bool legacy;

  /// Added in the Teachers tab; has not signed in for the first time yet.
  final bool pending;

  /// False for an account created on the login screen until an
  /// administrator approves it (accounts without the field are approved).
  final bool approved;

  /// The administrator refused this sign up.
  final bool rejected;

  /// Finance role: the classes (whole classes like 1A) this person may manage.
  /// Empty = every class.
  final List<String> financeSections;

  /// Class monitor: the classes (whole classes like 1A) this person takes the
  /// DAILY attendance of. Set by the administrator in Settings > Users.
  final List<String> monitorSections;
  const UserProfile({
    required this.uid,
    required this.role,
    this.name = '',
    this.email = '',
    this.phone = '',
    this.studentId = '',
    this.access,
    this.legacy = false,
    this.pending = false,
    this.approved = true,
    this.rejected = false,
    this.financeSections = const [],
    this.monitorSections = const [],
  });

  static const roles = ['admin', 'teacher', 'affairs', 'finance', 'student'];
  static String roleLabel(String r) => r == 'affairs'
      ? 'Student affairs'
      : (r.isEmpty ? r : r[0].toUpperCase() + r.substring(1));

  bool get isAdmin => role == 'admin';

  /// Only administrators can open everything. Full access can only be
  /// given by assigning the Admin account type.
  bool get fullAccess => role == 'admin';

  List<String> effectiveAccess(AppSettings st) {
    if (fullAccess) return AppPages.all;
    final base = _baseAccess(st);
    // a class monitor always gets the Daily attendance page
    if (monitorSections.isNotEmpty && !base.contains(AppPages.daily)) {
      return [...base, AppPages.daily];
    }
    return base;
  }

  List<String> _baseAccess(AppSettings st) {
    final a = access;
    if (a != null) return a;
    if (role == 'student') return st.studentAccess;
    if (role == 'affairs') return st.affairsAccess;
    if (role == 'finance') return st.financeAccess;
    return st.teacherAccess;
  }

  factory UserProfile.fromDoc(DocumentSnapshot<Map<String, dynamic>> d) {
    final m = d.data();
    if (m == null) return UserProfile(uid: d.id, role: 'admin', legacy: true);
    final r = '${m['role'] ?? 'teacher'}';
    final a = m['access'];
    return UserProfile(
      uid: d.id,
      role: roles.contains(r) ? r : 'teacher',
      name: '${m['name'] ?? ''}',
      email: '${m['email'] ?? ''}',
      phone: '${m['phone'] ?? ''}',
      studentId: '${m['studentId'] ?? ''}',
      pending: m['pendingLogin'] == true,
      approved: m['approved'] != false,
      rejected: m['rejected'] == true,
      financeSections: m['financeSections'] is List
          ? [
        for (final e in (m['financeSections'] as List))
          if (e is String) e
      ]
          : const <String>[],
      monitorSections: m['monitorSections'] is List
          ? [
        for (final e in (m['monitorSections'] as List))
          if (e is String) e
      ]
          : const <String>[],
      access: a is List
          ? [
        for (final e in a)
          if (e is String && AppPages.all.contains(e)) e
      ]
          : null,
    );
  }

  /// The profile of the signed-in person, live.
  static Stream<UserProfile> watchMine() {
    final uid = FirebaseAuth.instance.currentUser?.uid ?? '';
    return FirebaseFirestore.instance
        .collection('users')
        .doc(uid)
        .snapshots()
        .map(UserProfile.fromDoc);
  }
}

final _profilesEnsured = <String>{};

/// Every account must be a user in the list (Firestore: users/{uid}).
/// Accounts made before permissions existed have no profile yet, so one is
/// created the first time they open the app:
///  - when there is no administrator yet, that account becomes the
///    administrator (the owner of the app);
///  - every other old account becomes a Teacher with the default access.
/// The administrator can change roles and access in Settings.
Future<void> ensureUserProfile(User user) async {
  if (!_profilesEnsured.add(user.uid)) return; // once per account and session
  try {
    final users = FirebaseFirestore.instance.collection('users');
    final mine = users.doc(user.uid);
    if ((await mine.get()).exists) return;
    final admins = await users.where('role', isEqualTo: 'admin').limit(1).get();
    final email = user.email ?? '';
    final firstAdmin = admins.docs.isEmpty;
    await mine.set({
      'role': firstAdmin
          ? 'admin'
          : (email.endsWith('@$kStudentEmailDomain') ? 'student' : 'teacher'),
      'name': email.contains('@') ? email.split('@').first : email,
      'email': email,
      // a deleted user who signs in again must be approved again
      if (!firstAdmin) 'approved': false,
      'createdAt': FieldValue.serverTimestamp(),
    });
  } catch (e) {
    debugPrint('User profile could not be created: $e');
  }
}

/// subject -> forms taught, read from a teacher document. Records saved
/// before per-subject forms existed only have the two lists `subjects` and
/// `forms`: every subject then applies to every form of the teacher.
Map<String, List<String>> parseTeacherAssignments(Map? m) {
  final out = <String, List<String>>{};
  final a = m?['assignments'];
  if (a is Map) {
    for (final s in ExamService.subjects) {
      final v = a[s];
      if (v is List) {
        final fs = [
          for (final f in ExamService.forms)
            if (v.contains(f)) f
        ];
        if (fs.isNotEmpty) out[s] = fs;
      }
    }
    if (out.isNotEmpty) return out;
  }
  List<String> list(String k) {
    final v = m?[k];
    return v is List ? [for (final e in v) if (e is String) e] : <String>[];
  }

  final subs = list('subjects'), forms = list('forms');
  if (subs.isNotEmpty && forms.isNotEmpty) {
    for (final s in ExamService.subjects) {
      if (subs.contains(s)) {
        out[s] = [
          for (final f in ExamService.forms)
            if (forms.contains(f)) f
        ];
      }
    }
  }
  return out;
}

/// The forms used by any subject of [a] (in the usual order).
List<String> formsOfAssignments(Map<String, List<String>> a) => [
  for (final f in ExamService.forms)
    if (a.values.any((l) => l.contains(f))) f
];

/// "Islamic (Form3, Form4) · Maths (Form4)"
String assignmentsText(Map<String, List<String>> a) => [
  for (final s in ExamService.subjects)
    if (a[s] != null && a[s]!.isNotEmpty) '$s (${a[s]!.join(', ')})'
].join(' · ');

/// What a teacher may see: ONLY the subjects and forms (classes) that were
/// filled in when the account was created (Firestore: teachers/{uid}).
/// Administrators, students and old accounts without a profile are not
/// restricted by this.
class TeacherScope {
  final bool restricted;

  /// Set by the administrator (Teachers > edit): this person sees EVERY
  /// section to take attendance, but still no exam marks of other subjects.
  final bool allSections;
  final List<String> subjects, forms;

  /// subject -> the forms in which this teacher teaches that subject.
  final Map<String, List<String>> assignments;

  /// A student account: sees only the own record (see [_LinkStudentBody]).
  final bool isStudent;
  final String studentId, sectionId;

  /// A Finance account: limited to these classes (empty = every class).
  final bool isFinance;
  final List<String> financeSectionIds;
  const TeacherScope({
    this.restricted = false,
    this.allSections = false,
    this.subjects = const [],
    this.forms = const [],
    this.assignments = const {},
    this.isStudent = false,
    this.studentId = '',
    this.sectionId = '',
    this.isFinance = false,
    this.financeSectionIds = const [],
  });

  /// Limited to a part of the data (a teacher or a student).
  bool get scoped => restricted || isStudent;

  static const open = TeacherScope();

  /// The subjects this person may see (in the usual order).
  List<String> get subjectList => restricted
      ? [for (final s in ExamService.subjects) if (subjects.contains(s)) s]
      : ExamService.subjects;

  /// The forms this person may see (in the usual order).
  List<String> get formList => restricted
      ? [for (final f in ExamService.forms) if (forms.contains(f)) f]
      : ExamService.forms;

  bool allowsSubject(String s) => !restricted || subjects.contains(s);
  bool allowsForm(String f) => !restricted || forms.contains(f);

  /// True when this person teaches [subject] in [form] (the exact pair).
  bool allows(String subject, String form) {
    if (!restricted) return true;
    if (assignments.isNotEmpty) {
      return assignments[subject]?.contains(form) ?? false;
    }
    return subjects.contains(subject) && forms.contains(form);
  }

  List<SectionInfo> filterSections(List<SectionInfo> l) {
    if (isStudent) return [for (final s in l) if (s.id == sectionId) s];
    if (isFinance && financeSectionIds.isNotEmpty) {
      // the ticked classes and the sections they were divided into
      final keys = {
        for (final s in l)
          if (financeSectionIds.contains(s.id)) '${s.form}|${s.classKey}'
      };
      return [for (final s in l) if (keys.contains('${s.form}|${s.classKey}')) s];
    }
    if (allSections) return l;
    return restricted ? [for (final s in l) if (forms.contains(s.form)) s] : l;
  }
}

/// The scope of the signed-in person. Kept up to date by [_ScopeGate].
final ValueNotifier<TeacherScope> teacherScope =
ValueNotifier(TeacherScope.open);

/// Loads the scope (role + subjects + forms) of the signed-in person and
/// shows [child] only once it is known, so a teacher never sees, even for a
/// moment, something that is not theirs.
class _ScopeGate extends StatefulWidget {
  final Widget child;
  const _ScopeGate({required this.child});

  @override
  State<_ScopeGate> createState() => _ScopeGateState();
}

class _ScopeGateState extends State<_ScopeGate> {
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _userSub;
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _teacherSub;
  StreamSubscription<DocumentSnapshot<Map<String, dynamic>>>? _stuSub;
  Map<String, dynamic>? _user, _teacher, _stu;
  bool _userDone = false, _teacherDone = false, _stuDone = true;
  String _stuWatched = '';

  bool get _ready => _userDone && _teacherDone && _stuDone;

  @override
  void initState() {
    super.initState();
    final uid = FirebaseAuth.instance.currentUser?.uid;
    if (uid == null) {
      _userDone = _teacherDone = true;
      return;
    }
    final db = FirebaseFirestore.instance;
    _userSub = db.collection('users').doc(uid).snapshots().listen((d) {
      _user = d.data();
      _userDone = true;
      _update();
    }, onError: (_) {
      _user = null; // profile unreadable (rules problem): nothing is hidden
      _userDone = true;
      _update();
    });
    _teacherSub = db.collection('teachers').doc(uid).snapshots().listen((d) async {
      _teacher = d.data();
      if (_teacher == null) {
        // Added by the administrator: the record has its own id, so find it
        // by the email of this account.
        final mail = FirebaseAuth.instance.currentUser?.email ?? '';
        if (mail.isNotEmpty) {
          try {
            final t = await findTeacherByEmail(mail);
            if (t != null) {
              _teacher = {
                'allSections': t.allSections,
                'subjects': t.subjects,
                'forms': t.forms,
                'assignments': t.assignments,
              };
            }
          } catch (_) {}
        }
      }
      _teacherDone = true;
      if (mounted) _update();
    }, onError: (_) {
      _teacher = null;
      _teacherDone = true;
      _update();
    });
  }

  List<String> _list(String k) {
    final v = _teacher?[k];
    return v is List ? [for (final e in v) if (e is String) e] : <String>[];
  }

  void _update() {
    final role = _user == null ? '' : '${_user!['role']}';
    if (role == 'student') {
      final sid = '${_user!['studentId'] ?? ''}';
      if (sid != _stuWatched) {
        _stuSub?.cancel();
        _stuWatched = sid;
        _stu = null;
        if (sid.isEmpty) {
          _stuDone = true;
        } else {
          _stuDone = false;
          _stuSub = FirebaseFirestore.instance
              .collection('students')
              .doc(sid)
              .snapshots()
              .listen((d) {
            _stu = d.data();
            _stuDone = true;
            _update();
          }, onError: (_) {
            _stu = null;
            _stuDone = true;
            _update();
          });
        }
      }
    }
    if (!_ready) return;
    if (role == 'student') {
      teacherScope.value = TeacherScope(
        isStudent: true,
        studentId: _stuWatched,
        sectionId: '${_stu?['sectionId'] ?? ''}',
      );
    } else if (role == 'finance') {
      final fs = _user?['financeSections'];
      teacherScope.value = TeacherScope(
        isFinance: true,
        financeSectionIds: fs is List ? [for (final e in fs) if (e is String) e] : const <String>[],
      );
    } else if (role == 'teacher') {
      final asg = parseTeacherAssignments(_teacher);
      teacherScope.value = TeacherScope(
          restricted: true,
          // only when the administrator ticked it for this person
          allSections: _teacher?['allSections'] == true,
          subjects: [
            for (final s in ExamService.subjects)
              if (asg.containsKey(s)) s
          ],
          forms: formsOfAssignments(asg),
          assignments: asg);
    } else {
      teacherScope.value = TeacherScope.open;
    }
    if (mounted) setState(() {});
  }

  @override
  void dispose() {
    _userSub?.cancel();
    _teacherSub?.cancel();
    _stuSub?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    if (!_ready) {
      return const Scaffold(body: Center(child: CircularProgressIndicator()));
    }
    return widget.child;
  }
}

/// A person who created an account on the login screen cannot open the app
/// until an administrator approves it (Settings > Users & permissions).
/// The screen opens by itself the moment the account is approved.
class _ApprovalGate extends StatefulWidget {
  final Widget child;
  const _ApprovalGate({required this.child});

  @override
  State<_ApprovalGate> createState() => _ApprovalGateState();
}

class _ApprovalGateState extends State<_ApprovalGate> {
  late final Stream<UserProfile> _stream = UserProfile.watchMine();
  bool _ensuring = false, _ensured = false;

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<UserProfile>(
      stream: _stream,
      builder: (context, snap) {
        // profile unreadable (rules problem): nothing is blocked
        if (snap.hasError) return widget.child;
        final p = snap.data;
        if (p == null) {
          return const Scaffold(body: Center(child: CircularProgressIndicator()));
        }
        if (!p.legacy) {
          _ensuring = false;
          _ensured = false;
        } else if (!_ensured) {
          // No profile (e.g. the user was deleted): create it first, as
          // unapproved, and never show the app with full access meanwhile.
          final u = FirebaseAuth.instance.currentUser;
          if (u != null && !_ensuring) {
            _ensuring = true;
            WidgetsBinding.instance.addPostFrameCallback((_) {
              _profilesEnsured.remove(u.uid);
              ensureUserProfile(u).whenComplete(() {
                if (mounted) setState(() => _ensured = true);
              });
            });
          }
          if (u != null) {
            return const Scaffold(
                body: Center(child: CircularProgressIndicator()));
          }
        }
        if (p.approved) return widget.child;
        return _WaitingApprovalScreen(profile: p);
      },
    );
  }
}

