  Future<void> _toggleExam(AppSettings s, String exam, bool open) async {
    if (!open && s.openExams.length <= 1) {
      _toast('Keep at least one exam open.');
      return;
    }
    final closed = {...s.closedExams};
    open ? closed.remove(exam) : closed.add(exam);
    await _save({
      'closedExams': [for (final e in s.examOptions) if (closed.contains(e)) e]
    }, open ? '\"$exam\" opened' : '\"$exam\" closed');
  }

  /// Makes [exam] the active exam: it is opened and every other exam is
  /// closed, so teachers and students only work on it. Other exams can still
  /// be opened again with their tick box.
  Future<void> _makeActive(AppSettings s, String exam) async {
    setState(() => _busy = true);
    try {
      await switchActiveExam(context, exam);
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

