Future<void> _pickDate() async {
final p = await showDatePicker(
context: context,
initialDate: _date,
firstDate: DateTime(2020),
lastDate: DateTime.now(),
selectableDayPredicate: (d) => d.weekday <= DateTime.friday,
);
if (p == null || !mounted) return;
setState(() => _date = DateTime(p.year, p.month, p.day));
_load();
}

Widget _msg(String t, {bool error = false}) => Padding(
padding: const EdgeInsets.all(24),
child: Center(
child: Text(t,
textAlign: TextAlign.center,
style: TextStyle(color: error ? Colors.red : Colors.black54))),
);

@override
Widget build(BuildContext context) {
return StreamBuilder<UserProfile>(
stream: _me,
builder: (context, meSnap) {
if (meSnap.hasError) return _msg('${meSnap.error}', error: true);
final me = meSnap.data;
if (me == null) {
return const Center(child: CircularProgressIndicator());
}
return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
stream: _secs,
builder: (context, secSnap) =>
StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
stream: _stus,
builder: (context, stuSnap) {
final err = secSnap.error ?? stuSnap.error;
if (err != null) {
return _msg('Could not load: $err', error: true);
}
if (!secSnap.hasData || !stuSnap.hasData) {
return const Center(child: CircularProgressIndicator());
}
return _content(me, secSnap.data!, stuSnap.data!);
},
),
);
},
);
}

Widget _content(UserProfile me, QuerySnapshot<Map<String, dynamic>> secDocs,
QuerySnapshot<Map<String, dynamic>> stuDocs) {
_secsSnap = secDocs;
_stusSnap = stuDocs;
final allSecs = [for (final d in secDocs.docs) SectionInfo.fromDoc(d)];
// a person with assigned classes sees ONLY those classes; they can take
// today only (Student affairs keep any date)
final restricted = me.monitorSections.isNotEmpty && !me.fullAccess;
final todayOnly = restricted && me.role != 'affairs';
final classes = [
for (final c in allSecs)
if (!c.isSub && (!restricted || me.monitorSections.contains(c.id))) c
]..sort((a, b) {
final f = a.form.compareTo(b.form);
return f != 0 ? f : a.name.compareTo(b.name);
});
if (classes.isEmpty) {
return _msg(restricted
? 'None of your classes was found. Ask the administrator.'
    : 'There are no classes yet.');
}
final cid =
classes.any((c) => c.id == _classId) ? _classId! : classes.first.id;
if (cid != _classId) {
WidgetsBinding.instance.addPostFrameCallback((_) {
if (!mounted) return;
_classId = cid;
_load();
});
}
final cls = classes.firstWhere((c) => c.id == cid);

// students of the class: the whole class + the ones that exist only in a
// divided section of it (a student saved in both counts once)
final subIds = {
for (final c in allSecs)
if (c.isSub &&
c.form == cls.form &&
c.classKey == cls.name.toUpperCase())
c.id
};
final inClass = <Map<String, String>>[];
final inSubs = <Map<String, String>>[];
for (final d in stuDocs.docs) {
final m = d.data();
final sid = '${m['sectionId'] ?? ''}';
final row = {
'id': d.id,
'name': '${m['name'] ?? ''}'.trim(),
'no': '${m['studentNo'] ?? ''}'.trim(),
'created':
'${(m['createdAt'] is Timestamp ? (m['createdAt'] as Timestamp).millisecondsSinceEpoch : 0)}',
};
if (sid == cid) {
inClass.add(row);
} else if (subIds.contains(sid)) {
inSubs.add(row);
}
}
final names = {for (final r in inClass) r['name']!.toLowerCase()};
final students = [
...inClass,
for (final r in inSubs)
if (!names.contains(r['name']!.toLowerCase())) r
]..sort((a, b) =>
a['name']!.toLowerCase().compareTo(b['name']!.toLowerCase()));

final today = DateTime.now();
final canEdit = !todayOnly || _sameDay(_date, today);
final isWeekend = today.weekday > DateTime.friday;
_current = [for (final r in students) r['id']!];

// fixed numbers: saved ones first; a student without a number yet goes
// after the last number until it is saved
final studentsNow = [...students];
WidgetsBinding.instance.addPostFrameCallback((_) {
if (mounted) _ensureNumbers(cid, studentsNow);
});
final noOf = _assignRollNumbers(
_nums[cid] ?? const {}, students, _numNames[cid] ?? const {});
students.sort((a, b) {
final c = noOf[a['id']]!.compareTo(noOf[b['id']]!);
return c != 0
? c
    : a['name']!.toLowerCase().compareTo(b['name']!.toLowerCase());
});
final absent = students.where((r) => _marks[r['id']] == 'a').length;
final present = students.length - absent;
// how many numbers are vacant (a removed student)
final usedNos = {for (final r in students) noOf[r['id']]!};
final vacantTotal = usedNos.isEmpty
? 0
    : usedNos.reduce((a, b) => a > b ? a : b) - usedNos.length;
// rows shown, in number order. A vacant number (a removed student) is
// shown as an empty slot (negative number) when the whole list is shown.
final items = <int>[];
var prevNo = 0;
for (var i = 0; i < students.length; i++) {
final n = noOf[students[i]['id']]!;
if (_show == 'all') {
for (var g = prevNo + 1; g < n; g++) {
items.add(-g);
}
}
if (_show == 'all' ||
(_show == 'a') == (_marks[students[i]['id']] == 'a')) {
items.add(i);
}
if (n > prevNo) prevNo = n;
}

return ListView(
padding: const EdgeInsets.fromLTRB(16, 12, 16, 32),
children: [
// only the administrator sees the report
if (me.fullAccess) _reportPanel(classes),
DropdownButtonFormField<String>(
value: cid,
isExpanded: true,
decoration: const InputDecoration(
labelText: 'Class',
border: OutlineInputBorder(),
isDense: true,
prefixIcon: Icon(Icons.groups),
),
items: [
for (final c in classes)
DropdownMenuItem(value: c.id, child: Text(c.fullName)),
],
onChanged: (v) {
if (v == null || v == _classId) return;
setState(() => _classId = v);
_load();
},
),
const SizedBox(height: 10),
Wrap(
spacing: 10,
runSpacing: 10,
crossAxisAlignment: WrapCrossAlignment.center,
children: [
OutlinedButton.icon(
onPressed: todayOnly ? null : _pickDate,
icon: const Icon(Icons.calendar_today, size: 18),
label: Text(DateFormat('EEE d MMM yyyy').format(_date)),
),
SegmentedButton<String>(
showSelectedIcon: false,
segments: const [
ButtonSegment(
value: 'am',
icon: Icon(Icons.looks_one_outlined, size: 18),
label: Text('Shift A')),
ButtonSegment(
value: 'pm',
icon: Icon(Icons.looks_two_outlined, size: 18),
label: Text('Shift B')),
],
selected: {_session},
onSelectionChanged: (v) {
setState(() => _session = v.first);
_load();
},
),
]),
if (todayOnly && isWeekend)
const Padding(
padding: EdgeInsets.only(top: 10),
child: Text(
'Attendance is taken Monday to Friday. Today is a weekend, '
'so you can only look at the last school day.',
style: TextStyle(fontSize: 12, color: Colors.black54)),
)
else if (todayOnly)
const Padding(
padding: EdgeInsets.only(top: 10),
child: Text('You can take today\'s attendance of your classes.',
style: TextStyle(fontSize: 12, color: Colors.black54)),
),
const SizedBox(height: 12),
// the counts are also the filter of the list below
Wrap(spacing: 8, runSpacing: 6, children: [
ChoiceChip(
visualDensity: VisualDensity.compact,
showCheckmark: false,
selected: _show == 'all',
label: Text('All ${students.length}',
style: const TextStyle(
fontWeight: FontWeight.w600, fontSize: 12)),
onSelected: (_) => setState(() => _show = 'all'),
),
ChoiceChip(
visualDensity: VisualDensity.compact,
showCheckmark: false,
selected: _show == 'p',
selectedColor: _presentColor.withOpacity(0.2),
side: const BorderSide(color: _presentColor),
label: Text('Present $present',
style: const TextStyle(
color: _presentColor,
fontWeight: FontWeight.w600,
fontSize: 12)),
onSelected: (_) => setState(() => _show = 'p'),
),
ChoiceChip(
visualDensity: VisualDensity.compact,
showCheckmark: false,
selected: _show == 'a',
selectedColor: _absentColor.withOpacity(0.2),
side: const BorderSide(color: _absentColor),
label: Text('Absent $absent',
style: const TextStyle(
color: _absentColor,
fontWeight: FontWeight.w600,
fontSize: 12)),
onSelected: (_) => setState(() => _show = 'a'),
),
if (_exists)
const Chip(
visualDensity: VisualDensity.compact,
label: Text('Register saved', style: TextStyle(fontSize: 12)),
),
if (!restricted && vacantTotal > 0)
ActionChip(
visualDensity: VisualDensity.compact,
avatar: const Icon(Icons.delete_sweep_outlined, size: 16),
label: Text('Remove $vacantTotal vacant',
style: const TextStyle(fontSize: 12)),
onPressed: () =>
_removeAllVacant(cid, noOf, students, vacantTotal),
),
]),
const SizedBox(height: 10),
Row(children: [
TextButton.icon(
onPressed: !canEdit || students.isEmpty
? null
    : () => setState(() {
_marks.clear();
_dirty = true;
}),
icon: const Icon(Icons.check_box, size: 18),
label: const Text('Tick all'),
),
TextButton.icon(
onPressed: !canEdit || students.isEmpty
? null
    : () => setState(() {
for (final r in students) {
_marks[r['id']!] = 'a';
}
_dirty = true;
}),
icon: const Icon(Icons.check_box_outline_blank, size: 18),
label: const Text('Untick all'),
),
const Spacer(),
FilledButton.icon(
onPressed: !canEdit || _saving || (_exists && !_dirty)
? null
    : () => _save(me),
icon: _saving
? const SizedBox(
width: 16,
height: 16,
child: CircularProgressIndicator(strokeWidth: 2))
    : const Icon(Icons.save, size: 18),
label: Text(_exists && !_dirty ? 'Saved' : 'Save'),
),
]),
const SizedBox(height: 8),
if (_loading)
const Padding(
padding: EdgeInsets.all(24),
child: Center(child: CircularProgressIndicator()))
else if (_error != null)
_msg('Could not load this register.\n$_error', error: true)
else if (students.isEmpty)
_msg('This class has no students yet.')
else if (items.isEmpty)
_msg(_show == 'a'
? 'No student is absent.'
    : 'No student is present.')
else
for (final i in items)
if (i < 0)
// vacant number: the student was removed
Container(
margin: const EdgeInsets.symmetric(vertical: 3),
padding:
const EdgeInsets.symmetric(horizontal: 12, vertical: 2),
decoration: BoxDecoration(
borderRadius: BorderRadius.circular(12),
border: Border.all(color: Colors.black12),
),
child: Row(children: [
SizedBox(
width: 34,
child: Text('${-i}',
style: const TextStyle(
fontSize: 12, color: Colors.black38))),
const Text('Vacant',
style: TextStyle(
fontSize: 12.5,
fontStyle: FontStyle.italic,
color: Colors.black38)),
const Spacer(),
// removing the number moves the next students up by one
if (!restricted)
IconButton(
tooltip: 'Remove this number',
visualDensity: VisualDensity.compact,
iconSize: 19,
color: Colors.black45,
icon: const Icon(Icons.delete_outline),
onPressed: () =>
_removeVacant(cid, -i, noOf, students),
),
]),
)
else
Card(
margin: const EdgeInsets.symmetric(vertical: 3),
child: Padding(
padding:
const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
child: Row(children: [
SizedBox(
width: 34,
child: Text('${noOf[students[i]['id']]}',
style: const TextStyle(
fontSize: 12.5,
fontWeight: FontWeight.w700,
color: Colors.black54))),
Expanded(
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Text(students[i]['name']!,
style: const TextStyle(
fontSize: 14.5, fontWeight: FontWeight.w600)),
if (students[i]['no']!.isNotEmpty)
Text('ID ${students[i]['no']}',
style: const TextStyle(
fontSize: 11.5, color: Colors.black54)),
]),
),
Text(_marks[students[i]['id']] == 'a' ? 'Absent' : 'Present',
style: TextStyle(
fontSize: 12,
fontWeight: FontWeight.w600,
color: _marks[students[i]['id']] == 'a'
? _absentColor
    : _presentColor)),
Checkbox(
value: _marks[students[i]['id']] != 'a',
activeColor: _presentColor,
onChanged: !canEdit
? null
    : (on) => setState(() {
if (on == true) {
_marks.remove(students[i]['id']);
} else {
_marks[students[i]['id']!] = 'a';
}
_dirty = true;
}),
),
]),
),
),
],
);
}
}

class AttendanceScreen extends StatefulWidget {
const AttendanceScreen({super.key});

@override
State<AttendanceScreen> createState() => _AttendanceScreenState();
}

class _AttendanceScreenState extends State<AttendanceScreen> {
final _service = SchoolService();
String? _sectionId;
// Selected subjects. Empty = "All subjects" (whole-day register).
// One or more subjects = the same marks are saved for each of them.
final Set<String> _subjects = {};

List<String> get _subjectOrder {
final all = teacherScope.value.subjectList;
final sel = _subjects.toList();
sel.sort((a, b) => all.indexOf(a).compareTo(all.indexOf(b)));
return sel;
}

String get _subjectLabel =>
_subjects.isEmpty ? 'All subjects' : _subjectOrder.join(', ');
DateTime _date = DateTime.now();
Map<String, String> _marks = {};
Map<String, String> _notes = {}; // studentId -> note (only for absent)
bool _loading = false;
bool _saving = false;
bool _dirty = false;
bool _onlyUnmarked = false;
int _token = 0; // ignores answers of an older section / date / subject

String get _dateKey => DateFormat('yyyy-MM-dd').format(_date);

Future<void> _load() async {
final id = _sectionId;
if (id == null) return;
final t = ++_token;
setState(() {
_loading = true;
_dirty = false;
});
try {
// Empty selection = whole day. Several subjects: merge their registers.
// A student absent in ANY chosen subject is shown absent for all of them.
final keys = _subjects.isEmpty ? <String>[''] : _subjectOrder;
final merged = <String, String>{};
final mergedNotes = <String, String>{};
for (final k in keys) {
final m = await _service.getAttendance(id, _dateKey, subject: k);
final n = await _service.getAttendanceNotes(id, _dateKey, subject: k);
for (final e in m.entries) {
if (merged[e.key] == 'absent') continue;
merged[e.key] = e.value;
}
for (final e in n.entries) {
if (e.value.trim().isNotEmpty) mergedNotes.putIfAbsent(e.key, () => e.value);
}
}
if (!mounted || t != _token) return;
setState(() {
_notes = mergedNotes;
// the Late option was removed: old late marks count as present
_marks = {
for (final e in merged.entries)
e.key: e.value == 'late' ? 'present' : e.value,
};
_loading = false;
});
} catch (e) {
if (!mounted || t != _token) return;
setState(() {
_marks = {};
_notes = {};
_loading = false;
});
ScaffoldMessenger.of(context)
    .showSnackBar(SnackBar(content: Text('Could not load: $e')));
}
}

/// Asks before throwing away marks that were not saved yet.
Future<bool> _okToLeave() async {
if (!_dirty) return true;
final r = await showDialog<bool>(
context: context,
builder: (c) => AlertDialog(
title: const Text('Discard unsaved changes?'),
content: const Text('The marks you changed have not been saved.'),
actions: [
TextButton(
onPressed: () => Navigator.pop(c, false),
child: const Text('Keep editing')),
FilledButton(
onPressed: () => Navigator.pop(c, true),
child: const Text('Discard')),
],
),
);
return r ?? false;
}

Future<void> _setDate(DateTime d) async {
if (!await _okToLeave() || !mounted) return;
setState(() => _date = d);
_load();
}

Future<void> _pickDate() async {
final d = await showDatePicker(
context: context,
initialDate: _date,
firstDate: DateTime(2020),
lastDate: DateTime.now().add(const Duration(days: 365)),
);
if (d != null) _setDate(d);
}

/// Add / edit / remove the note of a student.
Future<void> _editNote(StudentInfo s) async {
final r = await showDialog<String>(
context: context,
builder: (_) => _NoteDialog(name: s.name, initial: _notes[s.id] ?? ''),
);
if (r == null || !mounted) return;
setState(() {
if (r.trim().isEmpty) {
_notes.remove(s.id);
} else {
_notes[s.id] = r.trim();
}
_dirty = true;
});
}

Future<void> _save(List<StudentInfo> students) async {
final id = _sectionId;
if (id == null) return;
setState(() => _saving = true);
final messenger = ScaffoldMessenger.of(context);
try {
final records = {
for (final s in students)
if (_marks[s.id] != null) s.id: _marks[s.id]!,
};
// a note can be written for any student (present, absent or not marked)
final notes = {
for (final s in students)
if ((_notes[s.id] ?? '').trim().isNotEmpty)
s.id: _notes[s.id]!.trim(),
};
final keys = _subjects.isEmpty ? <String>[''] : _subjectOrder;
for (final k in keys) {
await _service.saveAttendance(id, _dateKey, records,
subject: k, notes: notes);
}
if (!mounted) return;
setState(() {
_saving = false;
_dirty = false;
});
messenger.showSnackBar(SnackBar(
content: Text(
'Saved · ${records.length} of ${students.length} students marked')));
} catch (e) {
if (mounted) setState(() => _saving = false);
messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
}
}

/// Dialog with checkboxes: "All subjects" or any number of subjects.
Future<void> _pickSubjects() async {
final all = teacherScope.value.subjectList;
final temp = {..._subjects};
final result = await showDialog<Set<String>>(
context: context,
builder: (c) => StatefulBuilder(
builder: (c, setD) => AlertDialog(
title: const Text('Subjects'),
contentPadding: const EdgeInsets.fromLTRB(8, 12, 8, 0),
content: SizedBox(
width: 360,
child: ListView(shrinkWrap: true, children: [
CheckboxListTile(
value: temp.isEmpty,
title: const Text('All subjects'),
controlAffinity: ListTileControlAffinity.leading,
onChanged: (_) => setD(temp.clear),
),
const Divider(height: 1),
for (final s in all)
CheckboxListTile(
value: temp.contains(s),
title: Text(s),
controlAffinity: ListTileControlAffinity.leading,
onChanged: (v) =>
setD(() => v == true ? temp.add(s) : temp.remove(s)),
),
]),
),
actions: [
TextButton(
onPressed: () => Navigator.pop(c),
child: const Text('Cancel')),
FilledButton(
onPressed: () => Navigator.pop(c, temp),
child: const Text('Done')),
],
),
),
);
if (result == null || !mounted) return;
if (result.length == _subjects.length && result.containsAll(_subjects)) {
return;
}
if (!await _okToLeave() || !mounted) return;
setState(() {
_subjects
..clear()
..addAll(result);
});
_load();
}

void _openReport() {
Navigator.of(context).push(MaterialPageRoute(
builder: (_) =>
AttendanceReportScreen(sectionId: _sectionId, date: _date),
));
}

// ---------------- widgets ----------------

