),
]),
]),
);

Widget _stat(IconData icon, String label, int n, Color c) => Padding(
padding: const EdgeInsets.only(right: 14),
child: Row(mainAxisSize: MainAxisSize.min, children: [
Icon(icon, size: 16, color: c),
const SizedBox(width: 4),
Text('$label ',
style: TextStyle(fontSize: 13, color: Colors.grey.shade700)),
Text('$n',
style:
const TextStyle(fontSize: 13, fontWeight: FontWeight.w700)),
]),
);

Widget _markButton(StudentInfo s, String value, IconData icon, Color c,
String label) {
final selected = _marks[s.id] == value;
return Tooltip(
message: label,
child: InkWell(
borderRadius: BorderRadius.circular(10),
onTap: _saving
? null
    : () => setState(() {
if (selected) {
_marks.remove(s.id);
} else {
_marks[s.id] = value;
}
_dirty = true;
}),
child: AnimatedContainer(
duration: const Duration(milliseconds: 120),
width: 46,
height: 38,
margin: const EdgeInsets.only(left: 6),
decoration: BoxDecoration(
color: selected ? c : Colors.transparent,
border: Border.all(color: selected ? c : Colors.grey.shade400),
borderRadius: BorderRadius.circular(10),
),
child: Icon(icon,
size: 20, color: selected ? Colors.white : Colors.grey.shade600),
),
),
);
}

Widget _list(List<StudentInfo> students) {
final t = _Tally();
for (final s in students) {
t.add(_marks[s.id]);
}
final unmarked = students.length - t.total;
final shown = [
for (var i = 0; i < students.length; i++)
if (!_onlyUnmarked || _marks[students[i].id] == null) i,
];

return Column(children: [
// ---- summary ----
Padding(
padding: const EdgeInsets.fromLTRB(16, 0, 16, 6),
child: Card(
margin: EdgeInsets.zero,
child: Padding(
padding: const EdgeInsets.fromLTRB(12, 10, 4, 10),
child: Column(children: [
Row(children: [
Expanded(
child: Wrap(runSpacing: 4, children: [
_stat(Icons.check_circle, 'Present', t.p, kGreen),
_stat(Icons.cancel, 'Absent', t.a, kRed),
_stat(Icons.help, 'Left', unmarked, Colors.grey),
]),
),
FilledButton.tonalIcon(
onPressed: _saving
? null
    : () => setState(() {
for (final s in students) {
_marks[s.id] = 'present';
}
_dirty = true;
}),
icon: const Icon(Icons.done_all, size: 18),
label: const Text('All present'),
style: FilledButton.styleFrom(
visualDensity: VisualDensity.compact),
),
PopupMenuButton<String>(
tooltip: 'More',
enabled: !_saving,
icon: const Icon(Icons.more_vert),
onSelected: (v) => setState(() {
if (v == 'present') {
for (final s in students) {
_marks[s.id] = 'present';
}
} else if (v == 'rest') {
for (final s in students) {
_marks.putIfAbsent(s.id, () => 'present');
}
} else {
_marks.clear();
}
_dirty = true;
}),
itemBuilder: (_) => const [
PopupMenuItem(
value: 'rest', child: Text('Mark the rest present')),
PopupMenuItem(value: 'clear', child: Text('Clear all')),
],
),
]),
Padding(
padding: const EdgeInsets.only(right: 8, top: 2),
child: _StackBar(t, unmarked: unmarked, height: 6),
),
]),
),
),
),
Padding(
padding: const EdgeInsets.fromLTRB(16, 0, 16, 2),
child: Row(children: [
Text(
'${students.length} students · $_subjectLabel',
style: TextStyle(fontSize: 12, color: Colors.grey.shade700)),
const Spacer(),
FilterChip(
label: const Text('Not marked only'),
selected: _onlyUnmarked,
visualDensity: VisualDensity.compact,
labelStyle: const TextStyle(fontSize: 12),
onSelected: (v) => setState(() => _onlyUnmarked = v),
),
]),
),
// ---- students: name + 3 one-tap buttons on a single line ----
Expanded(
child: shown.isEmpty
? const Center(child: Text('Everyone is marked 🎉'))
    : ListView.builder(
padding: const EdgeInsets.fromLTRB(16, 4, 16, 8),
itemCount: shown.length,
itemBuilder: (context, k) {
final i = shown[k];
final s = students[i];
final mark = _marks[s.id];
final c = mark == 'present'
? kGreen
    : mark == 'absent'
? kRed
    : Colors.grey.shade400;
return Card(
margin: const EdgeInsets.symmetric(vertical: 3),
child: Padding(
padding: const EdgeInsets.symmetric(
horizontal: 12, vertical: 8),
child: Row(children: [
CircleAvatar(
radius: 13,
backgroundColor: c,
child: Text('${i + 1}',
style: const TextStyle(
fontSize: 11, color: Colors.white)),
),
const SizedBox(width: 10),
Expanded(
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Text(s.name,
maxLines: 2,
overflow: TextOverflow.ellipsis,
style: const TextStyle(
fontSize: 14.5, fontWeight: FontWeight.w600)),
InkWell(
onTap: _saving ? null : () => _editNote(s),
child: Padding(
padding: const EdgeInsets.only(top: 3, bottom: 1),
child: Row(mainAxisSize: MainAxisSize.min, children: [
Icon(
(_notes[s.id] ?? '').trim().isEmpty
? Icons.note_add_outlined
    : Icons.edit_note,
size: 15,
color: mark == 'absent' ? kRed : Colors.grey.shade600),
const SizedBox(width: 4),
Flexible(
child: Text(
(_notes[s.id] ?? '').trim().isEmpty
? 'Add note'
    : _notes[s.id]!.trim(),
maxLines: 2,
overflow: TextOverflow.ellipsis,
style: TextStyle(
fontSize: 12,
color: (_notes[s.id] ?? '').trim().isEmpty
? (mark == 'absent' ? kRed : Colors.grey.shade600)
    : Colors.grey.shade800,
fontStyle: (_notes[s.id] ?? '').trim().isEmpty
? FontStyle.normal
    : FontStyle.italic))),
]),
),
),
],
),
),
_markButton(
s, 'present', Icons.check, kGreen, 'Present'),
_markButton(s, 'absent', Icons.close, kRed, 'Absent'),
]),
),
);
},
),
),
SafeArea(
top: false,
child: Padding(
padding: const EdgeInsets.fromLTRB(16, 4, 16, 12),
child: SizedBox(
width: double.infinity,
child: FilledButton.icon(
onPressed: (_saving || _loading) ? null : () => _save(students),
icon: _saving
? const SizedBox(
width: 16,
height: 16,
child: CircularProgressIndicator(strokeWidth: 2))
    : const Icon(Icons.save),
label: Text(_dirty ? 'Save changes' : 'Save attendance'),
),
),
),
),
]);
}

@override
Widget build(BuildContext context) {
final Widget body;
if (_sectionId == null) {
body = const Center(
child: Padding(
padding: EdgeInsets.all(24),
child: Text('Choose a section, subject and date to take attendance.',
textAlign: TextAlign.center),
),
);
} else if (_loading) {
body = const Center(child: CircularProgressIndicator());
} else {
body = StreamBuilder<List<StudentInfo>>(
stream: _service.watchStudents(_sectionId!),
builder: (context, snap) {
if (snap.hasError) return Center(child: Text('Error: ${snap.error}'));
if (!snap.hasData) {
return const Center(child: CircularProgressIndicator());
}
if (snap.data!.isEmpty) {
return const Center(
child: Padding(
padding: EdgeInsets.all(24),
child: Text(
'This section has no students yet.\nAdd them in Sections first.',
textAlign: TextAlign.center),
),
);
}
return _list(snap.data!);
},
);
}
return Scaffold(
appBar: AppBar(title: const Text('Attendance')),
body: Align(
alignment: Alignment.topCenter,
child: ConstrainedBox(
constraints: const BoxConstraints(maxWidth: 720),
child: Column(children: [
_controls(),
Expanded(child: body),
]),
),
),
);
}
}

// ======================= FINANCE =======================

String _plainNum(double v) =>
v == v.roundToDouble() ? v.toInt().toString() : v.toString();

/// 150000 -> "150,000" (for filling an amount field).
String _commaNum(double v) => NumberFormat('#,##0.##').format(v);

/// Reads an amount typed with thousands commas: "150,000" -> 150000.
double? _parseMoney(String s) => double.tryParse(s.trim().replaceAll(',', ''));

/// Puts thousands commas in an amount field while the person types.
class _MoneyFormatter extends TextInputFormatter {
const _MoneyFormatter();

@override
TextEditingValue formatEditUpdate(TextEditingValue old, TextEditingValue v) {
final t = v.text.replaceAll(RegExp(r'[^0-9.]'), '');
final dot = t.indexOf('.');
final intPart = dot < 0 ? t : t.substring(0, dot);
final dec = dot < 0 ? '' : t.substring(dot + 1).replaceAll('.', '');
final b = StringBuffer();
for (var i = 0; i < intPart.length; i++) {
if (i > 0 && (intPart.length - i) % 3 == 0) b.write(',');
b.write(intPart[i]);
}
final out = dot < 0 ? b.toString() : '${b.toString()}.$dec';
final end = v.selection.end < 0 || v.selection.end > v.text.length
? v.text.length
    : v.selection.end;
final before =
v.text.substring(0, end).replaceAll(RegExp(r'[^0-9.]'), '').length;
var pos = 0, seen = 0;
while (pos < out.length && seen < before) {
if (out[pos] != ',') seen++;
pos++;
}
return TextEditingValue(
text: out, selection: TextSelection.collapsed(offset: pos));
}
}

/// An amount with the currency chosen in Settings > Finance.
String _money(double v) {
final cur = appSettings.value.currency.trim();
final n = NumberFormat('#,##0.##').format(v);
return cur.isEmpty ? n : '$cur $n';
}

/// One payment (Firestore: payments/{id}). `month` is the fee month it pays
/// for ("2026-11"); `date` is the day the money was received.
class _Pay {
final String id, studentId, month, method, note, date;
final double amount; // money received
final double discount; // amount forgiven for this month
const _Pay(this.id, this.studentId, this.month, this.method, this.note,
this.date, this.amount, {this.discount = 0.0});

factory _Pay.fromDoc(DocumentSnapshot<Map<String, dynamic>> d) {
final m = d.data() ?? {};
final a = m['amount'];
return _Pay(
d.id,
'${m['studentId'] ?? ''}',
'${m['month'] ?? ''}',
'${m['method'] ?? ''}',
'${m['note'] ?? ''}',
'${m['date'] ?? ''}',
a is num ? a.toDouble() : 0.0,
discount: m['discount'] is num ? (m['discount'] as num).toDouble() : 0.0,
);
}
}

class _PayInput {
final double amount;
final String method, note;
final DateTime date;
const _PayInput(this.amount, this.method, this.date, this.note);
}

