icon: Icons.edit_note,
color: const Color(0xFFEF6C00),
onTap: () => Navigator.of(context).push(MaterialPageRoute(
builder: (_) =>
ManualReportScreen(
month: _month,
sectionId: _sectionId == _allId ? null : _sectionId),
)),
),
],
),
body: Align(
alignment: Alignment.topCenter,
child: ConstrainedBox(
