child: ConstrainedBox(
constraints: const BoxConstraints(maxWidth: 720),
child: StreamBuilder<List<SectionInfo>>(
stream: _service.watchSections(),
builder: (context, secSnap) {
final sections = secSnap.data ?? const <SectionInfo>[];
_allowedIds = {for (final s in sections) s.id};
return Column(children: [
_filters(sections),
Expanded(
child: FutureBuilder<_ReportData>(
future: _future,
builder: (context, snap) {
if (snap.connectionState != ConnectionState.done) {
return const Center(child: CircularProgressIndicator());
}
if (snap.hasError) {
return Center(
child: Padding(
padding: const EdgeInsets.all(24),
child: Text('Could not load the report:\n${snap.error}',
textAlign: TextAlign.center),
));
}
_data = snap.data;
_secs = sections;
return ListView(
padding: const EdgeInsets.fromLTRB(16, 6, 16, 24),
children: [_content(snap.data!, sections)],
);
},
),
),
]);
},
),
),
),
);
}
}

// ======================= RESULTS (exam marks per student) =======================

/// Highest mark a subject can have in [exam] (set in Settings > Exams).
double maxMarkOf(String exam, [String form = '']) =>
appSettings.value.limitsFor(exam, form).maxMark;

/// Lowest mark a subject can have in [exam] (set in Settings > Exams).
double minMarkOf(String exam, [String form = '']) =>
appSettings.value.limitsFor(exam, form).minMark;

String _fmtMark(double n) =>
n == n.roundToDouble() ? n.toInt().toString() : n.toStringAsFixed(1);

/// Shown (not saved) in a mark box when attendance says the student was absent
/// in that subject. It is never a mark, so totals and averages ignore it.
const kAbsentText = 'Absent';
/// A student added AFTER the exam date of a subject has no mark to enter
/// there: the field shows "New" (locked) instead of a mark.
const kNewText = 'New';
const kNewColor = Color(0xFF1565C0);
const kCheatText = 'Cheated';
const kCheatColor = Color(0xFFC62828);
bool isNewText(String t) {
final x = t.trim().toLowerCase();
return x == 'new' || x == 'cheated';
}

/// True when [added] is later than the exam date of [subject].
bool studentIsNew(DateTime? added, String subject) {
final d = appSettings.value.subjectDateOf(subject);
if (added == null || d == null) return false;
return DateTime(added.year, added.month, added.day).isAfter(d);
}

/// Text of a locked field that is not a mark: "Absent" or "New".
bool _isAbsentText(String t) {
final x = t.trim().toLowerCase();
return x == 'absent' || x == 'new' || x == 'cheated';
}

/// Grade of a mark / average mark. The grade limits in Settings (A from 80,
/// B from 70 ...) are PERCENTAGES, so the mark is turned into a percentage
/// of [max] first (the highest subject mark of the exam, e.g. 20 -> 12.2 is
/// 61% = C). With the default max of 100 the mark is used as it is.
String _gradeOf(double avg, {double max = 100}) {
final pct = max > 0 ? avg / max * 100 : avg;
final limits = appSettings.value.grades;
for (var i = 0; i < limits.length; i++) {
if (pct >= limits[i] - 1e-9) return AppSettings.gradeLetters[i];
}
return 'F';
}

/// Highest subject mark of [exam] for [form] (100 when not set).
double _gradeMax(String exam, [String form = '']) {
final m = appSettings.value.limitsFor(exam, form).maxMark;
return m > 0 ? m : 100.0;
}

Color _gradeColor(String g) {
if (g == 'A' || g == 'B') return kGreen;
if (g == 'C' || g == 'D') return kLate;
return kRed;
}

/// Remembers the exam that was picked, so every Result screen shows the same one.
class _ResultPrefs {
static String? _picked;

/// The exams set in Settings > Exams. Only the OPEN exams are offered
/// (for everyone, the administrator included); closed ones are hidden.
/// Settings keeps at least one exam open; if none is, the full list is used
/// so the picker is never empty.
static List<String> options() {
final open = appSettings.value.openExams;
return open.isEmpty ? appSettings.value.examOptions : open;
}

/// The picked exam. If it was removed from the list, the list's
/// "Mid-term <year>" (or its first exam) is used instead.
static String get exam {
final o = options();
if (_picked != null && o.contains(_picked)) return _picked!;
final cur = appSettings.value.currentExam;
return o.contains(cur) ? cur : o.first;
}

static set exam(String v) => _picked = v;
}

/// One table of the result report: a class, a whole form, ...
class ResultReportGroup {
final String title;
final List<StudentInfo> students;
final Map<String, String> sectionLabels; // studentId -> e.g. 1A
final Map<String, ResultMarks> results; // studentId -> marks
const ResultReportGroup({
required this.title,
required this.students,
required this.sectionLabels,
required this.results,
});
}


// =====================================================================
// COMBINED REPORT: one report that joins the results of several exams,
// SUBJECT BY SUBJECT (English of every exam, Somali of every exam, ...).
//  - TOTAL MARKS mode: the marks are simply added (Mid-term 30 + Monthly1 12
//    = 42). The report shows the total of every subject, the grand total,
//    what it is out of, the % (used for the grade) and the rank.
//  - WEIGHTED % mode: every mark becomes a % of that exam's highest mark
//    (Settings > Exams > Mark limits) and the % are averaged with weights.
// =====================================================================
class CombinedRow {
final StudentInfo student;
final String classLabel;
/// subject -> exam -> mark (null = no mark in that exam)
final Map<String, Map<String, double?>> subjectRaw;
/// subject -> exam -> % of that exam's highest mark
final Map<String, Map<String, double?>> subjectPct;
/// subject -> total marks (Total mode) or weighted % (Weighted mode)
final Map<String, double?> subjectCombined;
/// subjects where at least one picked exam had no mark
final Set<String> partial;
/// grand total of the subjects (Total mode) or mean % (Weighted mode)
final double? combined;
/// what the grand total is out of (Total mode); 100 in Weighted mode
final double totalMax;
/// overall % of the student, used for the grade
final double? percent;
int rank = 0;
CombinedRow({
required this.student,
required this.classLabel,
required this.subjectRaw,
required this.subjectPct,
required this.subjectCombined,
required this.partial,
required this.combined,
required this.totalMax,
required this.percent,
});
}

class CombinedGroup {
final String title;
final bool sumMode;
final List<String> subjects; // columns, in the school's subject order
final List<CombinedRow> rows; // best first, students without marks last
const CombinedGroup({
required this.title,
required this.sumMode,
required this.subjects,
required this.rows,
});
}

String _pct1(double v) => v.toStringAsFixed(1);
String _n1(double v) => _fmtMark(double.parse(v.toStringAsFixed(1)));

/// Joins the results of [exams] subject by subject for the students of every
/// group. [sumMode] true: the marks are added. false: weighted % ([weights]
/// are relative numbers such as 10, 10, 30, 50 or 1, 1, 1, 1).
/// [missingAsZero] true: an exam without a mark counts as 0 (and its highest
/// mark stays in "out of"); false: it is left out (and the weights re-scaled).
Future<List<CombinedGroup>> buildCombinedGroups({
required List<String> exams,
required Map<String, double> weights,
required List<ResultReportGroup> groups,
bool missingAsZero = false,
bool sumMode = true,
}) async {
final svc = ResultService();
final perExam = <String, Map<String, ResultMarks>>{};
for (final e in exams) {
perExam[e] = await svc.watchResults(e).first;
}

final out = <CombinedGroup>[];
for (final g in groups) {
final rows = <CombinedRow>[];
final seen = <String>{}; // subjects that have a mark in this group
for (final s in g.students) {
final form = SchoolService.formOf(s);
final subs = <String>{
for (final e in exams) ...(perExam[e]?[s.id]?.marks.keys ?? const <String>[]),
};
final subjRaw = <String, Map<String, double?>>{};
final subjPct = <String, Map<String, double?>>{};
final subjComb = <String, double?>{};
final subjMax = <String, double>{};
final partial = <String>{};
for (final sub in subs) {
final rawM = <String, double?>{};
final pctM = <String, double?>{};
var rawSum = 0.0, maxSum = 0.0, wSum = 0.0, pSum = 0.0;
var used = 0;
for (final e in exams) {
final r = perExam[e]?[s.id];
final mark = (r == null || r.cheated) ? null : r.marks[sub];
final max = maxMarkOf(e, form);
final v = (mark == null || max <= 0) ? null : mark / max * 100;
final wt = weights[e] ?? 0;
rawM[e] = mark;
pctM[e] = v;
final present = sumMode ? mark != null : v != null;
if (present) {
used++;
if (sumMode) {
rawSum += mark!;
maxSum += max;
} else {
pSum += v! * wt;
wSum += wt;
}
} else if (missingAsZero) {
if (sumMode) {
maxSum += max;
} else {
wSum += wt;
}
}
}
subjRaw[sub] = rawM;
subjPct[sub] = pctM;
if (used == 0 || (!sumMode && wSum == 0)) {
subjComb[sub] = null;
} else {
subjComb[sub] = sumMode ? rawSum : pSum / wSum;
subjMax[sub] = maxSum;
seen.add(sub);
if (used < exams.length) partial.add(sub);
}
}
final vals = subjComb.values.whereType<double>().toList();
double? combined;
double totalMax = 100;
double? percent;
if (vals.isNotEmpty) {
final sum = vals.fold(0.0, (a, b) => a + b);
if (sumMode) {
combined = sum;
totalMax = [
for (final e in subjComb.entries)
if (e.value != null) subjMax[e.key] ?? 0
].fold(0.0, (a, b) => a + b);
percent = totalMax > 0 ? sum / totalMax * 100 : null;
} else {
combined = sum / vals.length;
percent = combined;
}
}
rows.add(CombinedRow(
student: s,
classLabel: g.sectionLabels[s.id] ?? '',
subjectRaw: subjRaw,
subjectPct: subjPct,
subjectCombined: subjComb,
partial: partial,
combined: combined,
totalMax: totalMax,
percent: percent,
));
}
final subjects = <String>[
for (final sub in ExamService.subjects)
if (seen.contains(sub)) sub,
...(seen.where((x) => !ExamService.subjects.contains(x)).toList()..sort()),
];
int byName(CombinedRow a, CombinedRow b) =>
a.student.name.toLowerCase().compareTo(b.student.name.toLowerCase());
final scored = [for (final r in rows) if (r.combined != null) r]
..sort((a, b) {
final c = b.combined!.compareTo(a.combined!);
return c != 0 ? c : byName(a, b);
});
for (var i = 0; i < scored.length; i++) {
final same = i > 0 && scored[i].combined == scored[i - 1].combined;
scored[i].rank = same ? scored[i - 1].rank : i + 1;
}
final unscored = [for (final r in rows) if (r.combined == null) r]
..sort(byName);
out.add(CombinedGroup(
title: g.title,
sumMode: sumMode,
subjects: subjects,
rows: [...scored, ...unscored]));
}
return out;
}

/// The combined report as CSV (opens in Excel). For every subject it lists
/// the mark (or %) of each picked exam and then the combined value.
/// UTF-8 with a BOM so Arabic and Somali names show correctly.
Uint8List buildCombinedCsv({
required List<String> exams,
required Map<String, double> weights,
required List<CombinedGroup> groups,
required bool missingAsZero,
bool detail = false, // also one column per exam
bool extras = false, // Total mode: Out of, %, Grade, Rank
}) {
String q(String s) => '"${s.replaceAll('"', '""')}"';
final sum = groups.isNotEmpty && groups.first.sumMode;
final total = exams.fold(0.0, (a, e) => a + (weights[e] ?? 0));
final sb = StringBuffer();
sb.writeln(q(sum
? 'Combined result report - total marks per subject'
    : 'Combined result report - weighted % per subject'));
sb.writeln(q(sum
? 'Total of: ${exams.join(' + ')}'
    : 'Weights: ${[
for (final e in exams) '$e ${_pct1((weights[e] ?? 0) / total * 100)}%'
].join(' | ')}'));
sb.writeln(q(missingAsZero
? 'A missing exam counts as 0'
    : 'A missing exam is left out'));
for (final g in groups) {
sb.writeln();
sb.writeln(q(g.title));
sb.writeln([
q('No.'),
q('Student name'),
q('ID'),
q('Class'),
for (final sub in g.subjects) ...[
if (detail)
for (final e in exams) q(sum ? '$sub - $e' : '$sub - $e (%)'),
q(detail ? (sum ? '$sub - TOTAL' : '$sub - COMBINED (%)') : sub),
],
if (sum) q('Total') else q('Average (%)'),
if (!sum || extras) ...[
if (sum) ...[q('Out of'), q('Percent (%)')],
q('Grade'),
q('Rank'),
],
].join(','));
for (var i = 0; i < g.rows.length; i++) {
final r = g.rows[i];
final c = r.combined;
final p = r.percent;
sb.writeln([
'${i + 1}',
q(r.student.name),
q(r.student.studentNo),
q(r.classLabel),
for (final sub in g.subjects) ...[
if (detail)
for (final e in exams)
sum
? (r.subjectRaw[sub]?[e] == null ? '' : _n1(r.subjectRaw[sub]![e]!))
    : (r.subjectPct[sub]?[e] == null ? '' : _pct1(r.subjectPct[sub]![e]!)),
r.subjectCombined[sub] == null
? ''
    : (sum ? _n1(r.subjectCombined[sub]!) : _pct1(r.subjectCombined[sub]!)),
],
if (sum)
(c == null ? '' : _n1(c))
else
(c == null ? '' : _pct1(c)),
if (!sum || extras) ...[
if (sum) ...[
c == null ? '' : _n1(r.totalMax),
p == null ? '' : _pct1(p),
],
p == null ? '' : _gradeOf(p),
c == null ? '' : '${r.rank}',
],
].join(','));
}
}
return Uint8List.fromList([0xEF, 0xBB, 0xBF, ...utf8.encode(sb.toString())]);
}

/// Pick the exams to combine and how, then get the report.
class _CombinedReportDialog extends StatefulWidget {
final String title;
final Future<List<ResultReportGroup>> Function() loadGroups;
const _CombinedReportDialog(
{required this.title, required this.loadGroups});

@override
State<_CombinedReportDialog> createState() => _CombinedReportDialogState();
}

class _CombinedReportDialogState extends State<_CombinedReportDialog> {
late final List<String> _exams = List<String>.of(appSettings.value.examOptions);
final Set<String> _picked = {};
final Map<String, TextEditingController> _w = {};
bool _sum = true; // true: add the marks, false: weighted %
bool _zero = false;
bool _detail = false;
bool _extras = false;
bool _busy = false;

@override
void initState() {
super.initState();
for (final e in _exams) {
_w[e] = TextEditingController(text: '1');
}
}

@override
void dispose() {
for (final c in _w.values) {
c.dispose();
}
super.dispose();
}

double? _weight(String e) {
final v = double.tryParse(_w[e]!.text.trim().replaceAll(',', '.'));
return v == null || v <= 0 ? null : v;
}

double get _total => [
for (final e in _picked) _weight(e) ?? 0,
].fold(0.0, (a, b) => a + b);

void _say(String t) =>
ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(t)));

Future<void> _run(String kind) async {
final exams = [for (final e in _exams) if (_picked.contains(e)) e];
if (exams.length < 2) {
_say('Tick at least two exams to combine.');
return;
}
final weights = <String, double>{};
for (final e in exams) {
if (_sum) {
weights[e] = 1;
continue;
}
final v = _weight(e);
if (v == null) {
_say('Enter a weight above 0 for "$e".');
return;
}
weights[e] = v;
}
setState(() => _busy = true);
final messenger = ScaffoldMessenger.of(context);
final nav = Navigator.of(context);
try {
final groups = await buildCombinedGroups(
exams: exams,
weights: weights,
groups: await widget.loadGroups(),
missingAsZero: _zero,
sumMode: _sum,
);
final name = _safeFile('Combined-${widget.title}');
if (kind == 'csv') {
final bytes = buildCombinedCsv(
exams: exams,
weights: weights,
groups: groups,
missingAsZero: _zero,
detail: _detail,
extras: _extras);
final path = await _downloadInBrowser(bytes, '$name.csv', 'text/csv');
if (mounted) nav.pop();
if (path != null) {
messenger.showSnackBar(
SnackBar(content: Text('Saved $name.csv (open it with Excel)')));
}
} else {
final bytes = await ExamService().buildCombinedPdf(
exams: exams,
weights: weights,
groups: groups,
missingAsZero: _zero,
detail: _detail,
extras: _extras);
if (kind == 'print') {
if (mounted) setState(() => _busy = false);
await Printing.layoutPdf(name: name, onLayout: (_) async => bytes);
} else {
final path =
await _downloadInBrowser(bytes, '$name.pdf', 'application/pdf');
if (mounted) nav.pop();
if (path != null) {
messenger.showSnackBar(SnackBar(content: Text('Saved $name.pdf')));
}
}
}
} catch (e) {
messenger.showSnackBar(SnackBar(
content: Text('$e'.replaceFirst('Exception: ', '')),
duration: const Duration(seconds: 6)));
} finally {
if (mounted) setState(() => _busy = false);
}
}

@override
Widget build(BuildContext context) {
final total = _total;
return AlertDialog(
title: const Text('Combined report'),
content: SizedBox(
width: 500,
child: SingleChildScrollView(
child: Column(
mainAxisSize: MainAxisSize.min,
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Text('Scope: ${widget.title}',
style: const TextStyle(fontWeight: FontWeight.w600)),
const SizedBox(height: 8),
SegmentedButton<bool>(
segments: const [
ButtonSegment<bool>(
value: true,
label: Text('Total marks'),
icon: Icon(Icons.add)),
ButtonSegment<bool>(
value: false,
label: Text('Weighted %'),
icon: Icon(Icons.percent)),
],
selected: {_sum},
onSelectionChanged:
_busy ? null : (s) => setState(() => _sum = s.first),
),
const SizedBox(height: 8),
Text(
_sum
? 'The marks of the ticked exams are ADDED, subject by '
'subject (e.g. Mid-term 30 + Monthly1 12 = 42), and the '
'subject totals are added to a grand total. The grade '
'uses the total as a % of what it is out of.'
    : 'Each mark becomes a % of that exam\'s highest mark, '
'then the exams are averaged with the weights below '
'(1,1,1 = equal; 10,10,30,50 = percentages).',
style: TextStyle(fontSize: 12.5, color: Colors.grey.shade700)),
const SizedBox(height: 10),
for (final e in _exams)
Row(children: [
Checkbox(
value: _picked.contains(e),
onChanged: _busy
? null
    : (v) => setState(() {
if (v == true) {
_picked.add(e);
} else {
_picked.remove(e);
}
}),
),
Expanded(child: Text(e)),
if (!_sum) ...[
SizedBox(
width: 64,
child: TextField(
controller: _w[e],
enabled: _picked.contains(e) && !_busy,
onChanged: (_) => setState(() {}),
keyboardType: const TextInputType.numberWithOptions(
decimal: true),
decoration: const InputDecoration(
isDense: true,
labelText: 'Weight',
border: OutlineInputBorder()),
),
),
SizedBox(
width: 52,
child: Text(
_picked.contains(e) && total > 0 && _weight(e) != null
? '${_pct1(_weight(e)! / total * 100)}%'
    : '',
textAlign: TextAlign.right,
style: const TextStyle(fontWeight: FontWeight.w600)),
),
],
]),
const SizedBox(height: 6),
SwitchListTile(
contentPadding: EdgeInsets.zero,
dense: true,
title: const Text('Count a missing exam as 0'),
subtitle: Text(_sum
? (_zero
? 'A subject without a mark in a ticked exam adds 0 and '
'that exam stays in "Out of".'
    : 'A subject without a mark in a ticked exam is left out '
'of its total and of "Out of" (shown with *).')
    : (_zero
? 'A student without a result in a ticked exam gets 0 there.'
    : 'A missing exam is left out and the other weights are '
're-scaled (shown with *).')),
value: _zero,
onChanged: _busy ? null : (v) => setState(() => _zero = v),
),
if (_sum)
SwitchListTile(
contentPadding: EdgeInsets.zero,
dense: true,
title: const Text('Also show Out of, %, Grade and Rank'),
subtitle: const Text(
'Off = only the subject totals and the Total.'),
value: _extras,
onChanged: _busy ? null : (v) => setState(() => _extras = v),
),
SwitchListTile(
contentPadding: EdgeInsets.zero,
dense: true,
title: const Text('Show the mark of each exam'),
subtitle: Text(_sum
? 'PDF: small numbers under every subject total. Excel: one '
'column per exam, in the order above.'
    : 'PDF: small numbers under the combined % of every subject. '
'Excel: one column per exam, in the order above.'),
value: _detail,
onChanged: _busy ? null : (v) => setState(() => _detail = v),
),
if (_busy)
const Padding(
padding: EdgeInsets.only(top: 8),
child: LinearProgressIndicator(),
),
],
),
),
),
actions: [
TextButton(
onPressed: _busy ? null : () => Navigator.pop(context),
child: const Text('Cancel')),
TextButton.icon(
onPressed: _busy ? null : () => _run('print'),
icon: const Icon(Icons.print),
label: const Text('Print')),
TextButton.icon(
onPressed: _busy ? null : () => _run('csv'),
icon: const Icon(Icons.table_chart),
label: const Text('Excel')),
FilledButton.icon(
onPressed: _busy ? null : () => _run('pdf'),
icon: const Icon(Icons.picture_as_pdf),
label: const Text('PDF')),
],
);
}
}

/// A clear toolbar button: a coloured rounded tile with the icon on top and a
/// short text under it. Used for every report / print / download / upload
/// action so each one says what it does. Pass [onTap] for a normal button;
/// leave it null when the tile is the child of a PopupMenuButton.
class _BarAction extends StatelessWidget {
final IconData icon;
final String label;
final String? tooltip;
final Color color;
final VoidCallback? onTap;
final bool enabled;
const _BarAction({
required this.icon,
required this.label,
this.tooltip,
this.color = const Color(0xFF1565C0),
this.onTap,
this.enabled = true,
});

@override
Widget build(BuildContext context) {
final on = enabled;
final c = on ? color : Theme.of(context).colorScheme.outline;
Widget tile = Container(
constraints: const BoxConstraints(minWidth: 52),
padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
decoration: BoxDecoration(
color: c.withAlpha(on ? 28 : 18),
borderRadius: BorderRadius.circular(14),
border: Border.all(color: c.withAlpha(on ? 80 : 40)),
),
child: Column(
mainAxisSize: MainAxisSize.min,
mainAxisAlignment: MainAxisAlignment.center,
children: [
Icon(icon, size: 20, color: c),
const SizedBox(height: 1),
Text(label,
maxLines: 1,
overflow: TextOverflow.fade,
softWrap: false,
style: TextStyle(
fontSize: 10.5,
height: 1.1,
fontWeight: FontWeight.w700,
color: c)),
],
),
);
if (onTap != null) {
tile = InkWell(
borderRadius: BorderRadius.circular(14),
onTap: enabled ? onTap : null,
child: tile,
);
}
if (tooltip != null) tile = Tooltip(message: tooltip!, child: tile);
return Padding(
padding: const EdgeInsets.symmetric(horizontal: 3, vertical: 5),
child: Material(type: MaterialType.transparency, child: tile),
);
}
}

String _safeFile(String s) => s.replaceAll(RegExp(r'[^A-Za-z0-9._-]+'), '-');

/// "Report" menu: download the report as Excel or Word (or PDF), or print it.
/// The builders run only when the person taps (so they always use the exam
/// that is picked then).
class _ReportMenuButton extends StatefulWidget {
final Future<Uint8List> Function() build; // PDF (also used for Print)
final Future<Uint8List> Function()? buildXlsx; // Excel
final Future<Uint8List> Function()? buildDocx; // Word
final String Function() fileName;
final bool enabled;
final bool iconOnly;
const _ReportMenuButton({
required this.build,
this.buildXlsx,
this.buildDocx,
required this.fileName,
this.enabled = true,
this.iconOnly = false,
});

@override
State<_ReportMenuButton> createState() => _ReportMenuButtonState();
}

class _ReportMenuButtonState extends State<_ReportMenuButton> {
bool _busy = false;

Future<void> _run(String kind) async {
setState(() => _busy = true);
final messenger = ScaffoldMessenger.of(context);
try {
final name = widget.fileName();
final builder = switch (kind) {
'xlsx' => widget.buildXlsx ?? widget.build,
'docx' => widget.buildDocx ?? widget.build,
_ => widget.build,
};
final bytes = await builder();
if (kind == 'print') {
if (mounted) setState(() => _busy = false);
await Printing.layoutPdf(name: name, onLayout: (_) async => bytes);
} else {
final (ext, mime) = switch (kind) {
'xlsx' => (
'xlsx',
'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
),
'docx' => ('docx', ExamService._docxMime),
_ => ('pdf', 'application/pdf'),
};
final path = await _downloadInBrowser(bytes, '$name.$ext', mime);
messenger.showSnackBar(SnackBar(
duration: const Duration(seconds: 6),
content: Text(path == null && !kIsWeb
? 'Download cancelled (nothing was saved).'
    : 'Report saved'
'${path == null ? ' - check your Downloads folder' : '\nSaved to: $path'}')));
}
} catch (e) {
messenger.showSnackBar(
SnackBar(content: Text('$e'.replaceFirst('Exception: ', ''))));
} finally {
if (mounted) setState(() => _busy = false);
}
}

@override
Widget build(BuildContext context) {
// only the administrator can see, download or print the report
if (teacherScope.value.scoped) return const SizedBox.shrink();
if (_busy) {
return const Padding(
padding: EdgeInsets.all(12),
child: SizedBox(
width: 20, height: 20, child: CircularProgressIndicator(strokeWidth: 2.5)),
);
}
final items = [
if (widget.buildXlsx != null)
const PopupMenuItem(
value: 'xlsx',
child: ListTile(
dense: true,
leading: Icon(Icons.table_chart, color: Color(0xFF1D6F42)),
title: Text('Download Excel'))),
if (widget.buildDocx != null)
const PopupMenuItem(
value: 'docx',
child: ListTile(
dense: true,
leading: Icon(Icons.description, color: Color(0xFF1565C0)),
title: Text('Download Word'))),
const PopupMenuItem(
value: 'pdf',
child: ListTile(
dense: true,
leading: Icon(Icons.picture_as_pdf, color: Color(0xFFC62828)),
title: Text('Download PDF'))),
const PopupMenuItem(
value: 'print',
child: ListTile(
dense: true,
leading: Icon(Icons.print, color: Color(0xFF546E7A)),
title: Text('Print'))),
];
if (widget.iconOnly) {
return Padding(
padding: const EdgeInsets.only(right: 6),
child: PopupMenuButton<String>(
tooltip: 'Download or print the report',
enabled: widget.enabled,
onSelected: _run,
itemBuilder: (_) => items,
shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
child: _BarAction(
icon: Icons.summarize,
label: 'Report',
enabled: widget.enabled,
),
),
);
}
return PopupMenuButton<String>(
tooltip: 'Report',
enabled: widget.enabled,
onSelected: _run,
itemBuilder: (_) => items,
child: IgnorePointer(
child: FilledButton.tonalIcon(
onPressed: widget.enabled ? () {} : null,
icon: const Icon(Icons.summarize, size: 18),
label: const Text('Report'),
),
),
);
}
}

/// The marks of one student in one exam (subject -> mark).
/// One student in the cheating list of an exam.
class CheatEntry {
final String id, exam, name, label, studentNo, by;
final DateTime? at;
/// Subjects the student cheated in. Empty = every subject.
final List<String> subjects;
const CheatEntry({
required this.id,
required this.exam,
required this.name,
this.label = '',
this.studentNo = '',
this.by = '',
this.at,
this.subjects = const [],
});

factory CheatEntry.fromDoc(DocumentSnapshot<Map<String, dynamic>> d) {
final m = d.data() ?? const <String, dynamic>{};
return CheatEntry(
id: '${m['studentId'] ?? ''}',
exam: '${m['exam'] ?? ''}',
name: '${m['name'] ?? ''}',
label: '${m['label'] ?? ''}',
studentNo: '${m['studentNo'] ?? ''}',
by: '${m['by'] ?? ''}',
at: (m['createdAt'] as Timestamp?)?.toDate(),
subjects: [for (final x in (m['subjects'] as List? ?? const [])) '$x'],
);
}
}

/// The cheating list (collection "cheating", one document per student and
/// exam). A student in the list shows "Cheated" in every mark field of that
/// exam and is left out of totals, averages and positions. Only the
/// administrator adds / removes students (set the Firestore rule so).
// ======================= MARK AS COMPLETE =======================
//
// The marks of one subject IN ONE FORM of an exam can be closed
// ("Complete"): the mark fields of that subject become inactive for the
// students of that form, everywhere. This happens when
//  - an administrator, or a teacher of that subject and form, taps the lock
//    in the Schedule tab (or "Mark all" for every form of the subject), or
//  - the deadline of the subject (exam date + days to return the results)
//    has passed.
// Status is kept in the "subjectStatus" collection, one document per exam,
// subject and form: status "complete" (closed by a person) or "open"
// (reopened by a person; this also overrides the deadline). A document
// without a form (older version) applies to every form.
class SubjectLockService {
static final _col = FirebaseFirestore.instance.collection('subjectStatus');

/// exam -> 'subject|form' -> 'complete' | 'open'   (empty form = all forms)
static final ValueNotifier<Map<String, Map<String, String>>> byExam =
ValueNotifier(const {});
static StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? _sub;
static final Completer<void> _ready = Completer<void>();
static Future<void> get ready => _ready.future;

static String _key(String subject, String form) => '$subject|$form';

static void start() {
if (_sub != null) return;
_sub = _col.snapshots().listen((s) {
final m = <String, Map<String, String>>{};
for (final d in s.docs) {
final x = d.data();
final exam = '${x['exam'] ?? ''}';
final sub = '${x['subject'] ?? ''}';
final form = '${x['form'] ?? ''}';
final st = '${x['status'] ?? ''}';
if (exam.isEmpty || sub.isEmpty) continue;
if (st != 'complete' && st != 'open') continue;
(m[exam] ??= {})[_key(sub, form)] = st;
}
byExam.value = m;
if (!_ready.isCompleted) _ready.complete();
}, onError: (Object e) {
debugPrint('Subject status could not be read: $e');
_sub?.cancel();
_sub = null; // tried again the next time a screen starts it
if (!_ready.isCompleted) _ready.complete();
});
}

/// The status set by a person for this subject and form ('complete' or
/// 'open'), or null when nobody set one.
static String? statusOf(String exam, String subject, [String form = '']) {
final m = byExam.value[exam];
if (m == null) return null;
return (form.isEmpty ? null : m[_key(subject, form)]) ??
m[_key(subject, '')];
}

/// True when the last day of the subject (exam date + days to return the
/// results) is behind us.
static bool deadlinePassed(String subject) {
final due = appSettings.value.subjectDeadline(subject);
if (due == null) return false;
final now = DateTime.now();
return DateTime(now.year, now.month, now.day)
    .isAfter(DateTime(due.year, due.month, due.day));
}

/// True when the marks of [subject] are closed for [exam] (in [form]).
static bool isComplete(String exam, String subject, [String form = '']) {
final s = statusOf(exam, subject, form);
if (s == 'complete') return true;
if (s == 'open') return false;
return deadlinePassed(subject);
}

/// Closed only because the deadline passed (nobody tapped the button).
static bool closedByDeadline(String exam, String subject,
[String form = '']) =>
statusOf(exam, subject, form) == null && deadlinePassed(subject);

/// An administrator, or a teacher of this subject (in this form).
static bool canMark(String subject, [String form = '']) {
final t = teacherScope.value;
if (t.isStudent) return false;
return form.isEmpty ? t.allowsSubject(subject) : t.allows(subject, form);
}

/// A teacher cannot reopen a subject once its deadline has passed.
static bool canReopen(String exam, String subject, [String form = '']) {
if (!canMark(subject, form)) return false;
return !teacherScope.value.scoped || !deadlinePassed(subject);
}

static String _docId(String exam, String subject, String form) =>
'${SchoolService.subjectKey(exam)}__${SchoolService.subjectKey(subject)}'
'__${SchoolService.subjectKey(form)}';

/// Marks the subject Complete (or reopens it) in each of [forms].
static Future<void> setStatus(
String exam, String subject, List<String> forms, bool complete) async {
final u = FirebaseAuth.instance.currentUser;
final batch = FirebaseFirestore.instance.batch();
for (final f in forms) {
batch.set(_col.doc(_docId(exam, subject, f)), {
'exam': exam,
'subject': subject,
'form': f,
'status': complete ? 'complete' : 'open',
'updatedBy': u?.uid,
'updatedByEmail': u?.email,
'updatedAt': FieldValue.serverTimestamp(),
});
}
await batch.commit();
}
}

class CheatService {
static final _col = FirebaseFirestore.instance.collection('cheating');

/// exam -> studentId -> entry
static final ValueNotifier<Map<String, Map<String, CheatEntry>>> byExam =
ValueNotifier(const {});
static StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? _sub;
static final Completer<void> _ready = Completer<void>();
static Future<void> get ready => _ready.future;

static void start() {
SubjectLockService.start();
if (_sub != null) return;
_sub = _col.snapshots().listen((s) {
final m = <String, Map<String, CheatEntry>>{};
for (final d in s.docs) {
final e = CheatEntry.fromDoc(d);
if (e.id.isEmpty) continue;
(m[e.exam] ??= {})[e.id] = e;
}
byExam.value = m;
if (!_ready.isCompleted) _ready.complete();
}, onError: (Object e) {
debugPrint('Cheating list could not be read: $e');
_sub?.cancel();
_sub = null; // tried again the next time a screen starts it
if (!_ready.isCompleted) _ready.complete();
});
}

/// True when the student cheated in EVERY subject of the exam.
static bool isCheated(String exam, String studentId) {
final e = byExam.value[exam]?[studentId];
return e != null && e.subjects.isEmpty;
}

/// The subjects a student cheated in when only some subjects were chosen
/// (empty when the student is not listed or cheated in every subject).
static Set<String> partialSubjects(String exam, String studentId) {
final e = byExam.value[exam]?[studentId];
if (e == null || e.subjects.isEmpty) return const <String>{};
return e.subjects.toSet();
}

/// A teacher only sees the cheating of the subjects they teach (an
/// administrator sees all of it). Returns the part of [cs] this person may see.
static Set<String> visibleSubjects(Set<String> cs) {
final t = teacherScope.value;
if (!t.restricted) return cs;
return {for (final x in cs) if (t.allowsSubject(x)) x};
}

/// Whole-exam cheating is visible to everyone; a partial entry only to
/// administrators and to teachers of one of its subjects.
static bool visibleEntry(CheatEntry e) =>
e.subjects.isEmpty || visibleSubjects(e.subjects.toSet()).isNotEmpty;

/// True when this one subject counts as cheated for the student.
static bool isCheatedIn(String exam, String studentId, String subject) =>
isCheated(exam, studentId) ||
partialSubjects(exam, studentId).contains(subject);

/// Changes the cheated subjects of a student already in the list
/// (empty list = every subject).
static Future<void> setSubjects(
String exam, String studentId, List<String> subjects) async {
final twin = (await ResultService().twinMap())[studentId];
final batch = FirebaseFirestore.instance.batch();
for (final id in <String>{studentId, if (twin != null) twin}) {
batch.update(_col.doc(_docId(exam, id)), {'subjects': subjects});
}
await batch.commit();
}

static Set<String> idsOf(String exam) =>
byExam.value[exam]?.keys.toSet() ?? <String>{};

static String _docId(String exam, String id) =>
'${SchoolService.subjectKey(exam)}__$id';

/// Marks the student (and his twin record: class <-> section) as cheated.
static Future<void> add(StudentInfo s, String exam, String label,
{List<String> subjects = const []}) async {
final twin = (await ResultService().twinMap())[s.id];
final by = FirebaseAuth.instance.currentUser?.email ?? '';
final batch = FirebaseFirestore.instance.batch();
for (final id in <String>{s.id, if (twin != null) twin}) {
batch.set(_col.doc(_docId(exam, id)), {
'exam': exam,
'studentId': id,
'name': s.name,
'label': label,
'studentNo': s.studentNo,
'by': by,
'subjects': subjects,
'createdAt': FieldValue.serverTimestamp(),
});
}
await batch.commit();
}

static Future<void> remove(String exam, String studentId) async {
final twin = (await ResultService().twinMap())[studentId];
final batch = FirebaseFirestore.instance.batch();
for (final id in <String>{studentId, if (twin != null) twin}) {
batch.delete(_col.doc(_docId(exam, id)));
}
await batch.commit();
}
}

class ResultMarks {
final Map<String, double> marks;

/// The student is in the cheating list of this exam: no marks count.
final bool cheated;

/// Subjects of this exam that count as cheated (the student cheated in
/// some subjects only). Their marks are left out of the total and average.
final Set<String> cheatedSubs;
const ResultMarks(this.marks,
{this.cheated = false, this.cheatedSubs = const <String>{}});
double get total => marks.values.fold(0.0, (a, b) => a + b);
double? get average => marks.isEmpty ? null : total / marks.length;
}

class ResultService {
final _db = FirebaseFirestore.instance;
CollectionReference<Map<String, dynamic>> get _col => _db.collection('results');
String? get _uid => FirebaseAuth.instance.currentUser?.uid;

static String _id(String studentId, String exam) =>
'${studentId}_${SchoolService.subjectKey(exam)}';

/// Every student of the school.
Stream<List<StudentInfo>> watchAllStudents() =>
_db.collection('students').snapshots().map((s) {
final sc = teacherScope.value;
final l = [
for (final d in s.docs)
if (!sc.isStudent || d.id == sc.studentId)
StudentInfo(
id: d.id,
name: '${d.data()['name'] ?? ''}',
sectionId: '${d.data()['sectionId'] ?? ''}',
studentNo: '${d.data()['studentNo'] ?? ''}'.trim(),
createdAt: (d.data()['createdAt'] as Timestamp?)?.toDate()),
];
l.sort((a, b) => a.name.toLowerCase().compareTo(b.name.toLowerCase()));
return l;
});

static Map<String, double> _marksOf(Object? r) {
final out = <String, double>{};
if (r is Map) {
r.forEach((k, v) {
if (v is num) out['$k'] = v.toDouble();
});
}
return out;
}

/// A teacher only sees the marks of the subjects they teach.
static Map<String, double> _visibleMarks(Map<String, double> m) =>
teacherScope.value.restricted
? {
for (final e in m.entries)
if (teacherScope.value.allowsSubject(e.key)) e.key: e.value
}
    : m;

/// A student can exist twice: once in the whole class (3C) and once in a
/// divided section (3C-A), e.g. when a list was uploaded twice. Results are
/// stored per student record, so marks entered on one copy were invisible on
/// the other. This finds those pairs (same form + class + name, exactly one
/// copy in the whole class and one in a section) so results stay the same
/// whichever way they are entered or viewed. id -> id of its twin.
static Map<String, String> _twinCache = const {};
static Map<String, String> _stuSection = {};
static DateTime? _twinAt;

Future<Map<String, String>> twinMap() async {
final at = _twinAt;
if (at != null && DateTime.now().difference(at) < const Duration(seconds: 30)) {
return _twinCache;
}
try {
final secs = await _db.collection('sections').get();
final secOf = {for (final d in secs.docs) d.id: SectionInfo.fromDoc(d)};
final stu = await _db.collection('students').get();
// same words in any order, ignoring case and punctuation
String norm(String n) {
final w = n
    .toLowerCase()
    .replaceAll(RegExp(r'[^\p{L}\p{N}\s]', unicode: true), ' ')
    .split(RegExp(r'\s+'))
    .where((x) => x.isNotEmpty)
    .toList()
..sort();
return w.join(' ');
}

final groups = <String, List<(String, bool)>>{};
final stuSec = <String, String>{};
for (final d in stu.docs) {
final sid = '${d.data()['sectionId'] ?? ''}';
final sec = secOf[sid];
if (sec == null) continue;
stuSec[d.id] = sid;
groups
    .putIfAbsent('${sec.form}|${sec.classKey}|${norm('${d.data()['name'] ?? ''}')}',
() => [])
    .add((d.id, sec.isSub));
}
final out = <String, String>{};
for (final g in groups.values) {
if (g.length == 2 && g[0].$2 != g[1].$2) {
out[g[0].$1] = g[1].$1;
out[g[1].$1] = g[0].$1;
}
}
_twinCache = out;
_stuSection = stuSec;
_twinAt = DateTime.now();
return out;
} catch (_) {
return _twinCache; // no access: work without twins
}
}

static int _ts(Map<String, dynamic> d) {
final t = d['updatedAt'];
return t is Timestamp ? t.millisecondsSinceEpoch : 0;
}

/// Marks of several copies of one student: the newest entry wins per subject.
static Map<String, double> _merge(List<Map<String, dynamic>> docs) {
final l = [...docs]..sort((a, b) => _ts(a).compareTo(_ts(b)));
final out = <String, double>{};
for (final d in l) {
out.addAll(_marksOf(d['marks']));
}
return out;
}

/// studentId -> marks, for one exam.
Stream<Map<String, ResultMarks>> watchResults(String exam) {
late final StreamController<Map<String, ResultMarks>> ctrl;
StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? sub;
QuerySnapshot<Map<String, dynamic>>? last;
VoidCallback? listener;

Future<void> emit() async {
final s = last;
if (s == null || ctrl.isClosed) return;
try {
final twins = await twinMap();
await CheatService.ready;
final raw = <String, Map<String, dynamic>>{};
for (final d in s.docs) {
raw['${d.data()['studentId'] ?? ''}'] = d.data();
}
final ids = <String>{...raw.keys};
for (final e in twins.entries) {
if (raw.containsKey(e.value)) ids.add(e.key);
}
final out = <String, ResultMarks>{};
for (final id in ids) {
final t = twins[id];
final docs = [
if (raw[id] != null) raw[id]!,
if (t != null && raw[t] != null) raw[t]!,
];
out[id] = ResultMarks(_visibleMarks(_merge(docs)));
}
// the cheating list: no marks count, the student shows "Cheated"
for (final id in CheatService.idsOf(exam)) {
if (CheatService.isCheated(exam, id)) {
out[id] = const ResultMarks({}, cheated: true);
} else {
final cs = CheatService.visibleSubjects(
CheatService.partialSubjects(exam, id));
if (cs.isEmpty) continue; // cheated only in subjects this user cannot see
final old = out[id]?.marks ?? const <String, double>{};
out[id] = ResultMarks(
{for (final e in old.entries) if (!cs.contains(e.key)) e.key: e.value},
cheatedSubs: cs);
}
}
Map<String, ResultMarks> result = out;
if (teacherScope.value.isStudent) {
final me = teacherScope.value.studentId;
result = {if (out[me] != null) me: out[me]!};
}
if (!ctrl.isClosed) ctrl.add(result);
} catch (e, st) {
if (!ctrl.isClosed) ctrl.addError(e, st);
}
}

ctrl = StreamController<Map<String, ResultMarks>>.broadcast(
onListen: () {
CheatService.start();
listener = () => emit();
CheatService.byExam.addListener(listener!);
sub = _col.where('exam', isEqualTo: exam).snapshots().listen((s) {
last = s;
emit();
}, onError: (Object e, StackTrace st) => ctrl.addError(e, st));
},
onCancel: () async {
if (listener != null) CheatService.byExam.removeListener(listener!);
await sub?.cancel();
sub = null;
},
);
return ctrl.stream;
}

/// studentId -> ALL marks (every subject), for one exam.
/// studentId -> the subjects the student was ABSENT in, read from attendance:
/// the register of that subject on the day of its exam (date set in the Exam
/// tab). If the subject has no register that day, the whole-day register is
/// used. Subjects without an exam date are skipped.
Future<Map<String, Set<String>>> absentSubjects(
Iterable<String>? studentIds, Iterable<String> subjects) async {
final out = <String, Set<String>>{};
final ids = studentIds?.toSet(); // null = every student
if (ids != null && ids.isEmpty) return out;
final twins = await twinMap();
final byDate = <String, List<String>>{};
for (final sub in subjects) {
final d = appSettings.value.subjectDateOf(sub);
if (d != null) {
byDate.putIfAbsent(DateFormat('yyyy-MM-dd').format(d), () => []).add(sub);
}
}
final school = SchoolService();
for (final e in byDate.entries) {
final docs = await school.getAttendanceRange(e.key, e.key);
for (final sub in e.value) {
final sk = SchoolService.subjectKey(sub);
final specific = [
for (final d in docs)
if (d.subject.trim().isNotEmpty &&
SchoolService.subjectKey(d.subject) == sk)
d
];
final src = specific.isNotEmpty
? specific
    : [for (final d in docs) if (d.subject.trim().isEmpty) d];
for (final d in src) {
for (final e in d.records.entries) {
if (e.value != 'absent') continue;
final twin = twins[e.key];
for (final id in <String>{e.key, if (twin != null) twin}) {
if (ids == null || ids.contains(id)) {
out.putIfAbsent(id, () => <String>{}).add(sub);
}
}
}
}
}
}
return out;
}

/// Live version of [absentSubjects]: emits again whenever a register of an
/// exam day is saved or changed in Attendance, or the exam dates change.
Stream<Map<String, Set<String>>> watchAbsentSubjects(
Iterable<String>? studentIds, Iterable<String> subjects) {
final subs = subjects.toList();
final ids = studentIds?.toList();
final ctrl = StreamController<Map<String, Set<String>>>();
StreamSubscription<QuerySnapshot<Map<String, dynamic>>>? sub;
var gen = 0;
Future<void> compute() async {
final my = ++gen;
try {
final a = await absentSubjects(ids, subs);
if (my == gen && !ctrl.isClosed) ctrl.add(a);
} catch (_) {} // no access to attendance: nothing to show
}

void listen() {
sub?.cancel();
sub = null;
final keys = <String>[
for (final s in subs)
if (appSettings.value.subjectDateOf(s) != null)
DateFormat('yyyy-MM-dd').format(appSettings.value.subjectDateOf(s)!)
]..sort();
if (keys.isEmpty) return;
sub = FirebaseFirestore.instance
    .collection('attendance')
    .where('date', isGreaterThanOrEqualTo: keys.first)
    .where('date', isLessThanOrEqualTo: keys.last)
    .snapshots()
    .listen((_) => compute(), onError: (Object _) {});
}

void onSettings() {
listen();
compute();
}

ctrl.onListen = () {
appSettings.addListener(onSettings);
listen();
compute();
};
ctrl.onCancel = () {
appSettings.removeListener(onSettings);
return sub?.cancel();
};
return ctrl.stream;
}

Future<Map<String, Map<String, double>>> getAllForExam(String exam) async {
final twins = await twinMap();
final q = await _col.where('exam', isEqualTo: exam).get();
final raw = <String, Map<String, dynamic>>{
for (final d in q.docs) '${d.data()['studentId'] ?? ''}': d.data(),
};
final ids = <String>{...raw.keys};
for (final e in twins.entries) {
if (raw.containsKey(e.value)) ids.add(e.key);
}
return {
for (final id in ids)
id: _merge([
if (raw[id] != null) raw[id]!,
if (twins[id] != null && raw[twins[id]] != null) raw[twins[id]]!,
]),
};
}

/// Saves the marks of many students in one go (an empty map removes the
/// result of that student).
/// The highest exam total (Settings > Exams) cannot be exceeded.
static void _checkTotal(
String exam, String name, Map<String, double> marks, String form) {
final top = appSettings.value.limitsFor(exam, form).totalMax;
if (top <= 0 || marks.isEmpty) return;
final total = marks.values.fold(0.0, (a, b) => a + b);
if (total > top + 1e-9) {
throw Exception('The total of $name is ${_fmtMark(total)}, more than '
'the highest exam total (${_fmtMark(top)}).');
}
}

Future<void> saveMany(String exam,
List<(StudentInfo, Map<String, double>)> items) async {
SubjectLockService.start();
await SubjectLockService.ready;
final closedByForm = <String, List<String>>{};
List<String> closedFor(String form) => closedByForm.putIfAbsent(
form,
() => [
for (final sub in ExamService.subjects)
if (SubjectLockService.isComplete(exam, sub, form)) sub
]);
if (items.any((it) => closedFor(SchoolService.formOf(it.$1)).isNotEmpty)) {
final stored = await getAllForExam(exam);
items = [
for (final it in items)
(
it.$1,
_keepClosed(stored[it.$1.id] ?? const <String, double>{}, it.$2,
closedFor(SchoolService.formOf(it.$1)))
),
];
}
for (final it in items) {
_checkTotal(exam, it.$1.name, it.$2, SchoolService.formOf(it.$1));
}
Future<void> write(List<(String, String, Map<String, double>)> rows) async {
for (var i = 0; i < rows.length; i += 400) {
final batch = _db.batch();
for (final r in rows.skip(i).take(400)) {
final ref = _col.doc(_id(r.$1, exam));
if (r.$3.isEmpty) {
batch.delete(ref);
} else {
batch.set(ref, {
'studentId': r.$1,
'sectionId': r.$2,
'exam': exam,
'marks': r.$3,
'updatedBy': _uid,
'updatedAt': FieldValue.serverTimestamp(),
});
}
}
await batch.commit().timeout(const Duration(seconds: 30), onTimeout: () {
throw Exception('Saving timed out. Check the internet connection.');
});
}
}

await write([for (final it in items) (it.$1.id, it.$1.sectionId, it.$2)]);

// the same marks go to the twin copy of a student (whole class <-> section)
try {
final twins = await twinMap();
final extra = <(String, String, Map<String, double>)>[
for (final it in items)
if (twins[it.$1.id] != null)
(twins[it.$1.id]!, _stuSection[twins[it.$1.id]!] ?? it.$1.sectionId, it.$2),
];
if (extra.isNotEmpty) await write(extra);
} catch (_) {}
}

/// Administrator: replaces ALL marks of one student for one exam. Unlike
/// [saveMany] it also changes subjects that are marked Complete (closed).
/// An empty map removes the result. The twin copy is kept in step.
Future<void> adminSaveMarks(StudentInfo s, String exam,
Map<String, double> marks, String form) async {
_checkTotal(exam, s.name, marks, form);
final twin = (await twinMap())[s.id];
final batch = _db.batch();
for (final id in [s.id, if (twin != null) twin]) {
final ref = _col.doc(_id(id, exam));
if (marks.isEmpty) {
batch.delete(ref);
} else {
batch.set(ref, {
'studentId': id,
'sectionId': id == s.id ? s.sectionId : (_stuSection[id] ?? s.sectionId),
'exam': exam,
'marks': marks,
'updatedBy': _uid,
'updatedAt': FieldValue.serverTimestamp(),
});
}
}
await batch.commit().timeout(const Duration(seconds: 30), onTimeout: () {
throw Exception('Saving timed out. Check the internet connection.');
});
}

/// [raw] keeps the marks of cheated subjects (used when editing, so they
/// are never lost when saving).
Future<ResultMarks> get(String studentId, String exam,
{bool raw = false}) async {
CheatService.start();
await CheatService.ready;
await SubjectLockService.ready;
if (CheatService.isCheated(exam, studentId)) {
return const ResultMarks({}, cheated: true);
}
final t = (await twinMap())[studentId];
final docs = <Map<String, dynamic>>[];
for (final id in [studentId, if (t != null) t]) {
try {
final d = await _col.doc(_id(id, exam)).get();
if (d.data() != null) docs.add(d.data()!);
} catch (_) {
if (id == studentId) rethrow;
}
}
final cs = CheatService.visibleSubjects(
CheatService.partialSubjects(exam, studentId));
final merged = _merge(docs);
if (cs.isEmpty) return ResultMarks(merged);
return ResultMarks(
raw
? merged
    : {for (final e in merged.entries) if (!cs.contains(e.key)) e.key: e.value},
cheatedSubs: cs);
}

static Map<String, double> _keepClosed(Map<String, double> stored,
Map<String, double> marks, List<String> closed) {
final out = {...marks};
for (final sub in closed) {
final v = stored[sub];
if (v == null) {
out.remove(sub);
} else {
out[sub] = v;
}
}
return out;
}

/// Subjects marked Complete (or past their deadline) cannot change: they
/// keep the stored mark, whatever the screen sent.
Future<Map<String, double>> _keepComplete(String studentId, String exam,
String form, Map<String, double> marks) async {
SubjectLockService.start();
await SubjectLockService.ready;
final closed = [
for (final sub in ExamService.subjects)
if (SubjectLockService.isComplete(exam, sub, form)) sub
];
if (closed.isEmpty) return marks;
final cur = (await get(studentId, exam, raw: true)).marks;
return _keepClosed(cur, marks, closed);
}

/// Saves the marks (an empty map removes the result).
Future<void> save(StudentInfo s, String exam, Map<String, double> marks) async {
marks = await _keepComplete(s.id, exam, SchoolService.formOf(s), marks);
_checkTotal(exam, s.name, marks, SchoolService.formOf(s));
Future<void> put(String id, String sectionId) {
final ref = _col.doc(_id(id, exam));
if (marks.isEmpty) return ref.delete();
return ref.set({
'studentId': id,
'sectionId': sectionId,
'exam': exam,
'marks': marks,
'updatedBy': _uid,
'updatedAt': FieldValue.serverTimestamp(),
});
}

// the same marks go to the twin copy of the student (whole class <->
// section): both are written at the same time
String? t;
try {
t = (await twinMap())[s.id];
} catch (_) {}
await Future.wait([
put(s.id, s.sectionId),
if (t != null) put(t, _stuSection[t] ?? s.sectionId).catchError((_) {}),
]).timeout(const Duration(seconds: 30), onTimeout: () {
throw Exception('Saving timed out. Check the internet connection.');
});
}
}

