// ======================= REMINDERS TO TEACHERS =======================
//
// The administrator sends a reminder from the Schedule tab. It is saved in
// the "notifications" collection and the teacher sees it as a pop-up and a
// banner on the home page as soon as the app is open (no server needed).

/// Reminders of the signed-in person that were not read yet.
class _ReminderInbox extends StatefulWidget {
const _ReminderInbox();

@override
State<_ReminderInbox> createState() => _ReminderInboxState();
}

class _ReminderInboxState extends State<_ReminderInbox> {
final _announced = <String>{};
bool _dialogOpen = false;

Future<void> _announce(
List<QueryDocumentSnapshot<Map<String, dynamic>>> fresh) async {
if (_dialogOpen || fresh.isEmpty || !mounted) return;
_dialogOpen = true;
for (final d in fresh) {
_announced.add(d.id);
}
await showDialog<void>(
context: context,
builder: (ctx) => AlertDialog(
icon: const Icon(Icons.notifications_active, color: kLate, size: 32),
title: const Text('Xusuusin'),
content: SingleChildScrollView(
child: Column(mainAxisSize: MainAxisSize.min, children: [
for (final d in fresh)
Padding(
padding: const EdgeInsets.only(bottom: 10),
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Text('${d.data()['title'] ?? ''}',
style: const TextStyle(fontWeight: FontWeight.w700)),
Text('${d.data()['body'] ?? ''}'),
]),
),
]),
),
actions: [
FilledButton(
onPressed: () => Navigator.pop(ctx), child: const Text('OK')),
],
),
);
_dialogOpen = false;
}

@override
Widget build(BuildContext context) {
final uid = FirebaseAuth.instance.currentUser?.uid;
if (uid == null) return const SizedBox.shrink();
return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
stream: FirebaseFirestore.instance
    .collection('notifications')
    .where('uid', isEqualTo: uid)
    .where('read', isEqualTo: false)
    .snapshots(),
builder: (context, snap) {
final docs = snap.data?.docs ?? const [];
if (docs.isEmpty) return const SizedBox.shrink();
final fresh = [
for (final d in docs)
if (!_announced.contains(d.id)) d
];
if (fresh.isNotEmpty) {
WidgetsBinding.instance.addPostFrameCallback((_) => _announce(fresh));
}
return Align(
alignment: Alignment.topCenter,
child: ConstrainedBox(
constraints: const BoxConstraints(maxWidth: 720),
child: Padding(
padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
child: Column(children: [
for (final d in docs)
Container(
margin: const EdgeInsets.only(bottom: 8),
padding: const EdgeInsets.fromLTRB(12, 10, 6, 10),
decoration: BoxDecoration(
color: kLate.withAlpha(30),
border: Border.all(color: kLate.withAlpha(140)),
borderRadius: BorderRadius.circular(12)),
child: Row(children: [
const Icon(Icons.notifications_active, color: kLate),
const SizedBox(width: 10),
Expanded(
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Text('${d.data()['title'] ?? ''}',
style: const TextStyle(
fontWeight: FontWeight.w700)),
Text('${d.data()['body'] ?? ''}',
style: const TextStyle(fontSize: 13.5)),
]),
),
TextButton(
onPressed: () => d.reference.update({'read': true}),
child: const Text('OK'),
),
]),
),
]),
),
),
);
},
);
}
}

/// One reminder: a teacher + a subject + the days left.
class _Reminder {
final String uid, name, subject, title, body;
final int left;
const _Reminder({
required this.uid,
required this.name,
required this.subject,
required this.left,
required this.title,
required this.body,
});
}

String _daysSo(int n) => n == 1 ? '1 maalin' : '$n maalmood';

/// The message sent to a teacher (Somali).
String _reminderBody(int left) {
if (left > 0) {
return 'Fadlan macalin, muddada kuu hadhay soo xaraynta natiijadu waa ${_daysSo(left)}.';
}
if (left == 0) {
return 'Fadlan macalin, maanta waa maalinta ugu dambeysa ee soo xaraynta natiijada.';
}
return 'Fadlan macalin, muddadii soo xaraynta natiijada waa dhacday ${_daysSo(-left)} ka hor.';
}

/// Students without a mark in each subject (every student counted once).
Map<String, int> _notEnteredBySubject(
List<SectionInfo> sections,
List<StudentInfo> students,
Map<String, ResultMarks> results,
Map<String, String> twins) {
final secById = {for (final s in sections) s.id: s};
final inScope = {
for (final st in students)
if (secById.containsKey(st.sectionId)) st.id
};
final people = [
for (final st in students)
if (inScope.contains(st.id) && !_isDupCopy(st, twins, secById, inScope))
st
];
return {
for (final sub in ExamService.subjects)
sub: people
    .where((st) =>
results[st.id]?.marks[sub] == null &&
!(results[st.id]?.cheated ?? false) &&
!(results[st.id]?.cheatedSubs.contains(sub) ?? false) &&
!studentIsNew(st.createdAt, sub))
    .length,
};
}

// ======================= SCHEDULE (result deadline) =======================

/// The summary by subject of an exam together with the days left to return
/// its results (exam date + the days set in Settings).
class ScheduleScreen extends StatefulWidget {
const ScheduleScreen({super.key});

@override
State<ScheduleScreen> createState() => _ScheduleScreenState();
}

class _ScheduleScreenState extends State<ScheduleScreen> {
final _school = SchoolService();
final _service = ResultService();
late final Stream<List<SectionInfo>> _secStream = _school.watchSections();
late final Stream<List<StudentInfo>> _stuStream = _service.watchAllStudents();
late Stream<Map<String, ResultMarks>> _resStream =
_service.watchResults(_ResultPrefs.exam);
String _exam = _ResultPrefs.exam;
Map<String, String> _twins = const {};
List<SectionInfo>? _secs;
List<StudentInfo>? _stus;
Map<String, ResultMarks> _res = const {};

@override
void initState() {
super.initState();
SubjectLockService.start();
_service.twinMap().then((t) {
if (mounted) setState(() => _twins = t);
});
}

/// Sends the reminder: every teacher of a subject whose deadline is set and
/// whose marks are not all entered gets "days left" for that subject.
Future<void> _sendReminders() async {
final messenger = ScaffoldMessenger.of(context);
void say(String t) => messenger.showSnackBar(SnackBar(content: Text(t)));
final secs = _secs, stus = _stus;
if (secs == null || stus == null) {
say('Wait until the page has loaded.');
return;
}
final notEntered = _notEnteredBySubject(secs, stus, _res, _twins);
final now = DateTime.now();
final today = DateTime.utc(now.year, now.month, now.day);
final left = <String, int>{};
for (final sub in ExamService.subjects) {
final due = appSettings.value.subjectDeadline(sub);
if (due == null || (notEntered[sub] ?? 0) == 0) continue;
// a Complete subject needs no reminder
final fs = [
for (final f in ExamService.forms)
if (secs.any((x) => x.form == f)) f
];
if (fs.isNotEmpty &&
fs.every((f) => SubjectLockService.isComplete(_ResultPrefs.exam, sub, f))) {
continue;
}
left[sub] =
DateTime.utc(due.year, due.month, due.day).difference(today).inDays;
}
if (left.isEmpty) {
say('Nothing to send: no subject has an exam date with marks still '
'to enter. Set the exam dates in the Exam tab.');
return;
}
final items = <_Reminder>[];
try {
final q =
await FirebaseFirestore.instance.collection('teachers').get();
for (final d in q.docs) {
final t = TeacherInfo.fromDoc(d);
if (!t.isTeaching) continue;
final subs = t.subjects;
final name = t.name.trim().isEmpty ? t.email : t.name;
// the reminder goes to the USER account of this teacher
final userUid = await userUidOfTeacher(t.id);
if (userUid == null) continue;
for (final sub in left.keys) {
if (!subs.contains(sub)) continue;
items.add(_Reminder(
uid: userUid,
name: name,
subject: sub,
left: left[sub]!,
title: 'Natiijada $sub',
body: _reminderBody(left[sub]!),
));
}
}
} catch (e) {
say('Could not read the teachers: $e');
return;
}
if (items.isEmpty) {
say('No teacher is assigned to these subjects. Add them in Teachers.');
return;
}
items.sort((a, b) => a.name.toLowerCase().compareTo(b.name.toLowerCase()));
if (!mounted) return;
final ok = await showDialog<bool>(
context: context,
builder: (ctx) => AlertDialog(
title: const Text('Send reminder to the teachers?'),
content: SizedBox(
width: 480,
child: Column(mainAxisSize: MainAxisSize.min, children: [
Text(
'${items.length} reminder${items.length == 1 ? '' : 's'}. Each teacher sees it as a pop-up when the app is open.',
style: const TextStyle(fontWeight: FontWeight.w600)),
const SizedBox(height: 8),
Flexible(
child: ListView(shrinkWrap: true, children: [
for (final x in items)
ListTile(
dense: true,
contentPadding: EdgeInsets.zero,
leading:
const Icon(Icons.notifications_active, color: kLate),
title: Text('${x.name} · ${x.subject}'),
subtitle: Text(x.body),
),
]),
),
]),
),
actions: [
TextButton(
onPressed: () => Navigator.pop(ctx, false),
child: const Text('Cancel')),
FilledButton.icon(
onPressed: () => Navigator.pop(ctx, true),
icon: const Icon(Icons.send),
label: Text('Send ${items.length}')),
],
),
);
if (ok != true) return;
try {
final me = FirebaseAuth.instance.currentUser?.uid;
final batch = FirebaseFirestore.instance.batch();
for (final x in items) {
batch.set(FirebaseFirestore.instance.collection('notifications').doc(), {
'uid': x.uid,
'title': x.title,
'body': x.body,
'subject': x.subject,
'daysLeft': x.left,
'read': false,
'createdBy': me,
'createdAt': FieldValue.serverTimestamp(),
});
}
await batch.commit();
say('Reminder sent (${items.length}).');
} catch (e) {
say('Failed: ${'$e'.replaceFirst('Exception: ', '')}');
}
}

@override
Widget build(BuildContext context) {
if (_exam != _ResultPrefs.exam) {
_exam = _ResultPrefs.exam;
_resStream = _service.watchResults(_exam);
}
return Scaffold(
appBar: AppBar(title: const Text('Schedule'), actions: [
if (!teacherScope.value.scoped)
IconButton(
tooltip: 'Send a reminder to the teachers',
icon: const Icon(Icons.notifications_active_outlined),
onPressed: _sendReminders,
),
const SizedBox(width: 8),
]),
body: ValueListenableBuilder<AppSettings>(
valueListenable: appSettings,
builder: (context, st, _) => Align(
alignment: Alignment.topCenter,
child: ConstrainedBox(
constraints: const BoxConstraints(maxWidth: 760),
child: Column(children: [
Padding(
padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
child: _ExamPicker(
value: _ResultPrefs.exam,
onChanged: (v) => setState(() => _ResultPrefs.exam = v),
),
),
Expanded(
child: StreamBuilder<List<SectionInfo>>(
stream: _secStream,
builder: (context, secSnap) =>
StreamBuilder<List<StudentInfo>>(
stream: _stuStream,
builder: (context, stuSnap) =>
StreamBuilder<Map<String, ResultMarks>>(
stream: _resStream,
builder: (context, resSnap) {
if (secSnap.hasError || stuSnap.hasError) {
return Center(
child: Text(
'Error: ${secSnap.error ?? stuSnap.error}'));
}
if (!secSnap.hasData ||
!stuSnap.hasData ||
(!resSnap.hasData && !resSnap.hasError)) {
return const Center(
child: CircularProgressIndicator());
}
if (secSnap.data!.isEmpty) {
return const Center(
child: Padding(
padding: EdgeInsets.all(32),
child: Text('No sections yet.',
textAlign: TextAlign.center)));
}
_secs = secSnap.data;
_stus = stuSnap.data;
_res = resSnap.data ?? const <String, ResultMarks>{};
return ListView(
padding: const EdgeInsets.fromLTRB(16, 4, 16, 24),
children: [
_subjectSummaryCard(
context,
secSnap.data!,
stuSnap.data!,
resSnap.data ??
const <String, ResultMarks>{},
_twins,
_ResultPrefs.exam,
banner: const _DeadlineNote(),
deadlines: true),
],
);
},
),
),
),
),
]),
),
),
),
);
}
}

/// Settings: how many days are allowed to return the results of an exam,
/// counted from the exam date.
class _ReturnDaysCard extends StatefulWidget {
const _ReturnDaysCard();

@override
State<_ReturnDaysCard> createState() => _ReturnDaysCardState();
}

class _ReturnDaysCardState extends State<_ReturnDaysCard> {
late final TextEditingController _c =
TextEditingController(text: '${appSettings.value.resultDays}');
bool _busy = false;

@override
void dispose() {
_c.dispose();
super.dispose();
}

Future<void> _save() async {
final messenger = ScaffoldMessenger.of(context);
final n = int.tryParse(_c.text.trim());
if (n == null || n < 0 || n > 365) {
messenger.showSnackBar(const SnackBar(
content: Text('Enter a whole number of days from 0 to 365.')));
return;
}
setState(() => _busy = true);
try {
await appSettings.update({'resultDays': n});
messenger.showSnackBar(SnackBar(
content: Text('Results must be returned within $n day${n == 1 ? '' : 's'} after the exam')));
} catch (e) {
messenger.showSnackBar(SnackBar(
content: Text('Failed: ${'$e'.replaceFirst('Exception: ', '')}')));
} finally {
if (mounted) setState(() => _busy = false);
}
}

@override
Widget build(BuildContext context) {
return Card(
margin: EdgeInsets.zero,
elevation: 0,
color: Colors.white,
shape: _kSettingsCardShape,
child: Padding(
padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
const Row(children: [
Icon(Icons.timer_outlined, size: 20, color: kBlue),
SizedBox(width: 8),
Text('Returning exam results',
style: TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
]),
const SizedBox(height: 6),
const Text(
'Days allowed to return the results of a subject, counted from its '
'exam date (set in the Exam tab). The Schedule tab shows the days left: '
'exam date + these days.',
style: TextStyle(fontSize: 12.5, color: Colors.black54)),
const SizedBox(height: 12),
Row(children: [
Expanded(
child: TextField(
controller: _c,
keyboardType: TextInputType.number,
inputFormatters: [FilteringTextInputFormatter.digitsOnly],
onSubmitted: (_) => _save(),
decoration: const InputDecoration(
labelText: 'Days to return the results',
suffixText: 'days',
border: OutlineInputBorder(),
isDense: true,
),
),
),
const SizedBox(width: 10),
FilledButton.tonal(
onPressed: _busy ? null : _save, child: const Text('Save')),
]),
]),
),
);
}
}

/// Asks which subject(s) a student cheated in. Returns null when cancelled,
/// an empty list when every subject is ticked (= all subjects), otherwise the
/// ticked subjects.
Future<List<String>?> _pickCheatSubjects(
BuildContext context, {
required String title,
required String intro,
required String confirm,
Set<String>? initial,
}) {
final all = ExamService.subjects;
final chosen = <String>{
...((initial == null || initial.isEmpty) ? all : initial),
};
return showDialog<List<String>>(
context: context,
builder: (ctx) => StatefulBuilder(
builder: (ctx, setS) => AlertDialog(
title: Text(title),
content: SizedBox(
width: 360,
child: SingleChildScrollView(
child: Column(
mainAxisSize: MainAxisSize.min,
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Text(intro),
const SizedBox(height: 8),
CheckboxListTile(
dense: true,
contentPadding: EdgeInsets.zero,
controlAffinity: ListTileControlAffinity.leading,
title: const Text('All subjects',
style: TextStyle(fontWeight: FontWeight.w700)),
value: chosen.length == all.length,
onChanged: (v) => setS(() {
chosen.clear();
if (v == true) chosen.addAll(all);
}),
),
const Divider(height: 1),
for (final sub in all)
CheckboxListTile(
dense: true,
contentPadding: EdgeInsets.zero,
controlAffinity: ListTileControlAffinity.leading,
title: Text(sub),
value: chosen.contains(sub),
onChanged: (v) => setS(() {
if (v == true) {
chosen.add(sub);
} else {
chosen.remove(sub);
}
}),
),
],
),
),
),
actions: [
TextButton(
onPressed: () => Navigator.pop(ctx),
child: const Text('Cancel')),
FilledButton(
style: FilledButton.styleFrom(backgroundColor: kCheatColor),
onPressed: chosen.isEmpty
? null
    : () => Navigator.pop(
ctx,
chosen.length == all.length
? <String>[]
    : <String>[for (final x in all) if (chosen.contains(x)) x]),
child: Text(confirm),
),
],
),
),
);
}

/// "Cheating list" of the Result screen: the students marked as cheated in
/// the chosen exam. The administrator searches a student and marks him; all
/// his marks of the exam then show "Cheated".
class _CheatPanel extends StatefulWidget {
final String exam;
final List<StudentInfo> students;
final List<SectionInfo> sections;
final Map<String, String> twins;
const _CheatPanel({
required this.exam,
required this.students,
required this.sections,
required this.twins,
});

@override
State<_CheatPanel> createState() => _CheatPanelState();
}

class _CheatPanelState extends State<_CheatPanel> {
final _search = TextEditingController();
String _query = '';
bool _busy = false;

@override
void initState() {
super.initState();
CheatService.start();
}

@override
void dispose() {
_search.dispose();
super.dispose();
}

Map<String, SectionInfo> get _secs => {for (final s in widget.sections) s.id: s};

List<StudentInfo> _matches() {
final tokens = _query
    .toLowerCase()
    .split(RegExp(r'\s+'))
    .where((t) => t.isNotEmpty)
    .toList();
if (tokens.isEmpty) return const [];
final secs = _secs;
final inScope = {for (final s in widget.students) s.id};
final out = <StudentInfo>[];
for (final st in widget.students) {
if (!secs.containsKey(st.sectionId)) continue;
if (CheatService.byExam.value[widget.exam]?.containsKey(st.id) ?? false) {
continue;
}
final hay = '${st.name} ${st.studentNo}'.toLowerCase();
if (!tokens.every(hay.contains)) continue;
if (_isDupCopy(st, widget.twins, secs, inScope)) continue;
out.add(st);
}
out.sort((a, b) => a.name.toLowerCase().compareTo(b.name.toLowerCase()));
return out.take(8).toList();
}

Future<void> _mark(StudentInfo s) async {
final messenger = ScaffoldMessenger.of(context);
final label = _secs[s.sectionId]?.label ?? '';
final picked = await _pickCheatSubjects(
context,
title: 'Mark as cheated?',
intro: '${s.name}${label.isEmpty ? '' : ' ($label)'} cheated in '
'${widget.exam}.\n\nChoose the subject(s) the student cheated in. '
'Those fields show "Cheated" and are left out of the total and '
'average; the other subjects keep their marks. You can change the '
'subjects or remove the student from the list any time.',
confirm: 'Mark as cheated',
);
if (picked == null || !mounted) return;
setState(() => _busy = true);
try {
await CheatService.add(s, widget.exam, label, subjects: picked);
if (mounted) {
setState(() {
_search.clear();
_query = '';
});
}
messenger.showSnackBar(
SnackBar(content: Text('${s.name} was marked as cheated.')));
} catch (e) {
messenger.showSnackBar(SnackBar(
content: Text('Could not save: ${'$e'.replaceFirst('Exception: ', '')}')));
} finally {
if (mounted) setState(() => _busy = false);
}
}

Future<void> _editSubjects(CheatEntry e) async {
final messenger = ScaffoldMessenger.of(context);
final picked = await _pickCheatSubjects(
context,
title: 'Cheated subjects',
intro: '${e.name} · ${widget.exam}\n\nChoose the subject(s) the student cheated in.',
confirm: 'Save',
initial: e.subjects.toSet(),
);
if (picked == null || !mounted) return;
setState(() => _busy = true);
try {
await CheatService.setSubjects(widget.exam, e.id, picked);
} catch (err) {
messenger.showSnackBar(SnackBar(
content: Text('Could not save: ${'$err'.replaceFirst('Exception: ', '')}')));
} finally {
if (mounted) setState(() => _busy = false);
}
}

Future<void> _unmark(CheatEntry e) async {
final messenger = ScaffoldMessenger.of(context);
final ok = await showDialog<bool>(
context: context,
builder: (ctx) => AlertDialog(
title: const Text('Remove from the cheating list?'),
content: Text(
'${e.name} will show his marks of ${widget.exam} again '
'(the marks were never deleted).'),
actions: [
TextButton(
onPressed: () => Navigator.pop(ctx, false),
child: const Text('Cancel')),
FilledButton(
onPressed: () => Navigator.pop(ctx, true),
child: const Text('Remove')),
],
),
);
if (ok != true || !mounted) return;
setState(() => _busy = true);
try {
await CheatService.remove(widget.exam, e.id);
} catch (err) {
messenger.showSnackBar(SnackBar(
content: Text('Could not remove: ${'$err'.replaceFirst('Exception: ', '')}')));
} finally {
if (mounted) setState(() => _busy = false);
}
}

@override
Widget build(BuildContext context) {
return ValueListenableBuilder<Map<String, Map<String, CheatEntry>>>(
valueListenable: CheatService.byExam,
builder: (context, all, _) {
final list = (all[widget.exam]?.values.toList() ?? <CheatEntry>[])
..sort((a, b) => a.name.toLowerCase().compareTo(b.name.toLowerCase()));
final seen = <String>{};
final allEntries = <CheatEntry>[];
for (final e in list) {
final t = widget.twins[e.id];
if (t != null && seen.contains(t)) continue; // twin record
seen.add(e.id);
allEntries.add(e);
}
return StreamBuilder<UserProfile>(
stream: UserProfile.watchMine(),
builder: (context, ps) {
final admin = ps.data?.fullAccess == true;
// a teacher only sees students cheated in a subject they teach
final entries = admin
? allEntries
    : [for (final e in allEntries) if (CheatService.visibleEntry(e)) e];
final matches = admin ? _matches() : const <StudentInfo>[];
return Card(
child: Padding(
padding: const EdgeInsets.all(14),
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Row(children: [
const Icon(Icons.gavel, color: kCheatColor),
const SizedBox(width: 8),
const Expanded(
child: Text('Cheating list',
style: TextStyle(
fontSize: 17, fontWeight: FontWeight.w700)),
),
// only the administrator sees the report menu (it hides itself otherwise)
if (admin)
_ReportMenuButton(
iconOnly: true,
enabled: entries.isNotEmpty,
fileName: () => _safeFile('Cheating-${widget.exam}'),
build: () => ExamService()
    .buildCheatReportPdf(exam: widget.exam, entries: entries),
),
if (_busy)
const SizedBox(
width: 16,
height: 16,
child: CircularProgressIndicator(strokeWidth: 2)),
]),
const SizedBox(height: 2),
Text('${widget.exam} · ${entries.length} '
'student${entries.length == 1 ? '' : 's'}',
style: TextStyle(
fontSize: 12.5, color: Colors.grey.shade700)),
if (admin) ...[
const SizedBox(height: 10),
TextField(
controller: _search,
onChanged: (v) => setState(() => _query = v),
decoration: const InputDecoration(
isDense: true,
prefixIcon: Icon(Icons.search),
hintText: 'Search a student to mark as cheated',
border: OutlineInputBorder(),
),
),
if (_query.trim().isNotEmpty && matches.isEmpty)
const Padding(
padding: EdgeInsets.only(top: 8),
child: Text('No student found.',
style: TextStyle(fontSize: 12.5)),
),
for (final st in matches)
ListTile(
dense: true,
contentPadding: EdgeInsets.zero,
title: Text(st.name),
subtitle: Text([
_secs[st.sectionId]?.label ?? '',
if (st.studentNo.isNotEmpty) 'ID ${st.studentNo}',
].where((x) => x.isNotEmpty).join('  ·  ')),
trailing: TextButton.icon(
onPressed: _busy ? null : () => _mark(st),
icon: const Icon(Icons.block,
size: 16, color: kCheatColor),
label: const Text('Cheated',
style: TextStyle(color: kCheatColor)),
),
),
],
const Divider(height: 22),
if (entries.isEmpty)
Text(
admin
? 'No student is marked as cheated in this exam.'
    : 'No student in the cheating list.',
style: TextStyle(color: Colors.grey.shade700))
else
for (final e in entries)
ListTile(
dense: true,
contentPadding: EdgeInsets.zero,
onTap: (admin && !_busy) ? () => _editSubjects(e) : null,
leading: const CircleAvatar(
radius: 14,
backgroundColor: Color(0xFFFDECEA),
child: Icon(Icons.gavel,
size: 14, color: kCheatColor),
),
title: Text(e.name),
subtitle: Text([
e.subjects.isEmpty
? 'All subjects'
    : CheatService.visibleSubjects(e.subjects.toSet()).join(', '),
if (e.label.isNotEmpty) e.label,
if (e.studentNo.isNotEmpty) 'ID ${e.studentNo}',
if (e.at != null)
DateFormat('MMM d, y').format(e.at!),
].join('  ·  ')),
trailing: admin
? Row(mainAxisSize: MainAxisSize.min, children: [
TextButton.icon(
onPressed: _busy ? null : () => _editSubjects(e),
icon: const Icon(Icons.checklist, size: 16),
label: const Text('Subjects'),
),
IconButton(
tooltip: 'Remove from the list',
icon: const Icon(Icons.close, size: 18),
onPressed: _busy ? null : () => _unmark(e),
),
])
    : null,
),
],
),
),
);
},
);
},
);
}
}

class ResultBrowseScreen extends StatefulWidget {
final String? form, classKey;
const ResultBrowseScreen({super.key, this.form, this.classKey});

@override
State<ResultBrowseScreen> createState() => _ResultBrowseScreenState();
}

class _ResultBrowseScreenState extends State<ResultBrowseScreen> {
final _school = SchoolService();
final _service = ResultService();
late final Stream<List<SectionInfo>> _secStream = _school.watchSections();
late final Stream<List<StudentInfo>> _stuStream = _service.watchAllStudents();
late Stream<Map<String, ResultMarks>> _resStream =
_service.watchResults(_ResultPrefs.exam);
String _exam = _ResultPrefs.exam;
final _q = TextEditingController();
String _query = '';
Map<String, String> _twins = const {};
Map<String, Set<String>>? _absent; // null until read from attendance
StreamSubscription<Map<String, Set<String>>>? _absentSub;

@override
void initState() {
super.initState();
_service.twinMap().then((t) {
if (mounted) setState(() => _twins = t);
});
_absentSub = _service
    .watchAbsentSubjects(null, teacherScope.value.subjectList)
    .listen((a) {
if (mounted) setState(() => _absent = a);
}, onError: (Object _) {}); // no access to attendance: nothing to show
}

@override
void dispose() {
_absentSub?.cancel();
_q.dispose();
super.dispose();
}

/// "12 entered · 17 not entered" (green / red).
/// Tap "entered" / "not entered" to open the students of that scope,
/// filtered.
Widget _statusLine(int entered, int notEntered,
{void Function(int filter)? onTap, int? absent}) {
Widget part(String text, Color c, int filter) => InkWell(
onTap: onTap == null ? null : () => onTap(filter),
borderRadius: BorderRadius.circular(6),
child: Padding(
padding: const EdgeInsets.symmetric(vertical: 4, horizontal: 2),
child: Text(text,
style: TextStyle(
fontSize: 13,
fontWeight: FontWeight.w600,
color: c,
decoration: onTap == null
? null
    : TextDecoration.underline,
decorationColor: c.withAlpha(110))),
),
);
return Wrap(crossAxisAlignment: WrapCrossAlignment.center, children: [
part('$entered entered', const Color(0xFF2E7D32), 1),
const Text(' · ', style: TextStyle(color: Colors.grey)),
part('$notEntered not entered', const Color(0xFFC62828), 2),
if (absent != null) ...[
const Text(' · ', style: TextStyle(color: Colors.grey)),
part('$absent absent', const Color(0xFFE67E22), 3),
],
]);
}

static String _formName(String f) => f.replaceFirstMapped(
RegExp(r'^Form\s*(\d+)$'), (m) => 'Form ${m[1]}');

static String _n(int n, String w) => '$n $w${n == 1 ? '' : 's'}';

String get _title {
if (widget.form == null) return 'Result';
if (widget.classKey == null) return _formName(widget.form!);
return 'Class ${SectionInfo.code(widget.form!, widget.classKey!)}';
}

void _go(Widget w) => Navigator.of(context)
    .push(MaterialPageRoute(builder: (_) => w))
    .then((_) {
if (mounted) setState(() {}); // the exam may have been changed inside
});

/// Report of what this screen shows: every form (one table each), one whole
/// form, or one whole class.
Future<Uint8List> _buildReport() async => ExamService().buildResultReportPdf(
exam: _ResultPrefs.exam, groups: await _reportGroups());

Future<Uint8List> _buildReportXlsx() async => ExamService()
    .buildResultReportXlsx(
exam: _ResultPrefs.exam, groups: await _reportGroups(byClass: true));

Future<Uint8List> _buildReportDocx() async => ExamService()
    .buildResultReportDocx(exam: _ResultPrefs.exam, groups: await _reportGroups());

Future<List<ResultReportGroup>> _reportGroups({bool byClass = false}) async {
final exam = _ResultPrefs.exam;
final sections = await _school.watchSections().first;
final students = await _service.watchAllStudents().first;
final results = await _service.watchResults(exam).first;
final twins = await _service.twinMap();
final secOf = {for (final s in sections) s.id: s};

ResultReportGroup group(String title, bool Function(SectionInfo) inGroup) {
final ids = {for (final s in sections) if (inGroup(s)) s.id};
// a student who exists in the whole class AND in a section is listed once
final inScope = {
for (final x in students)
if (ids.contains(x.sectionId)) x.id
};
final list = [
for (final x in students)
if (inScope.contains(x.id) && !_isDupCopy(x, twins, secOf, inScope)) x
];
return ResultReportGroup(
title: title,
students: list,
sectionLabels: {for (final x in list) x.id: secOf[x.sectionId]?.label ?? ''},
results: results,
);
}

// Excel: one sheet for every class (1A, 1B, 2A ...) instead of one per form.
if (byClass && widget.classKey == null) {
final forms = widget.form == null
? teacherScope.value.formList
    : [widget.form!];
final out = <ResultReportGroup>[];
for (final f in forms) {
final keys = {
for (final sec in sections)
if (sec.form == f && sec.classKey.isNotEmpty) sec.classKey
}.toList()
..sort((a, b) => a.toLowerCase().compareTo(b.toLowerCase()));
for (final k in keys) {
out.add(group('Class ${SectionInfo.code(f, k)}',
(sec) => sec.form == f && sec.classKey == k));
}
}
if (out.isNotEmpty) return out;
}

final groups = widget.form == null
? [
for (final f in teacherScope.value.formList)
group(_formName(f), (s) => s.form == f),
]
    : widget.classKey == null
? [
group('All ${_formName(widget.form!)}',
(s) => s.form == widget.form)
]
    : [
group(
'All ${SectionInfo.code(widget.form!, widget.classKey!)}',
(s) =>
s.form == widget.form && s.classKey == widget.classKey)
];
return groups;
}

/// Opens the "Combined report" dialog for what this screen shows
/// (the whole school by form, one form, or one class).
void _openCombined() {
showDialog<void>(
context: context,
builder: (_) => _CombinedReportDialog(
title: _title == 'Result' ? 'School' : _title,
loadGroups: () => _reportGroups(),
),
);
}

Widget _tile(IconData icon, Color color, String title, String subtitle,
VoidCallback? onTap,
{Widget? extra}) =>
Card(
margin: const EdgeInsets.symmetric(vertical: 4),
child: ListTile(
leading: CircleAvatar(
backgroundColor: color.withAlpha(36),
child: Icon(icon, color: color),
),
title: Text(title,
style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
subtitle: extra == null
? Text(subtitle)
    : Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [Text(subtitle), extra],
),
trailing: onTap == null ? null : const Icon(Icons.chevron_right),
onTap: onTap,
),
);

Widget _cheatPanel(List<SectionInfo> sections, List<StudentInfo> students) =>
_CheatPanel(
exam: _ResultPrefs.exam,
students: students,
sections: sections,
twins: _twins,
);

Widget _summaryCard(List<SectionInfo> sections, List<StudentInfo> students,
Map<String, ResultMarks> results) =>
_subjectSummaryCard(
context, sections, students, results, _twins, _ResultPrefs.exam,
);

Widget _hint(String text) => Padding(
padding: const EdgeInsets.all(32),
child: Center(child: Text(text, textAlign: TextAlign.center)),
);

Widget _body(List<SectionInfo> sections, List<StudentInfo> students,
Map<String, ResultMarks> results,
{Widget? summary}) {
final count = <String, int>{};
for (final s in students) {
count[s.sectionId] = (count[s.sectionId] ?? 0) + 1;
}
final secById = {for (final s in sections) s.id: s};
int countOf(Iterable<SectionInfo> l) {
final inScope = {
for (final st in students)
if (l.any((x) => x.id == st.sectionId)) st.id
};
return inScope.length -
students
    .where((st) =>
inScope.contains(st.id) &&
_isDupCopy(st, _twins, secById, inScope))
    .length;
}
// entered = the student has marks for the chosen exam
Widget status(Iterable<SectionInfo> l, String title) {
final secIds = {for (final x in l) x.id};
final inScope = {
for (final st in students)
if (secIds.contains(st.sectionId)) st.id
};
var total = 0, entered = 0, absentN = 0;
for (final st in students) {
if (!inScope.contains(st.id) ||
_isDupCopy(st, _twins, secById, inScope)) {
continue;
}
total++;
if (results[st.id]?.average != null ||
(results[st.id]?.cheated ?? false)) {
entered++;
}
if (_absent?[st.id]?.isNotEmpty ?? false) absentN++;
}
return _statusLine(entered, total - entered,
absent: _absent == null ? null : absentN,
onTap: (f) => _go(ResultStudentsScreen(
title: title, sectionIds: secIds, initialFilter: f)));
}
Set<String> ids(Iterable<SectionInfo> l) => {for (final s in l) s.id};
const purple = Color(0xFF9B59B6);
const orange = Color(0xFFE67E22);

// ---- level 1: forms (+ search over every student) ----
if (widget.form == null) {
final secOf = {for (final s in sections) s.id: s};
final searching = _query.trim().isNotEmpty;
final found = searching
? [
for (final s in students)
if (_nameMatches(s.name, _query) &&
(!teacherScope.value.scoped ||
secOf.containsKey(s.sectionId)))
s
]
    : const <StudentInfo>[];
return ListView(
padding: const EdgeInsets.fromLTRB(16, 4, 16, 24),
children: [
if (!teacherScope.value.isStudent && sections.isNotEmpty)
_tile(
Icons.apartment,
orange,
'School',
_n(countOf(sections), 'student'),
null,
extra: status(sections, 'School'),
),
if (summary != null && _query.trim().isEmpty) summary,
if (searching) ...[
if (found.isEmpty) _hint('No student matches "${_query.trim()}".'),
for (final s in found.take(60))
Card(
margin: const EdgeInsets.symmetric(vertical: 3),
child: ListTile(
dense: true,
leading: const CircleAvatar(
radius: 16, child: Icon(Icons.person, size: 18)),
title: Text(s.name,
style: const TextStyle(fontWeight: FontWeight.w600)),
subtitle: Text(secOf[s.sectionId]?.label ?? ''),
trailing: teacherScope.value.isStudent ? null : const Icon(Icons.edit_note),
onTap: () => _openResultEditor(context, s,
secOf[s.sectionId]?.label ?? '', _ResultPrefs.exam,
form: secOf[s.sectionId]?.form),
),
),
if (found.length > 60)
Padding(
padding: const EdgeInsets.all(12),
child: Text('Showing the first 60 of ${found.length}. Type more of the name.',
textAlign: TextAlign.center,
style: TextStyle(color: Colors.grey.shade600)),
),
] else
for (final f in teacherScope.value.formList)
if (!teacherScope.value.isStudent ||
sections.any((s) => s.form == f))
Builder(builder: (_) {
final inForm = sections.where((s) => s.form == f).toList();
final classes = {for (final s in inForm) s.classKey}.length;
return _tile(
Icons.school,
kBlue,
_formName(f),
'${_n(countOf(inForm), 'student')} · ${_n(classes, 'class')}',
() => _go(ResultBrowseScreen(form: f)),
extra: status(inForm, 'All ${_formName(f)}'),
);
}),
],
);
}

// ---- level 2: classes of a form ----
if (widget.classKey == null) {
final inForm = sections.where((s) => s.form == widget.form).toList();
if (inForm.isEmpty) return _hint('No sections in this form yet.\nAdd them in Sections first.');
final classes = <String, List<SectionInfo>>{};
for (final s in inForm) {
(classes[s.classKey] ??= []).add(s);
}
final keys = classes.keys.toList()..sort();
return ListView(
padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
children: [
_tile(
Icons.groups,
orange,
'All ${_formName(widget.form!)}',
_n(countOf(inForm), 'student'),
() => _go(ResultStudentsScreen(
title: 'All ${_formName(widget.form!)}', sectionIds: ids(inForm))),
extra: status(inForm, 'All ${_formName(widget.form!)}'),
),
for (final k in keys)
Builder(builder: (_) {
final list = classes[k]!;
final code = SectionInfo.code(widget.form!, k);
return _tile(
Icons.class_,
purple,
'Class $code',
'${_n(countOf(list), 'student')}'
'${list.length > 1 ? ' · ${_n(list.length, 'section')}' : ''}',
() => list.length == 1
? _go(ResultStudentsScreen(
title: list.first.label, sectionIds: ids(list)))
    : _go(ResultBrowseScreen(form: widget.form, classKey: k)),
extra: status(list, 'All $code'),
);
}),
],
);
}

// ---- level 3: sections of a class, or all of it ----
final list = sections
    .where((s) => s.form == widget.form && s.classKey == widget.classKey)
    .toList();
if (list.isEmpty) return _hint('No sections in this class.');
final code = SectionInfo.code(widget.form!, widget.classKey!);
return ListView(
padding: const EdgeInsets.fromLTRB(16, 8, 16, 24),
children: [
_tile(
Icons.groups,
orange,
'All $code',
_n(countOf(list), 'student'),
() => _go(ResultStudentsScreen(title: 'All $code', sectionIds: ids(list))),
extra: status(list, 'All $code'),
),
// When the class is divided (3C-A, 3C-B ...), the plain whole-class entry
// ("Section 3C") is not shown: "All 3C" already is the whole class.
for (final s in list)
if (s.isSub || !list.any((x) => x.isSub))
_tile(
Icons.grid_view,
purple,
'Section ${s.label}',
_n(count[s.id] ?? 0, 'student'),
() => _go(ResultStudentsScreen(title: s.label, sectionIds: {s.id})),
extra: status([s], s.label),
),
],
);
}

@override
Widget build(BuildContext context) {
if (_exam != _ResultPrefs.exam) {
_exam = _ResultPrefs.exam;
_resStream = _service.watchResults(_exam);
}
return Scaffold(
appBar: AppBar(
title: Text(_title),
actions: [
if (!teacherScope.value.scoped)
_BarAction(
icon: Icons.functions,
label: 'Combined',
tooltip: 'Combine several exams in one report',
color: const Color(0xFF6A1B9A),
onTap: _openCombined,
),
if (!teacherScope.value.scoped)
_ReportMenuButton(
iconOnly: true,
fileName: () => _safeFile('Result-$_title-${_ResultPrefs.exam}'),
build: _buildReport,
buildXlsx: _buildReportXlsx,
buildDocx: _buildReportDocx,
),
],
),
body: LayoutBuilder(builder: (context, box) {
final level1 = widget.form == null && !teacherScope.value.isStudent;
// wide screen: summary + cheating list (under it) beside the forms
final wide = level1 && box.maxWidth >= 1000;
Widget content() => StreamBuilder<List<SectionInfo>>(
stream: _secStream,
builder: (context, secSnap) => StreamBuilder<List<StudentInfo>>(
stream: _stuStream,
builder: (context, stuSnap) =>
StreamBuilder<Map<String, ResultMarks>>(
stream: _resStream,
builder: (context, resSnap) {
if (secSnap.hasError || stuSnap.hasError) {
return _hint('Error: ${secSnap.error ?? stuSnap.error}');
}
if (!secSnap.hasData ||
!stuSnap.hasData ||
(!resSnap.hasData && !resSnap.hasError)) {
return const Center(child: CircularProgressIndicator());
}
final res =
resSnap.data ?? const <String, ResultMarks>{};
final card = level1 && secSnap.data!.isNotEmpty
? _summaryCard(secSnap.data!, stuSnap.data!, res)
    : null;
final main = _body(secSnap.data!, stuSnap.data!, res,
summary: wide || card == null
? (wide ? null : card)
    : Column(children: [
card,
const SizedBox(height: 12),
_cheatPanel(secSnap.data!, stuSnap.data!),
]));
if (!wide || card == null) return main;
return Align(
alignment: Alignment.topCenter,
child: ConstrainedBox(
constraints: const BoxConstraints(maxWidth: 1800),
child: Row(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
// left: summary by subject, with the cheating list under it
Expanded(
flex: 6,
child: SingleChildScrollView(
padding: const EdgeInsets.fromLTRB(16, 4, 8, 24),
child: Column(
crossAxisAlignment: CrossAxisAlignment.stretch,
children: [
card,
const SizedBox(height: 12),
_cheatPanel(secSnap.data!, stuSnap.data!),
],
),
),
),
// right: forms
Expanded(flex: 5, child: main),
],
),
),
);
},
),
),
);
return Column(children: [
if (widget.form == null)
Align(
alignment: Alignment.topCenter,
child: ConstrainedBox(
constraints: const BoxConstraints(maxWidth: 720),
child: Padding(
padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
child: Column(children: [
_ExamPicker(
value: _ResultPrefs.exam,
onChanged: (v) =>
setState(() => _ResultPrefs.exam = v),
),
const SizedBox(height: 10),
_searchField(_q, (v) => setState(() => _query = v)),
]),
),
),
),
Expanded(
child: wide
? content()
    : Align(
alignment: Alignment.topCenter,
child: ConstrainedBox(
constraints: const BoxConstraints(maxWidth: 720),
child: content()),
),
),
]);
}),
);
}
}

// ---------------- 4) Students of the chosen scope, with search ----------------

class ResultStudentsScreen extends StatefulWidget {
final String title;
final Set<String> sectionIds;

/// 0 = everyone, 1 = only students with marks entered,
/// 2 = only students without marks.
final int initialFilter;
const ResultStudentsScreen(
{super.key,
required this.title,
required this.sectionIds,
this.initialFilter = 0});

@override
State<ResultStudentsScreen> createState() => _ResultStudentsScreenState();
}

class _ResultStudentsScreenState extends State<ResultStudentsScreen> {
final _school = SchoolService();
final _service = ResultService();
late final Stream<List<SectionInfo>> _secStream = _school.watchSections();
late final Stream<List<StudentInfo>> _stuStream = _service.watchAllStudents();
late Stream<Map<String, ResultMarks>> _resStream =
_service.watchResults(_ResultPrefs.exam);
final _q = TextEditingController();
String _query = '';
late int _filter = widget.initialFilter;

/// Students whose marks are being typed in the list right now. They stay
/// in the list (and keep their boxes) even after the first save moves them
/// from "not entered" to "entered".
final Set<String> _pinned = {};
Map<String, String> _twins = const {};
// studentId -> subjects the student was absent in on the exam day
Map<String, Set<String>> _absent = const {};
StreamSubscription<Map<String, Set<String>>>? _absentSub;
void _onLock() {
if (mounted) setState(() {});
}


@override
void initState() {
super.initState();
_service.twinMap().then((t) {
if (mounted) setState(() => _twins = t);
});
_absentSub = _service
    .watchAbsentSubjects(null, teacherScope.value.subjectList)
    .listen((a) {
if (mounted) setState(() => _absent = a);
}, onError: (Object _) {}); // no access to attendance: nothing to show
SubjectLockService.start();
SubjectLockService.byExam.addListener(_onLock);
}

@override
void dispose() {
_absentSub?.cancel();
SubjectLockService.byExam.removeListener(_onLock);
_q.dispose();
super.dispose();
}

Widget _content(List<SectionInfo> sections, List<StudentInfo> all,
Map<String, ResultMarks> results) {
final secOf = {for (final s in sections) s.id: s};
String secLabel(StudentInfo s) => secOf[s.sectionId]?.label ?? '';
final multi = widget.sectionIds.length > 1;

final inScope = {
for (final s in all)
if (widget.sectionIds.contains(s.sectionId)) s.id
};
final students = [
for (final s in all)
if (inScope.contains(s.id) && !_isDupCopy(s, _twins, secOf, inScope)) s,
];
if (multi) {
students.sort((a, b) {
final c = secLabel(a).toLowerCase().compareTo(secLabel(b).toLowerCase());
return c != 0
? c
    : a.name.toLowerCase().compareTo(b.name.toLowerCase());
});
}
final number = {for (var i = 0; i < students.length; i++) students[i].id: i + 1};

// position (rank) by average, equal averages share a position
final scored = [
for (final s in students)
if (results[s.id]?.average != null) s,
]..sort((a, b) => results[b.id]!.average!.compareTo(results[a.id]!.average!));
final rank = <String, int>{};
for (var i = 0; i < scored.length; i++) {
final same = i > 0 &&
results[scored[i].id]!.average == results[scored[i - 1].id]!.average;
rank[scored[i].id] = same ? rank[scored[i - 1].id]! : i + 1;
}
final cheatedN = [
for (final s in students)
if (results[s.id]?.cheated ?? false) s
].length;
final groupAvg = scored.isEmpty
? null
    : scored.fold(0.0, (a, s) => a + results[s.id]!.average!) / scored.length;

bool hasMarks(StudentInfo s) => results[s.id]?.average != null;
bool isAbs(StudentInfo s) => _absent[s.id]?.isNotEmpty ?? false;
final absentCount = students.where(isAbs).length;
// marked as cheated in the cheating list (all subjects or only some)
bool isCheatAny(StudentInfo s) {
final r = results[s.id];
return (r?.cheated ?? false) || (r?.cheatedSubs.isNotEmpty ?? false);
}

final cheatedAnyN = students.where(isCheatAny).length;
final shown = [
for (final s in students)
if (_nameMatches(s.name, _query) &&
(_filter == 0 ||
(_filter == 3
? isAbs(s)
    : _filter == 4
? isCheatAny(s)
    : (_filter == 1 ? hasMarks(s) : !hasMarks(s))) ||
_pinned.contains(s.id)))
s,
];

List<ResultReportGroup> reportGroups() => [
ResultReportGroup(
title: widget.title,
students: students,
sectionLabels: {for (final x in students) x.id: secLabel(x)},
results: results,
),
];

return Column(children: [
Padding(
padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
child: Column(children: [
_ExamPicker(
value: _ResultPrefs.exam,
onChanged: (v) => setState(() {
_ResultPrefs.exam = v;
_pinned.clear();
_resStream = _service.watchResults(v);
}),
),
const SizedBox(height: 10),
_searchField(_q, (v) => setState(() => _query = v)),
]),
),
Padding(
padding: const EdgeInsets.fromLTRB(16, 0, 16, 4),
child: Row(children: [
Expanded(
child: Text.rich(TextSpan(
style: TextStyle(fontSize: 12.5, color: Colors.grey.shade700),
children: [
TextSpan(text: '${students.length} students · '),
TextSpan(
text: '${scored.length + cheatedN} entered',
style: const TextStyle(
color: Color(0xFF2E7D32),
fontWeight: FontWeight.w600)),
const TextSpan(text: ' · '),
TextSpan(
text: '${students.length - scored.length - cheatedN} not entered',
style: const TextStyle(
color: Color(0xFFC62828),
fontWeight: FontWeight.w600)),
if (absentCount > 0) ...[
const TextSpan(text: ' · '),
TextSpan(
text: '$absentCount absent',
style: const TextStyle(
color: Color(0xFFE67E22),
fontWeight: FontWeight.w600)),
],
if (cheatedAnyN > 0) ...[
const TextSpan(text: ' · '),
TextSpan(
text: '$cheatedAnyN cheated',
style: TextStyle(
color: kCheatColor, fontWeight: FontWeight.w600)),
],
if (groupAvg != null)
TextSpan(
text:
' · average ${_fmtMark(double.parse(groupAvg.toStringAsFixed(1)))}'),
])),
),
_ReportMenuButton(
enabled: scored.isNotEmpty,
fileName: () =>
_safeFile('Result-${widget.title}-${_ResultPrefs.exam}'),
build: () => ExamService().buildResultReportPdf(
exam: _ResultPrefs.exam,
groups: reportGroups(),
),
buildXlsx: () async => ExamService().buildResultReportXlsx(
exam: _ResultPrefs.exam,
groups: reportGroups(),
),
buildDocx: () async => ExamService().buildResultReportDocx(
exam: _ResultPrefs.exam,
groups: reportGroups(),
),
),
const SizedBox(width: 8),
if (!teacherScope.value.isStudent)
FilledButton.tonalIcon(
onPressed: students.isEmpty
? null
    : () => Navigator.of(context).push(MaterialPageRoute(
builder: (_) => ResultBulkScreen(
title: widget.title,
exam: _ResultPrefs.exam,
students: students,
sectionLabels: {for (final s in students) s.id: secLabel(s)},
studentForms: {
for (final s in students)
s.id: secOf[s.sectionId]?.form ?? ''
},
),
)),
icon: const Icon(Icons.grid_on, size: 18),
label: const Text('Enter all'),
),
]),
),
Padding(
padding: const EdgeInsets.fromLTRB(16, 0, 16, 4),
child: Align(
alignment: Alignment.centerLeft,
child: Wrap(spacing: 8, runSpacing: 4, children: [
for (final f in [
(0, 'All'),
(1, 'Entered'),
(2, 'Not entered'),
if (absentCount > 0) (3, 'Absent'),
if (cheatedAnyN > 0) (4, 'Cheated'),
])
ChoiceChip(
label: Text(
'${f.$2} ${f.$1 == 0 ? students.length : f.$1 == 1 ? scored.length : f.$1 == 3 ? absentCount : f.$1 == 4 ? cheatedAnyN : students.length - scored.length}'),
selected: _filter == f.$1,
onSelected: (_) => setState(() {
_filter = f.$1;
_pinned.clear();
}),
),
]),
),
),
Expanded(
child: students.isEmpty
? const Center(child: Text('This group has no students yet.'))
    : shown.isEmpty
? Center(
child: Text(_query.trim().isEmpty
? (_filter == 1
? 'No student has marks entered yet.'
    : _filter == 3 ? 'No student was absent.' : _filter == 4 ? 'No student is marked as cheated.'
    : 'Every student has marks entered.')
    : 'No student matches "${_query.trim()}".'))
    : ListView.builder(
padding: const EdgeInsets.fromLTRB(16, 4, 16, 16),
itemCount: shown.length,
itemBuilder: (context, i) {
final s = shown[i];
final r = results[s.id];
final avg = r?.average;
final g = avg == null
? null
    : _gradeOf(avg,
max: _gradeMax(_ResultPrefs.exam, SchoolService.formOf(s)));
// Marks are typed straight in the list (not for a student login).
final sForm = secOf[s.sectionId]?.form;
final inlineSubs = teacherScope.value.isStudent
? const <String>[]
    : [
for (final x in teacherScope.value.subjectList)
if ((sForm == null || teacherScope.value.allows(x, sForm)) &&
!(r?.cheatedSubs.contains(x) ?? false) &&
!SubjectLockService.isComplete(_ResultPrefs.exam, x, sForm ?? ''))
x,
];
final cheated = results[s.id]?.cheated ?? false;
final inline = inlineSubs.isNotEmpty &&
!cheated &&
(avg == null || _pinned.contains(s.id));
Widget marksBox() => _InlineMarks(
key: ValueKey('${s.id}|${_ResultPrefs.exam}'),
student: s,
subjects: inlineSubs,
exam: _ResultPrefs.exam,
absent: _absent[s.id] ?? const <String>{},
newSubs: {
for (final sub in inlineSubs)
if (studentIsNew(s.createdAt, sub)) sub
},
onStart: () => _pinned.add(s.id),
);
return Card(
margin: const EdgeInsets.symmetric(vertical: 3),
child: InkWell(
borderRadius: BorderRadius.circular(12),
onTap: () => _openResultEditor(
context, s, secLabel(s), _ResultPrefs.exam,
form: secOf[s.sectionId]?.form),
child: Padding(
padding: const EdgeInsets.symmetric(
horizontal: 12, vertical: 10),
child: Row(children: [
CircleAvatar(
radius: 14,
backgroundColor: g == null
? Colors.grey.shade400
    : _gradeColor(g),
child: Text('${number[s.id]}',
style: const TextStyle(
fontSize: 11, color: Colors.white)),
),
const SizedBox(width: 10),
Expanded(
child: Column(
crossAxisAlignment: CrossAxisAlignment.start,
children: [
Text(s.name,
maxLines: 2,
overflow: TextOverflow.ellipsis,
style: const TextStyle(
fontSize: 14.5,
fontWeight: FontWeight.w600)),
if (multi || s.studentNo.isNotEmpty) ...[
const SizedBox(height: 2),
Text(
[
if (s.studentNo.isNotEmpty) 'ID ${s.studentNo}',
if (multi) secLabel(s),
].join('  ·  '),
style: TextStyle(
fontSize: 12,
color: Colors.grey.shade600)),
],
if (inline && inlineSubs.length > 1) ...[
const SizedBox(height: 8),
marksBox(),
],
],
),
),
if (inline && inlineSubs.length == 1)
marksBox()
else if (inline)
const SizedBox.shrink()
else if (r == null || avg == null)
Text(cheated ? 'Cheated' : 'No result',
style: TextStyle(
fontSize: 12,
fontWeight: cheated ? FontWeight.w800 : FontWeight.w400,
color: cheated ? kCheatColor : Colors.grey.shade500))
else
Column(
crossAxisAlignment: CrossAxisAlignment.end,
children: [
Row(mainAxisSize: MainAxisSize.min, children: [
Container(
padding: const EdgeInsets.symmetric(
horizontal: 8, vertical: 2),
decoration: BoxDecoration(
color: _gradeColor(g!).withAlpha(36),
borderRadius: BorderRadius.circular(8),
),
child: Text(g,
style: TextStyle(
fontWeight: FontWeight.w800,
color: _gradeColor(g))),
),
const SizedBox(width: 8),
Text(
_fmtMark(double.parse(
avg.toStringAsFixed(1))),
style: const TextStyle(
fontSize: 16,
fontWeight: FontWeight.w800)),
]),
],
),
if (!teacherScope.value.isStudent) ...[
const SizedBox(width: 4),
const Icon(Icons.edit_note, size: 20),
],
]),
),
),
);
},
),
),
]);
}

@override
Widget build(BuildContext context) {
return Scaffold(
appBar: AppBar(title: Text(widget.title)),
body: Align(
alignment: Alignment.topCenter,
child: ConstrainedBox(
constraints: const BoxConstraints(maxWidth: 720),
child: StreamBuilder<List<SectionInfo>>(
stream: _secStream,
builder: (context, secSnap) => StreamBuilder<List<StudentInfo>>(
stream: _stuStream,
builder: (context, stuSnap) =>
StreamBuilder<Map<String, ResultMarks>>(
stream: _resStream,
builder: (context, resSnap) {
final err = secSnap.error ?? stuSnap.error ?? resSnap.error;
if (err != null) {
return Center(
child: Padding(
padding: const EdgeInsets.all(24),
child: Text('Error: $err', textAlign: TextAlign.center),
));
}
if (!secSnap.hasData || !stuSnap.hasData) {
return const Center(child: CircularProgressIndicator());
}
return _content(
secSnap.data!, stuSnap.data!, resSnap.data ?? const {});
},
),
),
),
),
),
);
}
}

// ---------------- Mark entry for MANY students at once ----------------

/// One table: a row per student, a column per subject. Type all the marks,
/// then save once. Only the rows that were changed are written, and the marks
/// of subjects the person may not see are kept untouched.
class ResultBulkScreen extends StatefulWidget {
final String title, exam;
final List<StudentInfo> students;
final Map<String, String> sectionLabels; // studentId -> section label
final Map<String, String> studentForms; // studentId -> form
const ResultBulkScreen({
super.key,
required this.title,
required this.exam,
required this.students,
required this.sectionLabels,
this.studentForms = const {},
});

@override
State<ResultBulkScreen> createState() => _ResultBulkScreenState();
}

class _ResultBulkScreenState extends State<ResultBulkScreen> {
final _service = ResultService();
late final List<String> _subjects = teacherScope.value.subjectList;
final Map<String, Map<String, TextEditingController>> _c = {};
final Map<String, Map<String, double>> _hidden = {};
final Map<String, String> _orig = {}; // 'studentId|subject' -> first text
bool _loading = true, _saving = false;
String? _error;

@override
void initState() {
super.initState();
_load();
}

Future<void> _load() async {
try {
CheatService.start();
await CheatService.ready;
await SubjectLockService.ready;
final all = await _service.getAllForExam(widget.exam);
var absent = <String, Set<String>>{};
try {
absent = await _service.absentSubjects(
[for (final s in widget.students) s.id], _subjects);
} catch (_) {} // no access to attendance: no pre-fill
for (final s in widget.students) {
final m = all[s.id] ?? const <String, double>{};
final hid = <String, double>{};
for (final e in m.entries) {
if (!_subjects.contains(e.key) ||
CheatService.isCheatedIn(widget.exam, s.id, e.key)) {
hid[e.key] = e.value;
}
}
final row = <String, TextEditingController>{};
for (final sub in _subjects) {
final v = m[sub];
final t = CheatService.isCheatedIn(widget.exam, s.id, sub) ? kCheatText
    : v != null
? _fmtMark(v)
    : studentIsNew(s.createdAt, sub)
? kNewText
    : (absent[s.id]?.contains(sub) ?? false)
? kAbsentText
    : '';
row[sub] = TextEditingController(text: t);
_orig['${s.id}|$sub'] = t;
}
_c[s.id] = row;
_hidden[s.id] = hid;
}
if (mounted) setState(() => _loading = false);
} catch (e) {
if (mounted) {
setState(() {
_loading = false;
_error = 'Could not load: $e';
});
}
}
}

@override
void dispose() {
for (final row in _c.values) {
for (final c in row.values) {
c.dispose();
}
}
super.dispose();
}

/// A teacher may only type a mark where the subject is taught in the
/// form of the student (other boxes stay locked and keep their value).
bool _can(String studentId, String subject) {
final f = widget.studentForms[studentId] ?? '';
return f.isEmpty || teacherScope.value.allows(subject, f);
}

/// True when [subject] is Complete in every form of this list.
bool _allClosed(String subject) {
final fs = widget.studentForms.values.where((f) => f.isNotEmpty).toSet();
if (fs.isEmpty) return SubjectLockService.isComplete(widget.exam, subject);
return fs.every((f) => SubjectLockService.isComplete(widget.exam, subject, f));
}

bool _isBad(String text, String studentId) {
final t = text.trim();
if (t.isEmpty || _isAbsentText(t)) return false;
final v = double.tryParse(t);
final f = widget.studentForms[studentId] ?? '';
return v == null ||
v < minMarkOf(widget.exam, f) ||
v > maxMarkOf(widget.exam, f);
}

int get _changedRows {
var n = 0;
for (final s in widget.students) {
final row = _c[s.id];
if (row == null) continue;
if (_subjects
    .any((sub) => row[sub]!.text.trim() != _orig['${s.id}|$sub'])) {
n++;
}
}
return n;
}

Future<void> _save() async {
final items = <(StudentInfo, Map<String, double>)>[];
var bad = false;
String? badRange;
for (final s in widget.students) {
final row = _c[s.id];
if (row == null) continue;
var changed = false;
final marks = <String, double>{};
for (final sub in _subjects) {
final t = row[sub]!.text.trim();
if (t != _orig['${s.id}|$sub']) changed = true;
if (t.isEmpty || _isAbsentText(t)) continue;
final v = double.tryParse(t);
final f = widget.studentForms[s.id] ?? '';
if (v == null || v < minMarkOf(widget.exam, f) || v > maxMarkOf(widget.exam, f)) {
bad = true;
badRange ??= '${_fmtMark(minMarkOf(widget.exam, f))} to ${_fmtMark(maxMarkOf(widget.exam, f))}';
continue;
}
marks[sub] = v;
}
if (changed) items.add((s, {..._hidden[s.id]!, ...marks}));
}
if (bad) {
setState(() =>
_error = 'Fix the marks shown in red ($badRange).');
return;
}
if (items.isEmpty) {
setState(() => _error = 'Nothing was changed.');
return;
}
setState(() {
_saving = true;
_error = null;
});
try {
await _service.saveMany(widget.exam, items);
if (!mounted) return;
ScaffoldMessenger.of(context).showSnackBar(SnackBar(
content: Text('Saved results of ${items.length} '
'student${items.length == 1 ? '' : 's'}')));
Navigator.pop(context);
} catch (e) {
if (mounted) {
setState(() {
_saving = false;
_error = '$e'.replaceFirst('Exception: ', '');
});
}
}
}

@override
Widget build(BuildContext context) {
const numW = 36.0, nameW = 210.0, cellW = 90.0, avgW = 90.0;
final multi = widget.sectionLabels.values.toSet().length > 1;
final changed = _loading ? 0 : _changedRows;

Widget body;
if (_loading) {
body = const Center(child: CircularProgressIndicator());
} else if (_subjects.isEmpty) {
body = const Center(
child: Padding(
padding: EdgeInsets.all(24),
child: Text(
'No subjects are set on your account.\n'
'Ask the administrator to add them in Teachers.',
textAlign: TextAlign.center),
));
} else {
final width = numW + nameW + cellW * _subjects.length + avgW + 32;
body = SingleChildScrollView(
scrollDirection: Axis.horizontal,
child: SizedBox(
width: width,
child: Column(children: [
Container(
color: kBlue,
padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 8),
child: Row(children: [
const SizedBox(width: numW, child: Text('#', style: _bulkHead)),
const SizedBox(
width: nameW, child: Text('Student', style: _bulkHead)),
for (final sub in _subjects)
SizedBox(
