),
),
for (final sub in _subjects)
SizedBox(
width: cellW,
child: Padding(
padding: const EdgeInsets.only(right: 8),
child: TextField(
controller: row[sub],
enabled: !_saving &&
_can(s.id, sub) &&
!SubjectLockService.isComplete(
widget.exam, sub, widget.studentForms[s.id] ?? ''),
readOnly: _isAbsentText(row[sub]!.text),
canRequestFocus: !_isAbsentText(row[sub]!.text),
textAlign: TextAlign.center,
style: _isAbsentText(row[sub]!.text)
? TextStyle(
color: isNewText(row[sub]!.text) ? kNewColor : kRed,
fontWeight: FontWeight.w700,
fontSize: 13)
    : null,
textInputAction: TextInputAction.next,
keyboardType:
const TextInputType.numberWithOptions(
decimal: true),
inputFormatters: [
FilteringTextInputFormatter.allow(
RegExp(r'[0-9.]')),
],
onChanged: (_) => setState(() => _error = null),
decoration: InputDecoration(
isDense: true,
filled: _isAbsentText(row[sub]!.text),
fillColor: isNewText(row[sub]!.text)
? const Color(0xFFE3F2FD)
    : const Color(0xFFFDECEA),
border: const OutlineInputBorder(),
enabledBorder: OutlineInputBorder(
borderSide: BorderSide(
color: isNewText(row[sub]!.text)
? kNewColor
    : (_isBad(row[sub]!.text, s.id) ||
_isAbsentText(row[sub]!.text))
? Colors.red
    : Colors.grey.shade400,
width: _isBad(row[sub]!.text, s.id) ? 2 : 1,
),
),
contentPadding: const EdgeInsets.symmetric(
horizontal: 6, vertical: 10),
),
),
),
),
SizedBox(
width: avgW,
child: avg == null
? const Text('–')
    : Row(children: [
Text(
_fmtMark(double.parse(avg.toStringAsFixed(1))),
style: const TextStyle(
fontWeight: FontWeight.w800)),
const SizedBox(width: 6),
Text(
_gradeOf(avg,
max: _gradeMax(widget.exam, SchoolService.formOf(s))),
style: TextStyle(
fontWeight: FontWeight.w800,
color: _gradeColor(_gradeOf(avg,
max: _gradeMax(
widget.exam, SchoolService.formOf(s)))))),
]),
),
]),
);
},
),
),
]),
),
);
}

return Scaffold(
appBar: AppBar(
title: Text('${widget.title} · ${widget.exam}'),
actions: [
Padding(
padding: const EdgeInsets.only(right: 12),
child: Center(
child: FilledButton.icon(
onPressed: (_loading || _saving || _subjects.isEmpty)
? null
    : _save,
icon: _saving
? const SizedBox(
width: 16,
height: 16,
child: CircularProgressIndicator(strokeWidth: 2))
    : const Icon(Icons.save),
label: Text(changed == 0 ? 'Save' : 'Save ($changed)'),
),
),
),
],
),
body: Column(children: [
Padding(
