static const _bulkHead = TextStyle(
color: Colors.white, fontWeight: FontWeight.bold, fontSize: 14);
}

/// Boxes to type the marks of one student straight in the list (one box per
/// subject the person may enter). A mark is saved when its box loses focus
/// (Enter / Tab / tapping elsewhere). Other marks of the student, also the
/// ones this person may not see, are kept as they are.
class _InlineMarks extends StatefulWidget {
final StudentInfo student;
final List<String> subjects;
final String exam;
final VoidCallback onStart;

/// Subjects the student was absent in (attendance): shown as Absent, locked.
final Set<String> absent;

/// Subjects whose exam was held before the student was added: shown as New.
final Set<String> newSubs;
const _InlineMarks({
super.key,
required this.student,
required this.subjects,
required this.exam,
required this.onStart,
this.absent = const {},
this.newSubs = const {},
});

@override
State<_InlineMarks> createState() => _InlineMarksState();
}

class _InlineMarksState extends State<_InlineMarks> {
final _svc = ResultService();
late final Map<String, TextEditingController> _c = {
for (final s in widget.subjects)
s: TextEditingController(
text: widget.newSubs.contains(s)
? kNewText
    : widget.absent.contains(s)
? kAbsentText
    : ''),
};
late final Map<String, FocusNode> _f = {
for (final s in widget.subjects) s: FocusNode(),
};
final Map<String, String> _saved = {}; // subject -> text already saved
Future<void> _chain = Future.value();
bool _saving = false, _ok = false;
Timer? _typing;

/// Queue a save now (saves never overlap, so no mark is lost).
void _saveNow() {
_typing?.cancel();
_chain = _chain.then((_) => _run());
}

@override
void initState() {
super.initState();
_f.forEach((sub, node) {
node.addListener(() {
if (node.hasFocus) {
widget.onStart();
} else {
_saveNow();
}
});
});
}

@override
void dispose() {
_typing?.cancel();
for (final c in _c.values) {
c.dispose();
}
for (final f in _f.values) {
f.dispose();
}
super.dispose();
}

bool _lock(String sub) =>
widget.absent.contains(sub) || widget.newSubs.contains(sub);
Color _lockColor(String sub) =>
widget.newSubs.contains(sub) ? kNewColor : kRed;

bool _isBad(String text) {
final t = text.trim();
if (t.isEmpty || _isAbsentText(t)) return false;
final v = double.tryParse(t);
final f = SchoolService.formOf(widget.student);
return v == null ||
v < minMarkOf(widget.exam, f) ||
v > maxMarkOf(widget.exam, f);
}

Future<void> _run() async {
final typed = <String, double>{};
for (final sub in widget.subjects) {
final t = _c[sub]!.text.trim();
if (t.isEmpty ||
_isAbsentText(t) ||
t == (_saved[sub] ?? '') ||
_isBad(t)) {
continue;
}
typed[sub] = double.parse(t);
}
if (typed.isEmpty) return;
if (mounted) setState(() => _saving = true);
try {
// read the stored marks first so no other subject is lost
final cur = await _svc.get(widget.student.id, widget.exam, raw: true);
await _svc.save(widget.student, widget.exam, {...cur.marks, ...typed});
for (final e in typed.keys) {
_saved[e] = _c[e]!.text.trim();
}
if (mounted) {
setState(() {
_saving = false;
_ok = true;
});
}
} catch (e) {
if (!mounted) return;
setState(() => _saving = false);
ScaffoldMessenger.of(context).showSnackBar(SnackBar(
content: Text('Could not save ${widget.student.name}: '
'${'$e'.replaceFirst('Exception: ', '')}')));
}
}

@override
Widget build(BuildContext context) {
final single = widget.subjects.length == 1;
const red = OutlineInputBorder(
borderSide: BorderSide(color: Color(0xFFC62828), width: 1.5));
const blue = OutlineInputBorder(
borderSide: BorderSide(color: kNewColor, width: 1.5));
Widget box(String sub) => SizedBox(
width: single ? 92 : 84,
child: TextField(
controller: _c[sub],
focusNode: _f[sub],
readOnly: _lock(sub),
canRequestFocus: !_lock(sub),
textAlign: TextAlign.center,
textInputAction: TextInputAction.next,
keyboardType: const TextInputType.numberWithOptions(decimal: true),
inputFormatters: [FilteringTextInputFormatter.allow(RegExp(r'[0-9.]'))],
style: _lock(sub)
? TextStyle(
fontSize: 13, fontWeight: FontWeight.w700, color: _lockColor(sub))
    : const TextStyle(fontSize: 14, fontWeight: FontWeight.w600),
onChanged: (_) {
setState(() => _ok = false);
// auto-save a moment after the last key, no need to leave the box
_typing?.cancel();
_typing = Timer(const Duration(milliseconds: 300), _saveNow);
},
onSubmitted: (_) {
_saveNow();
FocusScope.of(context).nextFocus();
},
decoration: InputDecoration(
isDense: true,
filled: _lock(sub),
fillColor: widget.newSubs.contains(sub)
? const Color(0xFFE3F2FD)
    : const Color(0xFFFDECEA),
labelText: single ? 'Mark' : sub,
labelStyle: const TextStyle(fontSize: 11),
floatingLabelBehavior: FloatingLabelBehavior.auto,
contentPadding:
const EdgeInsets.symmetric(horizontal: 6, vertical: 10),
border: const OutlineInputBorder(),
enabledBorder: widget.newSubs.contains(sub)
? blue
    : (_isBad(_c[sub]!.text) || _lock(sub)) ? red : null,
focusedBorder: widget.newSubs.contains(sub)
? blue
    : (_isBad(_c[sub]!.text) || _lock(sub)) ? red : null,
),
),
);
final status = _saving
? const SizedBox(
width: 16,
height: 16,
child: CircularProgressIndicator(strokeWidth: 2))
    : _ok
? const Icon(Icons.check_circle, size: 18, color: Color(0xFF2E7D32))
    : null;
if (single) {
return Row(mainAxisSize: MainAxisSize.min, children: [
box(widget.subjects.first),
SizedBox(width: 26, child: status == null ? null : Center(child: status)),
]);
}
return Wrap(
spacing: 8,
runSpacing: 8,
crossAxisAlignment: WrapCrossAlignment.center,
children: [for (final sub in widget.subjects) box(sub), if (status != null) status],
);
}
}

// ---------------- Mark entry for one student ----------------

Future<void> _openResultEditor(
BuildContext context, StudentInfo s, String sectionLabel, String exam,
{String? form}) {
// a student can look at the own result but never change it
if (teacherScope.value.isStudent) {
return showDialog(
context: context,
builder: (_) => _ResultViewDialog(
student: s, sectionLabel: sectionLabel, exam: exam),
);
}
return showDialog(
context: context,
builder: (_) => _ResultEditorDialog(
student: s, sectionLabel: sectionLabel, exam: exam, form: form),
);
}

/// Read-only marks of one student (what a student sees).
class _ResultViewDialog extends StatelessWidget {
final StudentInfo student;
final String sectionLabel, exam;
const _ResultViewDialog({
required this.student,
required this.sectionLabel,
required this.exam,
});

@override
Widget build(BuildContext context) {
return AlertDialog(
title: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
Text(student.name,
style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
const SizedBox(height: 2),
Text('${sectionLabel.isEmpty ? '' : '$sectionLabel · '}$exam',
style: TextStyle(fontSize: 13, color: Colors.grey.shade700)),
]),
content: SizedBox(
width: 380,
child: FutureBuilder<ResultMarks>(
future: ResultService().get(student.id, exam),
builder: (context, snap) {
if (snap.hasError) return Text('Could not load: ${snap.error}');
if (!snap.hasData) {
return const SizedBox(
height: 100,
child: Center(child: CircularProgressIndicator()));
}
final r = snap.data!;
if (r.cheated) {
return const Text(
'Cheated: this student is in the cheating list of this exam, '
'so no marks count.',
style: TextStyle(color: kCheatColor, fontWeight: FontWeight.w700));
}
if (r.marks.isEmpty && r.cheatedSubs.isEmpty) {
return const Text('No result yet.');
}
final avg = r.average;
final g = avg == null ? null : _gradeOf(avg, max: _gradeMax(exam));
return SingleChildScrollView(
child: Column(mainAxisSize: MainAxisSize.min, children: [
for (final sub in ExamService.subjects)
if (r.marks[sub] != null)
Padding(
padding: const EdgeInsets.symmetric(vertical: 4),
child: Row(children: [
Expanded(child: Text(sub)),
Text(_fmtMark(r.marks[sub]!),
style:
const TextStyle(fontWeight: FontWeight.w700)),
]),
),
for (final sub in ExamService.subjects)
if (r.marks[sub] == null && studentIsNew(student.createdAt, sub))
Padding(
padding: const EdgeInsets.symmetric(vertical: 4),
child: Row(children: [
Expanded(child: Text(sub)),
const Text(kNewText,
style: TextStyle(
fontWeight: FontWeight.w700, color: kNewColor)),
]),
),
for (final sub in ExamService.subjects)
if (r.cheatedSubs.contains(sub))
Padding(
padding: const EdgeInsets.symmetric(vertical: 4),
child: Row(children: [
Expanded(child: Text(sub)),
const Text(kCheatText,
style: TextStyle(
fontWeight: FontWeight.w700, color: kCheatColor)),
]),
),
const Divider(),
Row(children: [
const Expanded(child: Text('Total')),
Text(_fmtMark(r.total),
style: const TextStyle(fontWeight: FontWeight.w700)),
]),
const SizedBox(height: 4),
Row(children: [
const Expanded(child: Text('Average')),
Text(avg == null ? '–' : _fmtMark(double.parse(avg.toStringAsFixed(1))),
style: const TextStyle(fontWeight: FontWeight.w700)),
const SizedBox(width: 8),
Text(g ?? '',
style: TextStyle(
fontWeight: FontWeight.w800,
color: g == null ? null : _gradeColor(g))),
]),
]),
);
},
),
),
actions: [
TextButton(
onPressed: () => Navigator.pop(context), child: const Text('Close')),
],
);
}
}

class _ResultEditorDialog extends StatefulWidget {
final StudentInfo student;
final String sectionLabel, exam;

/// The form of the student: a teacher can only enter the marks of the
/// subjects taught in this form.
final String? form;
const _ResultEditorDialog({
required this.student,
required this.sectionLabel,
required this.exam,
this.form,
});

@override
State<_ResultEditorDialog> createState() => _ResultEditorDialogState();
}

class _ResultEditorDialogState extends State<_ResultEditorDialog> {
final _service = ResultService();
late final _ctrl = {
for (final s in teacherScope.value.subjectList)
if (widget.form == null || teacherScope.value.allows(s, widget.form!))
s: TextEditingController(),
};
// marks of subjects this person may not see: kept as they are when saving
final Map<String, double> _hidden = {};
bool _admin = false;
bool _loading = true;
bool _saving = false;
String? _error;

@override
void initState() {
super.initState();
UserProfile.watchMine().first.then((p) {
if (mounted) setState(() => _admin = p.fullAccess);
}).catchError((_) {});
_service.get(widget.student.id, widget.exam, raw: true).then((r) async {
var absent = <String, Set<String>>{};
try {
absent = await _service.absentSubjects(
[widget.student.id], _ctrl.keys.toList());
} catch (_) {} // no access to attendance: no pre-fill
if (!mounted) return;
setState(() {
r.marks.forEach((k, v) {
final c = _ctrl[k]; if (c == null || r.cheatedSubs.contains(k)) { _hidden[k] = v;
} else {
c.text = _fmtMark(v);
}
});
// in the cheating list: every field shows Cheated (locked, never saved)
if (CheatService.isCheated(widget.exam, widget.student.id)) {
for (final c in _ctrl.values) {
c.text = kCheatText;
}
}
// cheated in some subjects only: those fields show Cheated (locked,
// never saved; the stored mark is kept)
for (final sub in r.cheatedSubs) {
final c = _ctrl[sub];
if (c != null) c.text = kCheatText;
}
// added after the exam date of a subject: show New (locked, never saved)
for (final e in _ctrl.entries) {
if (e.value.text.trim().isEmpty &&
studentIsNew(widget.student.createdAt, e.key)) {
e.value.text = kNewText;
}
}
// absent in attendance and no mark yet: show Absent (never saved)
for (final sub in absent[widget.student.id] ?? const <String>{}) {
final c = _ctrl[sub];
if (c != null && c.text.trim().isEmpty) c.text = kAbsentText;
}
_loading = false;
});
}).catchError((Object e) {
if (!mounted) return;
setState(() {
_loading = false;
_error = 'Could not load: $e';
});
});
}

@override
void dispose() {
for (final c in _ctrl.values) {
c.dispose();
}
super.dispose();
}

String get _form => widget.form ?? SchoolService.formOf(widget.student);

/// Administrator: choose which subjects the student cheated in.
Future<void> _editCheatSubjects() async {
final entry = CheatService.byExam.value[widget.exam]?[widget.student.id];
if (entry == null) return;
final picked = await _pickCheatSubjects(
context,
title: 'Cheated subjects',
intro: '${widget.student.name} · ${widget.exam}\n\nChoose the subject(s) the student cheated in.',
confirm: 'Save',
initial: entry.subjects.toSet(),
);
if (picked == null || !mounted) return;
setState(() => _saving = true);
try {
await CheatService.setSubjects(widget.exam, widget.student.id, picked);
if (mounted) Navigator.pop(context, true);
} catch (e) {
if (mounted) {
setState(() {
_saving = false;
_error = '$e'.replaceFirst('Exception: ', '');
});
}
}
}

({Map<String, double> marks, bool ok}) _read() {
final out = <String, double>{};
var ok = true;
_ctrl.forEach((k, c) {
final t = c.text.trim();
if (t.isEmpty || _isAbsentText(t)) return;
final v = double.tryParse(t);
if (v == null || v < minMarkOf(widget.exam, _form) || v > maxMarkOf(widget.exam, _form)) {
ok = false;
} else {
out[k] = v;
}
});
return (marks: out, ok: ok);
}

Future<void> _save() async {
// a cheated student has nothing to save (the stored marks stay untouched)
if (CheatService.isCheated(widget.exam, widget.student.id)) {
Navigator.pop(context, false);
return;
}
final r = _read();
if (!r.ok) {
setState(() => _error = 'Fix the marks shown in red (${_fmtMark(minMarkOf(widget.exam, _form))} to ${_fmtMark(maxMarkOf(widget.exam, _form))}).');
return;
}
setState(() {
_saving = true;
_error = null;
});
try {
await _service.save(widget.student, widget.exam, {..._hidden, ...r.marks});
if (mounted) Navigator.pop(context, true);
} catch (e) {
if (mounted) {
setState(() {
_saving = false;
_error = '$e'.replaceFirst('Exception: ', '');
});
}
}
}

@override
Widget build(BuildContext context) {
final r = _read();
final total = r.marks.values.fold(0.0, (a, b) => a + b);
final avg = r.marks.isEmpty ? null : total / r.marks.length;
final g = avg == null
? null
    : _gradeOf(avg, max: _gradeMax(widget.exam, widget.form ?? ''));

return AlertDialog(
title: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
Text(widget.student.name,
style: const TextStyle(fontSize: 18, fontWeight: FontWeight.w700)),
const SizedBox(height: 2),
Text(
'${widget.sectionLabel.isEmpty ? '' : '${widget.sectionLabel} · '}${widget.exam}',
style: TextStyle(fontSize: 13, color: Colors.grey.shade700)),
]),
content: SizedBox(
width: 460,
child: _loading
? const SizedBox(
height: 120, child: Center(child: CircularProgressIndicator()))
    : SingleChildScrollView(
child: Column(mainAxisSize: MainAxisSize.min, children: [
Wrap(spacing: 12, runSpacing: 12, children: [
for (final subject in _ctrl.keys)
SizedBox(
width: 136,
child: Builder(builder: (_) {
final c = _ctrl[subject]!;
final t = c.text.trim();
final locked =
SubjectLockService.isComplete(widget.exam, subject, _form);
final v = double.tryParse(t);
final bad =
t.isNotEmpty && !_isAbsentText(t) && (v == null || v < minMarkOf(widget.exam, _form) || v > maxMarkOf(widget.exam, _form));
return TextField(
controller: c,
enabled: !_saving,
readOnly: _isAbsentText(t) || locked,
canRequestFocus: !_isAbsentText(t) && !locked,
style: _isAbsentText(t)
? TextStyle(
color: isNewText(t) ? kNewColor : kRed,
fontWeight: FontWeight.w700)
    : null,
keyboardType: const TextInputType.numberWithOptions(
decimal: true),
inputFormatters: [
FilteringTextInputFormatter.allow(RegExp(r'[0-9.]')),
],
onChanged: (_) => setState(() => _error = null),
decoration: InputDecoration(
labelText: subject,
border: const OutlineInputBorder(),
suffixIcon: locked
? const Tooltip(
message: 'Complete: the marks of this subject are closed',
child: Icon(Icons.lock_outline, size: 16))
    : null,
filled: _isAbsentText(t) || locked,
fillColor: (locked && !_isAbsentText(t))
? const Color(0xFFEEEEEE)
    : isNewText(t)
? const Color(0xFFE3F2FD)
    : const Color(0xFFFDECEA),
enabledBorder: _isAbsentText(t)
? OutlineInputBorder(
borderSide: BorderSide(
color: isNewText(t) ? kNewColor : kRed, width: 1.5))
    : null,
isDense: true,
errorText: bad ? '${_fmtMark(minMarkOf(widget.exam, _form))}–${_fmtMark(maxMarkOf(widget.exam, _form))}' : null,
),
);
}),
),
]),
if (_ctrl.keys
    .any((s) => SubjectLockService.isComplete(widget.exam, s, _form)))
Padding(
padding: const EdgeInsets.only(top: 8),
child: Text(
'Subjects with a lock are Complete. They can be reopened in the Schedule tab.',
style: TextStyle(fontSize: 12, color: Colors.grey.shade700)),
),
const SizedBox(height: 14),
Container(
width: double.infinity,
padding: const EdgeInsets.all(12),
decoration: BoxDecoration(
color: Colors.grey.shade100,
borderRadius: BorderRadius.circular(10),
),
child: Row(
mainAxisAlignment: MainAxisAlignment.spaceAround,
children: [
_sum('Subjects', '${r.marks.length}'),
_sum('Total', _fmtMark(total)),
_sum('Average',
avg == null ? '–' : _fmtMark(double.parse(avg.toStringAsFixed(1)))),
_sum('Grade', g ?? '–',
color: g == null ? null : _gradeColor(g)),
],
),
),
if (_error != null)
Padding(
padding: const EdgeInsets.only(top: 10),
child: Text(_error!, style: const TextStyle(color: kRed)),
),
]),
),
),
actions: [
if (!_loading &&
_admin &&
(CheatService.byExam.value[widget.exam]?.containsKey(widget.student.id) ?? false))
TextButton(
onPressed: _saving ? null : _editCheatSubjects,
child: const Text('Cheated subjects',
style: TextStyle(color: kCheatColor)),
),
if (!_loading)
TextButton(
onPressed: _saving ? null : () => setState(() {
for (final c in _ctrl.values) {
c.clear();
}
}),
child: const Text('Clear all'),
),
TextButton(
onPressed: _saving ? null : () => Navigator.pop(context),
child: const Text('Cancel')),
FilledButton(
onPressed: (_saving || _loading) ? null : _save,
child: _saving
? const SizedBox(
width: 16,
height: 16,
child: CircularProgressIndicator(strokeWidth: 2))
    : const Text('Save'),
),
],
);
}

Widget _sum(String label, String value, {Color? color}) =>
Column(mainAxisSize: MainAxisSize.min, children: [
Text(value,
style: TextStyle(
fontSize: 19, fontWeight: FontWeight.w800, color: color)),
Text(label, style: TextStyle(fontSize: 11.5, color: Colors.grey.shade700)),
]);
}

String? _activityUid; // last account whose login was written to the log

Future<void> main() async {
WidgetsFlutterBinding.ensureInitialized();
try {
await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
schoolLogo.start(); // so the login screen can show the logo
// Keep the app settings in sync while somebody is signed in.
FirebaseAuth.instance.authStateChanges().listen((user) {
if (user == null) {
appSettings.stop();
stopPresence();
_activityUid = null;
} else {
appSettings.start();
schoolLogo.start(); // retry if it needed a signed-in user
if (_activityUid != user.uid) {
_activityUid = user.uid;
logActivity('login', user: user); // activity log + online marker
startPresence();
}
}
});
runApp(const ExamManagerApp());
} catch (e) {
// Show startup errors on screen instead of a blank page.
runApp(MaterialApp(
home: Scaffold(
body: Center(
child: Padding(
padding: const EdgeInsets.all(24),
child: SelectableText('Startup error:\n\n$e',
style: const TextStyle(color: Colors.red, fontSize: 16)),
),
),
),
));
}
}

class LoginScreen extends StatefulWidget {
const LoginScreen({super.key});
@override
State<LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends State<LoginScreen> {
final _email = TextEditingController();
final _password = TextEditingController();
final _name = TextEditingController();
final _phone = TextEditingController();
bool _busy = false;
bool _hide = true;
bool _signUp = false; // false = sign in, true = create account
int _step = 0; // sign up: 0 = email + password, 1 = fill in the profile form
String _role = 'Teacher'; // 'Teacher' or 'Student'
final _subjects = <String>{}; // teacher: subjects taught
final _forms = <String>{}; // teacher: forms taught
String? _studentForm; // student: own form (optional)
String? _error;

@override
void dispose() {
_email.dispose();
_password.dispose();
_name.dispose();
_phone.dispose();
super.dispose();
}

/// "Forgot password?": sends a reset link to the email address.
Future<void> _forgotPassword() async {
final typed = _email.text.trim();
final box = TextEditingController(text: typed.contains('@') ? typed : '');
final isPhone = typed.isNotEmpty && !typed.contains('@');
final messenger = ScaffoldMessenger.of(context);
final email = await showDialog<String>(
context: context,
builder: (ctx) => AlertDialog(
title: const Text('Forgot password'),
content: SizedBox(
width: 380,
child: Column(mainAxisSize: MainAxisSize.min, children: [
Align(
alignment: Alignment.centerLeft,
child: Text(
isPhone
? 'Students sign in with the phone number and have no email. '
'Ask your teacher or the administrator to reset your '
'password. Teachers and staff: enter your email below.'
    : 'Enter your email address. We will send you a link to '
'choose a new password.',
style: const TextStyle(fontSize: 13)),
),
const SizedBox(height: 12),
TextField(
controller: box,
autofocus: true,
keyboardType: TextInputType.emailAddress,
onSubmitted: (v) => Navigator.pop(ctx, v.trim()),
decoration: const InputDecoration(
labelText: 'Email', border: OutlineInputBorder()),
),
]),
),
actions: [
TextButton(
onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
FilledButton(
onPressed: () => Navigator.pop(ctx, box.text.trim()),
child: const Text('Send link')),
],
),
);
box.dispose();
if (email == null) return;
if (email.isEmpty || !email.contains('@') || !email.contains('.')) {
messenger.showSnackBar(
const SnackBar(content: Text('Enter a valid email address.')));
return;
}
try {
await FirebaseAuth.instance.sendPasswordResetEmail(email: email);
messenger.showSnackBar(SnackBar(
content: Text('If $email has an account, a reset link was sent. '
'Check the inbox and the spam folder.')));
} on FirebaseAuthException catch (e) {
messenger.showSnackBar(SnackBar(
content: Text(e.code == 'invalid-email'
? 'This email address is not valid.'
    : e.code == 'too-many-requests'
? 'Too many attempts. Try again later.'
    : (e.message ?? e.code))));
} catch (e) {
messenger.showSnackBar(SnackBar(content: Text('Failed: $e')));
}
}

/// Sign up, step 1 -> 2: check the email and password, then show the form.
void _next() {
final email = _email.text.trim();
if (email.isEmpty || !email.contains('@') || !email.contains('.')) {
setState(() => _error = 'Invalid email address.');
return;
}
if (_password.text.length < 6) {
setState(() => _error = 'Password must be at least 6 characters.');
return;
}
setState(() {
_error = null;
_step = 1;
});
}

/// First sign in of a teacher added by the administrator: the email saved
/// in Teachers is both the email and the password. Signs in (or creates the
/// account the first time) only when that email is in the Teachers list.
/// Returns false when this email is not a registered teacher.
Future<bool> _teacherEmailLogin(String rawEmail) async {
final email = rawEmail.trim().toLowerCase();
final auth = FirebaseAuth.instance;
bool notFound(String c) =>
c == 'invalid-credential' || c == 'wrong-password' || c == 'user-not-found';
// The account may already exist with the lower-case email as password.
try {
await auth.signInWithEmailAndPassword(email: email, password: email);
return true;
} on FirebaseAuthException catch (e) {
if (!notFound(e.code)) rethrow;
}
signUpBusy.value = true; // keep the login screen until the profile exists
UserCredential cred;
try {
cred = await auth.createUserWithEmailAndPassword(
email: email, password: email);
} on FirebaseAuthException catch (e) {
// the account exists with another password: a normal wrong password
if (e.code == 'email-already-in-use') return false;
rethrow;
}
final user = cred.user!;
try {
final t = await findTeacherByEmail(email);
if (t == null) {
// not a registered teacher: no account must be left behind
try {
await user.delete();
} catch (_) {
await auth.signOut();
}
return false;
}
final usersCol = FirebaseFirestore.instance.collection('users');
// The administrator may already have set the role / pages of this
// person in Settings (user entry created with the teacher record).
final keep = <String, dynamic>{};
var hadPlaceholder = false;
if (t.id != user.uid) {
try {
final ph = await usersCol.doc(t.id).get();
if (ph.exists) {
hadPlaceholder = true;
final m = ph.data() ?? {};
if (UserProfile.roles.contains('${m['role']}')) {
keep['role'] = m['role'];
}
if (m['access'] is List) keep['access'] = m['access'];
}
} catch (_) {}
}
await usersCol.doc(user.uid).set({
'role': 'teacher',
'name': t.name,
'email': email,
'createdAt': FieldValue.serverTimestamp(),
...keep,
});
if (hadPlaceholder) {
try {
await usersCol.doc(t.id).delete();
} catch (_) {}
}
return true;
} catch (e) {
debugPrint('Teacher first login failed: $e');
try {
await user.delete();
} catch (_) {
await auth.signOut();
}
loginNotice.value = 'Could not link this email to a teacher record. '
'Check the Firestore rules for "teachers" and "users".\n$e';
return false;
}
}

/// First sign in of a student from an uploaded list: the phone number is
/// the username and the password. Creates the login account the first time,
/// only when a student with this phone number exists, and links it to that
/// student. Returns false when no student has this phone number.
Future<bool> _studentPhoneLogin(String digits) async {
final auth = FirebaseAuth.instance;
final email = studentEmailFor(digits);
signUpBusy.value = true; // keep the login screen until the profile exists
UserCredential cred;
try {
cred = await auth.createUserWithEmailAndPassword(
email: email, password: digits);
} on FirebaseAuthException catch (e) {
if (e.code == 'email-already-in-use') return false; // wrong password
rethrow;
}
final user = cred.user!;
Future<void> undo() async {
try {
await user.delete();
} catch (_) {
await auth.signOut();
}
}

try {
final db = FirebaseFirestore.instance;
final q = await db
    .collection('students')
    .where('phone', isEqualTo: digits)
    .get();
final free = [
for (final d in q.docs)
if ('${d.data()['accountUid'] ?? ''}'.isEmpty ||
d.data()['accountUid'] == user.uid)
d,
]..sort((a, b) => '${a.data()['name']}'
    .toLowerCase()
    .compareTo('${b.data()['name']}'.toLowerCase()));
if (free.isEmpty) {
await undo(); // no student has this number: leave no account behind
return false;
}
final st = free.first;
var form = '';
try {
final sec =
await db.collection('sections').doc('${st.data()['sectionId']}').get();
form = '${sec.data()?['form'] ?? ''}';
} catch (_) {}
final batch = db.batch();
batch.update(st.reference, {'accountUid': user.uid});
batch.set(db.collection('users').doc(user.uid), {
'role': 'student',
'name': '${st.data()['name'] ?? ''}',
'email': email,
'phone': digits,
'studentId': st.id,
if (form.isNotEmpty) 'form': form,
'createdAt': FieldValue.serverTimestamp(),
});
await batch.commit();
return true;
} catch (e) {
debugPrint('Student first login failed: $e');
await undo();
loginNotice.value = 'Could not link this phone number to a student. '
'Check the Firestore rules for "students" and "users".\n$e';
return false;
}
}

Future<void> _submit() async {
if (_signUp && _step == 0) {
_next();
return;
}
if (_signUp && _role == 'Teacher' && _name.text.trim().isEmpty) {
setState(() => _error = 'Please enter your full name.');
return;
}
if (_signUp && _role == 'Teacher' && (_subjects.isEmpty || _forms.isEmpty)) {
setState(() =>
_error = 'Choose at least one subject and one form you teach.');
return;
}
setState(() {
_busy = true;
_error = null;
});
loginNotice.value = null;
if (_signUp) signUpBusy.value = true;
try {
if (_signUp) {
// Read everything first: this screen is replaced as soon as the
// account exists.
final email = _email.text.trim();
final isTeacherRole = _role == 'Teacher';
final name = isTeacherRole
? _name.text.trim()
    : email.split('@').first; // a student picks the real name next
final phone = _phone.text.trim();
final isTeacher = _role == 'Teacher';
final subjects = [
for (final x in ExamService.subjects)
if (_subjects.contains(x)) x
];
final forms = [
for (final x in ExamService.forms)
if (_forms.contains(x)) x
];
final studentForm = _studentForm;

final cred = await FirebaseAuth.instance.createUserWithEmailAndPassword(
email: email,
password: _password.text,
);
final uid = cred.user!.uid;
try {
// The profile first: it decides which pages the person can see.
await FirebaseFirestore.instance.collection('users').doc(uid).set({
'role': isTeacher ? 'teacher' : 'student',
'name': name,
'email': email,
'approved': false, // an administrator must approve this account first
if (!isTeacher && studentForm != null) 'form': studentForm,
'createdAt': FieldValue.serverTimestamp(),
});
if (isTeacher) {
// Goes to the Teachers list; the document id is the account id.
await TeacherService().save(TeacherInfo(
id: uid,
name: name,
role: 'Teacher',
phone: phone,
email: email,
subjects: subjects,
forms: forms,
assignments: {for (final s in subjects) s: forms},
));
}
} catch (e) {
debugPrint('Profile could not be saved: $e');
// Undo the sign up: an account without a profile must not exist.
try {
await FirebaseFirestore.instance
    .collection('users')
    .doc(uid)
    .delete();
} catch (_) {}
try {
await FirebaseFirestore.instance
    .collection('teachers')
    .doc(uid)
    .delete();
} catch (_) {}
try {
await cred.user!.delete();
} catch (_) {
await FirebaseAuth.instance.signOut();
}
loginNotice.value = 'The account could not be created because the '
'profile could not be saved. Check the Firestore rules for '
'"users" and "teachers".\n$e';
}
} else {
var typedEmail = _email.text.trim();
var typedPassword = _password.text;
// A student signs in with the phone number as username AND password.
String? studentPhone;
if (typedEmail.isNotEmpty && !typedEmail.contains('@')) {
studentPhone = phoneDigits(typedEmail);
if (studentPhone == null) {
throw FirebaseAuthException(code: 'invalid-email');
}
typedEmail = studentEmailFor(studentPhone);
typedPassword = phoneDigits(typedPassword) ?? typedPassword;
}
try {
await FirebaseAuth.instance.signInWithEmailAndPassword(
email: typedEmail,
password: typedPassword,
);
} on FirebaseAuthException catch (e) {
// A teacher added by the administrator signs in with the email that
// was saved in Teachers, typed in BOTH the email and password fields.
final wrongLogin = e.code == 'invalid-credential' ||
e.code == 'wrong-password' ||
e.code == 'user-not-found';
final sameAsEmail = typedEmail.isNotEmpty &&
_password.text.trim().toLowerCase() == typedEmail.toLowerCase();
if (wrongLogin && studentPhone != null && typedPassword == studentPhone) {
// First sign in of an uploaded student: the account is created now.
final ok = await _studentPhoneLogin(studentPhone);
if (!ok) rethrow;
} else if (wrongLogin && sameAsEmail) {
final ok = await _teacherEmailLogin(typedEmail);
if (!ok) rethrow;
} else {
rethrow;
}
}
// signed in: let the browser / phone save the login details
TextInput.finishAutofillContext();
}
} on FirebaseAuthException catch (e) {
setState(() {
_error = switch (e.code) {
'invalid-credential' ||
'wrong-password' ||
'user-not-found' =>
'Wrong email or password.',
'invalid-email' => 'Invalid email address or phone number.',
'email-already-in-use' =>
'This email already has an account. Please sign in.',
'weak-password' => 'Password must be at least 6 characters.',
'too-many-requests' => 'Too many attempts. Try again later.',
_ => e.message ?? e.code,
};
// a problem with the email / password: go back to the first step
if (_signUp) _step = 0;
});
} finally {
signUpBusy.value = false;
if (mounted) setState(() => _busy = false);
}
}

