_signUp = !_signUp;
_step = 0;
_error = null;
}),
child: Text(_signUp
? 'Already have an account? Sign in'
    : "Don't have an account? Sign up"),
),
]),
),
),
),
),
),
);
}
}

class ExamManagerApp extends StatelessWidget {
const ExamManagerApp({super.key});

@override
Widget build(BuildContext context) {
return MaterialApp(
title: 'Exam Manager',
debugShowCheckedModeBanner: false,
theme: ThemeData(
useMaterial3: true,
colorSchemeSeed: const Color(0xFF3498DB),
scaffoldBackgroundColor: const Color(0xFFF2F2F2),
),
home: StreamBuilder<User?>(
stream: FirebaseAuth.instance.authStateChanges(),
builder: (context, snap) {
if (snap.connectionState == ConnectionState.waiting) {
return const Scaffold(
body: Center(child: CircularProgressIndicator()));
}
if (!snap.hasData) return const LoginScreen();
return ValueListenableBuilder<bool>(
valueListenable: signUpBusy,
builder: (context, busy, _) => busy
? const Scaffold(
body: Center(child: CircularProgressIndicator()))
    : const _ApprovalGate(child: _ScopeGate(child: HomeScreen())),
);
},
),
);
}
}

// ======================= USERS & PERMISSIONS (Settings) =======================

/// Administrator only: default access per role and the access of each user.
class _PermissionsCard extends StatefulWidget {
/// 0 = everything, 1 = the users list only, 2 = the default access only.
final int part;
const _PermissionsCard({this.part = 0});

@override
State<_PermissionsCard> createState() => _PermissionsCardState();
}

class _PermissionsCardState extends State<_PermissionsCard> {
final _search = TextEditingController();
String _roleFilter = 'all'; // all | admin | teacher | student | unapproved

@override
void dispose() {
_search.dispose();
super.dispose();
}

static bool _teachersSynced = false;

/// For a teacher without an account the user document may not exist yet:
/// the first change creates it with the name and email.
static Map<String, dynamic> _base(UserProfile u) => u.pending
? {
'role': u.role,
'name': u.name,
'email': u.email.trim().toLowerCase(),
'pendingLogin': true,
}
    : <String, dynamic>{};

static void _toast(BuildContext c, String m) =>
ScaffoldMessenger.of(c).showSnackBar(SnackBar(content: Text(m)));

Widget _pageChips(List<String> selected, ValueChanged<List<String>> onChange,
{bool enabled = true}) =>
Wrap(spacing: 6, runSpacing: 6, children: [
for (final p in AppPages.all)
FilterChip(
label: Text(AppPages.labels[p]!),
selected: selected.contains(p),
onSelected: enabled
? (on) => onChange([
for (final x in AppPages.all)
if (x == p ? on : selected.contains(x)) x
])
    : null,
),
]);

/// Removes the user from the list (and the Teachers list). The login
/// account itself stays in Firebase Authentication; if the person signs in
/// again they come back as unapproved and need a new approval.
Future<void> _deleteUser(
BuildContext context, UserProfile u, TeacherInfo? rec) async {
final who = u.name.isEmpty ? (u.email.isEmpty ? u.uid : u.email) : u.name;
final ok = await showDialog<bool>(
context: context,
builder: (ctx) => AlertDialog(
title: const Text('Delete this user?'),
content: Text('$who will be removed from the users list'
'${rec != null ? ' and from the Teachers list' : ''}. '
'If this person signs in again, an administrator must approve '
'the account again.'),
actions: [
TextButton(
onPressed: () => Navigator.pop(ctx, false),
child: const Text('Cancel')),
FilledButton(
style: FilledButton.styleFrom(backgroundColor: Colors.red),
onPressed: () => Navigator.pop(ctx, true),
child: const Text('Delete')),
],
),
);
if (ok != true || !context.mounted) return;
await _run(context, () async {
final db = FirebaseFirestore.instance;
await db.collection('users').doc(u.uid).delete();
if (rec != null) await db.collection('teachers').doc(rec.id).delete();
if (u.role == 'student' && u.studentId.isNotEmpty) {
try {
// free the student record so it can be linked again
await db
    .collection('students')
    .doc(u.studentId)
    .update({'accountUid': FieldValue.delete()});
} catch (_) {}
}
if (context.mounted) _toast(context, '$who was deleted.');
});
}

Future<void> _run(BuildContext c, Future<void> Function() f) async {
try {
await f();
} catch (e) {
if (c.mounted) _toast(c, 'Failed: $e');
}
}

