FilledButton.tonal(
style: FilledButton.styleFrom(
visualDensity: VisualDensity.compact),
onPressed: () => _run(
context,
() => users.doc(u.uid).update(
{'approved': true, 'rejected': FieldValue.delete()})),
child: const Text('Approve')),
]),
